  ('L3 — Advanced', 'Troubleshooting', 'Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 'Free - Udemy', 'core', 2.0, 'Free - Udemy', 'Leads a systemic initiative that improves the support function''s diagnostic capability, not just an individual case.', 'principal', 'https://skedulo.udemy.com/course/from-engineer-to-technical-manager-a-survival-guide/', 53),
  ('L2 — Intermediate', 'Custom vs Core', 'Skedulo API Overview', 'developer.skedulo.com', 'core', 3.0, 'Free (internal)', 'Explains what the Skedulo API supports — GraphQL data access, job/resource management, dispatch notifications, optimisation — and knows which deeper guide (REST, GraphQL, best practices, date formats) to open next.', 'middle', 'https://docs.skedulo.com/developer-guides/integration-and-automation/api-overview', 54),
  ('L2 — Intermediate', 'Custom vs Core', 'API Basics', 'Salesforce Trailhead', 'core', 1.5, 'Free', 'Explains the difference between declarative configuration and code-level customisation when triaging a ticket.', 'middle', 'https://trailhead.salesforce.com/content/learn/modules/api_basics', 55),
  ('L2 — Intermediate', 'Custom vs Core', 'Skedulo CLI', 'docs.skedulo.com', 'core', 3.0, 'Free (internal)', 'Installs, authenticates, and uses the Skedulo CLI to create and manage custom artifacts — fields, objects, functions, webhooks, pages — and builds/deploys a package.', 'middle', 'https://docs.skedulo.com/developer-guides/cli/', 56),
  ('L3 — Advanced', 'Custom vs Core', 'Manage and control access', 'docs.skedulo.com', 'core', 1.5, 'Free', 'Automates user account provisioning via API and designs record-level access policies that control which data specific users can see.', 'senior', 'https://docs.skedulo.com/developer-guides/manage-and-control-access/', 57),
  ('L3 — Advanced', 'Custom vs Core', 'Advanced webhook scheduling and triggered-action design', 'developer.skedulo.com', 'core', 2.0, 'Free (internal)', 'Acts as the definitive escalation point for boundary cases spanning standard product behaviour and customer-specific automation.', 'principal', 'https://docs.skedulo.com/developer-guides/integration-and-automation/webhooks-and-triggered-actions', 58),
