-- Skill tags (courses.skills) for the 55 new courses, mapped onto Core
-- Competency's existing 8-skill taxonomy — same tab-to-skill mapping
-- already used for the Intern and Junior tiers (Troubleshooting ->
-- Technical Troubleshooting, Custom vs Core -> Skedulo Pulse Platform
-- Fundamentals, Process and Procedures / SLAs and Deliverables -> Support
-- Process & SLAs, Tools and Systems -> Support Tooling & Systems, Incident
-- Mgmt & Escalation -> Incident Management & Escalation, Culture Champion /
-- Growth and Learning -> Growth Mindset & Feedback Culture,
-- Cross-Functional Collaboration / Customer First mindset ->
-- Customer-Centered Communication, Performance Excellence / Change Driver &
-- Innovator -> Performance & Innovation). Same re-runnable UPDATE-by-title
-- pattern as every other skills block in this track, scoped by title +
-- track_id.
update courses set skills = v.skills
from (values
  ('Debugging Tools and Techniques for the Lightning Platform', array['Technical Troubleshooting']::text[]),
