-- Wrap-up quiz content — 560 questions across the 55 new courses (10 each,
-- except 'Crisis Communication...', which carries 20 — see file header).
-- Imported from "Quizzes - Specialist + Senior + Principal.xlsx", matched
-- to courses positionally (see file header) rather than by title or URL
-- text alone, since several of this workbook's own titles differ from the
-- roadmap sheet's by capitalization or a trailing "(Overview)"/qualifier
-- that would make a plain text match unreliable at this scale. `options` is
-- a jsonb array (`[{"label":"A","text":"..."}, ...]`, normally 4 options,
-- A-D). One question (Troubleshooting -> "Skedulo Optimization API", Q6)
-- carried a spurious 5th option lettered E with text "N/A" — dropped on the
-- way in, same as this file's usual practice isn't to import empty/filler
-- choices. correct_answer is normalized to a bare option label throughout,
-- same as every other quiz import in this track.
insert into course_quiz_questions (course_id, position, question, options, correct_answer, rationale)
select c.id, v.position, v.question, v.options, v.correct_answer, v.rationale
from (values
  ('Debugging Tools and Techniques for the Lightning Platform', 1, 'What are the eight debug log levels available in Salesforce, from least to most detailed?', '[{"label": "A", "text": "NONE, ERROR, WARN, INFO, DEBUG, FINE, FINER, FINEST"}, {"label": "B", "text": "NONE, WARN, ERROR, INFO, DEBUG, FINE, FINER, FINEST"}, {"label": "C", "text": "ERROR, WARN, INFO, DEBUG, FINE, FINER, FINEST, NONE"}, {"label": "D", "text": "DEBUG, INFO, WARN, ERROR, FINE, FINER, FINEST, NONE"}]'::jsonb, 'A', 'The module lists eight logging levels in exactly this order.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 2, 'What is the maximum size of a single debug log, and how much does an org retain in total?', '[{"label": "A", "text": "20 MB per log; 1,000 MB total per org"}, {"label": "B", "text": "5 MB per log; 100 MB total per org"}, {"label": "C", "text": "50 MB per log; 500 MB total per org"}, {"label": "D", "text": "There is no size limit on debug logs"}]'::jsonb, 'A', 'The module states each log must stay under 20 MB, with orgs retaining up to 1,000 MB total.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 3, 'Which statement writes a message to the debug log with a controllable verbosity level?', '[{"label": "A", "text": "System.debug(''message'')"}, {"label": "B", "text": "System.log(''message'')"}, {"label": "C", "text": "Debug.write(''message'')"}, {"label": "D", "text": "Trace.emit(''message'')"}]'::jsonb, 'A', 'The module describes logging via System.debug(''message'') with an optional logging level.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 4, 'What tool lets you examine a debug log after execution, with Timeline and Executed Units tabs?', '[{"label": "A", "text": "Log Inspector"}, {"label": "B", "text": "Developer Console Query Editor"}, {"label": "C", "text": "Checkpoint Manager"}, {"label": "D", "text": "Apex Test Runner"}]'::jsonb, 'A', 'Log Inspector is the console feature for post-execution log analysis, offering Timeline and Executed Units tabs.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 5, 'How do checkpoints differ from traditional breakpoints on the Lightning Platform?', '[{"label": "A", "text": "Checkpoints don''t halt execution, surfacing data via Symbols and Heap tabs without blocking shared resources"}, {"label": "B", "text": "Checkpoints pause execution indefinitely until a developer resumes it"}, {"label": "C", "text": "Checkpoints only work in production orgs, never sandboxes"}, {"label": "D", "text": "Checkpoints replace debug logs entirely"}]'::jsonb, 'A', 'The module frames checkpoints as ''similar to breakpoints'' but non-blocking — a deliberate design choice for the multi-tenant cloud environment.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 6, 'A support engineer needs to inspect a transaction''s state without pausing execution for other orgs sharing the multi-tenant instance. Which tool fits, and why?', '[{"label": "A", "text": "Checkpoints — they surface execution data without blocking shared resources"}, {"label": "B", "text": "Debug logs at FINEST — they always halt execution for inspection"}, {"label": "C", "text": "The breakpoint feature — built for multi-tenant use"}, {"label": "D", "text": "No tool can inspect state without stopping execution"}]'::jsonb, 'A', 'Checkpoints are explicitly positioned as the multi-tenant-safe alternative to breakpoints, since they never halt execution.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 7, 'A customer''s debug log for a complex transaction cuts off partway through. What''s the most likely cause per this module?', '[{"label": "A", "text": "The log exceeded the 20 MB per-log size limit"}, {"label": "B", "text": "The org has too many Apex classes deployed"}, {"label": "C", "text": "FINEST logging is disabled by default"}, {"label": "D", "text": "Debug logs can never be truncated"}]'::jsonb, 'A', 'The module states a hard 20 MB ceiling per log — logging stops once that cap is hit.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 8, 'What does the module say about debugging on the Lightning Platform compared to an environment like Visual Studio?', '[{"label": "A", "text": "Multi-tenant cloud debugging presents unique challenges, contrasted unfavorably with Visual Studio, while acknowledging Salesforce''s ongoing improvements"}, {"label": "B", "text": "They are described as functionally identical"}, {"label": "C", "text": "The Lightning Platform is called strictly superior for all debugging"}, {"label": "D", "text": "The module makes no such comparison"}]'::jsonb, 'A', 'The module explicitly acknowledges this tradeoff rather than claiming Lightning Platform debugging is on par with a dedicated IDE.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 9, 'Before reproducing a customer issue in Developer Console to capture a clean debug log, what should a support engineer do first, per the module?', '[{"label": "A", "text": "Configure log levels and perspectives before execution"}, {"label": "B", "text": "Enable FINEST on every category permanently by default"}, {"label": "C", "text": "Ask the customer to reproduce the issue three times first"}, {"label": "D", "text": "Nothing — log levels cannot be configured in Developer Console"}]'::jsonb, 'A', 'The module emphasizes setting up log levels and perspectives ahead of execution, not capturing logs blind and filtering after the fact.'),
  ('Debugging Tools and Techniques for the Lightning Platform', 10, 'A ticket needs variable-state and heap-usage detail at one specific line, without generating a full verbose debug log. Which tool fits better?', '[{"label": "A", "text": "Checkpoints, since they show Symbols and Heap tab detail at a chosen point without blocking execution"}, {"label": "B", "text": "Debug logs set to NONE"}, {"label": "C", "text": "The Log Inspector Executed Units tab alone"}, {"label": "D", "text": "Heap data cannot be inspected on the Lightning Platform"}]'::jsonb, 'A', 'Checkpoints are the targeted, non-blocking tool for exactly this kind of point-in-time state inspection.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 1, 'What are the two primary ways to interact with the Skedulo API described in the API Overview?', '[{"label": "A", "text": "REST API and GraphQL"}, {"label": "B", "text": "SOAP API and REST API"}, {"label": "C", "text": "GraphQL and Webhooks"}, {"label": "D", "text": "CLI and REST API"}]'::jsonb, 'A', 'The overview names REST API (Skedulo REST API) and GraphQL (the Skedulo GraphQL schema) as the two approaches.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 2, 'Which of these is NOT something the Skedulo API overview lists as a capability?', '[{"label": "A", "text": "Directly modifying a customer''s Salesforce org page layouts"}, {"label": "B", "text": "Full data access to standard and custom objects via GraphQL"}, {"label": "C", "text": "Creating jobs and managing scheduling"}, {"label": "D", "text": "Dispatching jobs to resources and sending SMS/push notifications"}]'::jsonb, 'A', 'The overview lists job creation/scheduling, dispatch+notifications, optimization access, and GraphQL data access — modifying Salesforce page layouts is outside the Skedulo API scope described here.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 3, 'Where would a developer find the definitive list of every supported Skedulo API endpoint?', '[{"label": "A", "text": "The API Reference Guide"}, {"label": "B", "text": "The Optimization getting-started guide"}, {"label": "C", "text": "The Skedulo CLI quick reference"}, {"label": "D", "text": "The Object Reference overview page alone"}]'::jsonb, 'A', 'The overview points to a dedicated API Reference Guide as the full list of supported APIs.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 4, 'Which linked document does the overview point to for writing efficient, high-performing integrations?', '[{"label": "A", "text": "The API Usage Best Practices guide"}, {"label": "B", "text": "The CLI troubleshooting guide"}, {"label": "C", "text": "The Optimization API getting-started guide"}, {"label": "D", "text": "The GraphQL query limits page only"}]'::jsonb, 'A', 'The overview specifically references an "API Usage Best Practices" doc for efficient, performant API interactions.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 5, 'The API overview also links to guidance on which data-formatting topic that commonly causes integration bugs?', '[{"label": "A", "text": "Valid Date and DateTime formats"}, {"label": "B", "text": "Currency localisation formats"}, {"label": "C", "text": "Time zone abbreviation standards"}, {"label": "D", "text": "Phone number formatting"}]'::jsonb, 'A', 'A "Valid Date and DateTime formats" reference is explicitly linked from the API overview.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 6, 'A customer integration needs to pull nearly all fields across several related custom and standard objects in one efficient call. Which approach best fits, per the overview?', '[{"label": "A", "text": "GraphQL, since it provides full data access to standard and custom objects"}, {"label": "B", "text": "REST API only, since GraphQL cannot access custom objects"}, {"label": "C", "text": "Neither API supports custom objects"}, {"label": "D", "text": "The Optimization API, since it replaces general data access"}]'::jsonb, 'A', 'The overview specifically calls out GraphQL for full data access across standard and custom objects.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 7, 'A customer''s external system is misparsing dates coming from the Skedulo API. Where should support point them first?', '[{"label": "A", "text": "The Valid Date and DateTime formats reference"}, {"label": "B", "text": "The Optimization API getting-started guide"}, {"label": "C", "text": "The API Reference Guide authentication section"}, {"label": "D", "text": "The Skedulo CLI working-with-functions page"}]'::jsonb, 'A', 'This exact topic is linked directly from the API overview as the reference for date/time formatting questions.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 8, 'A customer asks whether the API can text a resource automatically when a job is dispatched. What does the overview say?', '[{"label": "A", "text": "Yes — dispatching jobs to resources and managing notifications via SMS or push is a listed capability"}, {"label": "B", "text": "No — SMS requires a separate third-party integration"}, {"label": "C", "text": "Only push notifications are supported, never SMS"}, {"label": "D", "text": "Only the Optimization API can trigger notifications"}]'::jsonb, 'A', 'The overview explicitly lists SMS/push notification management alongside job dispatch as an API capability.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 9, 'Besides data access and scheduling, what other Skedulo capability does the overview say is reachable via the API?', '[{"label": "A", "text": "The optimization engine"}, {"label": "B", "text": "The billing engine"}, {"label": "C", "text": "The Salesforce Metadata engine"}, {"label": "D", "text": "A machine-translation engine"}]'::jsonb, 'A', 'The overview lists "optimization engine access" among the things the Skedulo API exposes.'),
  ('Skedulo Developer Guide — API Overview & REST API reference', 10, 'A teammate asks why anyone would use REST API when GraphQL offers full data access. What is the most accurate answer based on this overview?', '[{"label": "A", "text": "Both are presented as valid, supported approaches — the right choice depends on the integration''s needs, not a strict replacement"}, {"label": "B", "text": "REST API is deprecated and should never be used"}, {"label": "C", "text": "GraphQL cannot be used for any Skedulo object"}, {"label": "D", "text": "There is no meaningful difference between them"}]'::jsonb, 'A', 'The overview presents REST API and GraphQL side by side as two supported approaches rather than one superseding the other.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 1, 'What are the two mechanisms Skedulo provides for integrating with real-time events?', '[{"label": "A", "text": "Triggered Actions and Webhooks"}, {"label": "B", "text": "Webhooks and Polling"}, {"label": "C", "text": "Triggered Actions and the Optimization API"}, {"label": "D", "text": "GraphQL Subscriptions and REST Polling"}]'::jsonb, 'A', 'The overview names Triggered Actions and Webhooks as the two mechanisms for real-time event integration.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 2, 'Which capability is unique to Triggered Actions and NOT available with Webhooks?', '[{"label": "A", "text": "Sending SMS responses and querying additional data post-trigger"}, {"label": "B", "text": "Responding to a data record update"}, {"label": "C", "text": "Deferred/delayed execution"}, {"label": "D", "text": "Accessing previous data on modification"}]'::jsonb, 'A', 'The comparison table shows only Triggered Actions can send SMS responses and query additional data post-trigger; both share record-change response, deferred execution, and access to previous data.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 3, 'Which capability is unique to Webhooks and NOT available with Triggered Actions?', '[{"label": "A", "text": "Inbound SMS triggers and scheduled (cron) execution"}, {"label": "B", "text": "Access to previous data on modification"}, {"label": "C", "text": "Responding to a timer expiration"}, {"label": "D", "text": "Deferred/delayed execution"}]'::jsonb, 'A', 'The comparison table shows only Webhooks support inbound SMS triggers and cron-based scheduled execution.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 4, 'What is mandatory for Triggered Actions and merely recommended for Webhooks, in each configuration?', '[{"label": "A", "text": "A filter"}, {"label": "B", "text": "A GraphQL query"}, {"label": "C", "text": "An SMS template"}, {"label": "D", "text": "A custom header"}]'::jsonb, 'A', 'The overview states a filter is mandatory for triggered actions and recommended (but not required) for webhooks.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 5, 'What authentication is required to configure a webhook or triggered action, and what URL scheme is required?', '[{"label": "A", "text": "An API access token via Authorization: Bearer header, and HTTPS-only URLs"}, {"label": "B", "text": "Basic auth username/password, HTTP or HTTPS accepted"}, {"label": "C", "text": "No authentication required, any URL scheme accepted"}, {"label": "D", "text": "An API key in the URL query string, HTTPS-only"}]'::jsonb, 'A', 'The overview requires a Bearer token for authentication and states only HTTPS URLs are accepted.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 6, 'A customer wants to run an SMS auto-reply workflow triggered by incoming customer text messages. Which mechanism should support recommend?', '[{"label": "A", "text": "Webhooks, since inbound SMS is a Webhooks-only trigger type"}, {"label": "B", "text": "Triggered Actions, since they can send SMS responses"}, {"label": "C", "text": "Either works identically for inbound SMS"}, {"label": "D", "text": "Neither mechanism supports SMS at all"}]'::jsonb, 'A', 'Incoming SMS is listed as a trigger both systems can respond to, but inbound SMS as a webhook-specific trigger type is called out — and Triggered Actions can only send SMS responses, not receive inbound SMS as their distinguishing feature. Webhooks are the mechanism built for inbound SMS handling.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 7, 'A customer needs a nightly cron-style job that pings an external system every night at 2am regardless of any Skedulo data change. Which mechanism supports this natively?', '[{"label": "A", "text": "Webhooks, via scheduled (cron) execution"}, {"label": "B", "text": "Triggered Actions, via deferred execution"}, {"label": "C", "text": "Neither — this requires an external scheduler"}, {"label": "D", "text": "The Optimization API"}]'::jsonb, 'A', 'Scheduled/cron-based execution is listed as a Webhooks-only capability, not available on Triggered Actions.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 8, 'A support engineer is debugging why a Skedulo request never reached a customer endpoint. Which header would help them find the responsible configuration on the Skedulo side?', '[{"label": "A", "text": "Skedulo-Triggeredactionlogid (always present) plus Skedulo-Triggeredactionid or Skedulo-Webhook-Id depending on type"}, {"label": "B", "text": "X-Skedulo-Trace only, present on every request type"}, {"label": "C", "text": "There are no identifying headers sent with these requests"}, {"label": "D", "text": "Only a generic User-Agent header is sent, with no ID"}]'::jsonb, 'A', 'The overview lists these exact headers: Skedulo-Triggeredactionlogid always present, plus a type-specific ID header for triggered actions vs. webhooks.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 9, 'A Skedulo for Salesforce customer wants to configure a webhook or triggered action. What extra prerequisite applies to them specifically?', '[{"label": "A", "text": "They need an API user configured"}, {"label": "B", "text": "They must disable all custom Apex triggers first"}, {"label": "C", "text": "Salesforce customers cannot use webhooks or triggered actions"}, {"label": "D", "text": "They need a dedicated AU-region datastore"}]'::jsonb, 'A', 'The overview notes Skedulo for Salesforce users specifically need an API user configured for these features.'),
  ('Skedulo Developer Guide — Webhooks and Triggered Actions (overview + create a webhook)', 10, 'A customer wants their integration to see the value of a field BEFORE it changed, not just after. Is this possible, and with which mechanism(s)?', '[{"label": "A", "text": "Yes, with either — both Triggered Actions and Webhooks can access previous data on modification"}, {"label": "B", "text": "Yes, but only with Triggered Actions"}, {"label": "C", "text": "Yes, but only with Webhooks"}, {"label": "D", "text": "No, neither mechanism exposes prior field values"}]'::jsonb, 'A', 'The comparison table shows "Access previous data on modification" is supported by both mechanisms.'),
  ('Skedulo Optimization API — Get started with optimization', 1, 'What does Skedulo''s optimization engine fundamentally do?', '[{"label": "A", "text": "Evaluates hundreds of thousands of possible solutions to find near-optimal job/resource assignments given constraints"}, {"label": "B", "text": "Randomly assigns jobs to any available resource"}, {"label": "C", "text": "Only re-sorts existing schedules alphabetically by resource name"}, {"label": "D", "text": "Replaces the need for any resource availability data"}]'::jsonb, 'A', 'The doc describes the engine as evaluating hundreds of thousands of possible solutions to find near-optimal assignments considering skill, availability, location, and travel time.'),
  ('Skedulo Optimization API — Get started with optimization', 2, 'What are the three ways to run optimization, per the getting-started guide?', '[{"label": "A", "text": "Direct scheduling swimlane optimization, recurring optimization via settings, or remote API calls to /optimization"}, {"label": "B", "text": "Only via the mobile app"}, {"label": "C", "text": "Only via a nightly batch job with no manual trigger"}, {"label": "D", "text": "Only via the Skedulo CLI"}]'::jsonb, 'A', 'The doc names these three implementation approaches explicitly.'),
  ('Skedulo Optimization API — Get started with optimization', 3, 'How does the optimization engine treat a job that is already "dispatched" or beyond?', '[{"label": "A", "text": "As immovable — it schedules around it rather than reassigning it"}, {"label": "B", "text": "It always reassigns dispatched jobs first"}, {"label": "C", "text": "Dispatched jobs are excluded from the optimization run entirely and disappear from the schedule"}, {"label": "D", "text": "Dispatched status has no effect on optimization behavior"}]'::jsonb, 'A', 'The doc states jobs at "dispatched" status or beyond are treated as immovable, with the engine scheduling around them.'),
  ('Skedulo Optimization API — Get started with optimization', 4, 'What is the difference between a hard constraint and a soft constraint (objective)?', '[{"label": "A", "text": "Hard constraints are non-negotiable (e.g., tag requirements, travel limits); soft constraints/objectives can be compromised with weighting"}, {"label": "B", "text": "Hard constraints can be violated if the score is high enough; soft constraints never can"}, {"label": "C", "text": "There is no difference — both terms mean the same thing"}, {"label": "D", "text": "Soft constraints only apply to Skedulo for Salesforce tenants"}]'::jsonb, 'A', 'The doc defines hard constraints as non-negotiable limits and soft constraints/objectives as weightable and compromise-able.'),
  ('Skedulo Optimization API — Get started with optimization', 5, 'What defines a "feasible solution" in this optimization model?', '[{"label": "A", "text": "A valid scheduling solution that does not break any hard constraints"}, {"label": "B", "text": "Any solution at all, regardless of constraints"}, {"label": "C", "text": "A solution that maximizes only one objective, ignoring all others"}, {"label": "D", "text": "A solution that has zero travel time"}]'::jsonb, 'A', 'The doc defines a feasible solution exactly this way — it must not violate hard constraints, though it may vary in how well it satisfies objectives.'),
  ('Skedulo Optimization API — Get started with optimization', 6, 'A customer wants optimization to never assign a job to a resource lacking a specific certification, no matter how good the schedule would otherwise be. How should this be modeled?', '[{"label": "A", "text": "As a hard constraint (a required tag), since hard constraints are non-negotiable"}, {"label": "B", "text": "As a soft constraint/objective with high weighting, since it can still be violated if needed"}, {"label": "C", "text": "This cannot be modeled in Skedulo optimization"}, {"label": "D", "text": "As one of the seven objectives with 100% weighting"}]'::jsonb, 'A', 'Required tags are explicitly listed as a hard constraint type — the correct fit for a rule that must never be violated, unlike a weighted objective.'),
  ('Skedulo Optimization API — Get started with optimization', 7, 'What licensing/role prerequisites apply before a team can use Optimization, per the getting-started guide?', '[{"label": "A", "text": "Administrator or Scheduler role, plus optimization is a premium feature requiring additional licensing"}, {"label": "B", "text": "Any logged-in user can enable it with no licensing"}, {"label": "C", "text": "Only Salesforce admins can ever enable it"}, {"label": "D", "text": "It requires no additional license, only a Scheduler role"}]'::jsonb, 'A', 'The doc states Administrator or Scheduler role is required, and that optimization is a premium, additionally-licensed feature.'),
  ('Skedulo Optimization API — Get started with optimization', 8, 'A customer asks how many separate objectives can be weighted in the optimization engine to reflect their business priorities.', '[{"label": "A", "text": "Seven"}, {"label": "B", "text": "Three"}, {"label": "C", "text": "Unlimited"}, {"label": "D", "text": "One — only travel time can be weighted"}]'::jsonb, 'A', 'The doc states there are seven objectives that can be weighted depending on business needs.'),
  ('Skedulo Optimization API — Get started with optimization', 9, 'How does the engine compare multiple feasible solutions to decide which is best?', '[{"label": "A", "text": "By scoring constraint impacts using weighted percentages that total 100%"}, {"label": "B", "text": "By picking the first feasible solution found, with no further comparison"}, {"label": "C", "text": "By always preferring the solution with the fewest total jobs scheduled"}, {"label": "D", "text": "It cannot compare solutions — any feasible solution is returned at random"}]'::jsonb, 'A', 'The doc describes scoring based on weighted percentages summing to 100% to help the engine prioritize among feasible solutions.'),
  ('Skedulo Optimization API — Get started with optimization', 10, 'A customer''s optimization run keeps leaving a specific job unassigned even though several resources appear free on the calendar. What''s a likely explanation worth checking first?', '[{"label": "A", "text": "A hard constraint (e.g., required tags, exclusion lists, travel limits, or availability windows) is ruling out every otherwise-free resource"}, {"label": "B", "text": "The optimization engine ignores resource availability entirely"}, {"label": "C", "text": "Jobs can never be left unassigned by the optimization engine"}, {"label": "D", "text": "The job must already be in dispatched status"}]'::jsonb, 'A', 'Since hard constraints are non-negotiable and rule out any solution that breaks them, an unassigned job despite apparently free resources is a classic sign one or more hard constraints (tags, exclusions, travel, availability) are eliminating every candidate.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 1, 'Who is this course primarily designed for, per the "Who this course is for" section?', '[{"label": "A", "text": "Newly minted technical managers, engineers considering a move into management, and early-career managers"}, {"label": "B", "text": "Only C-level executives at large enterprises"}, {"label": "C", "text": "Recruiters with no engineering background"}, {"label": "D", "text": "Experienced VPs of Engineering with 20+ years of management experience"}]'::jsonb, 'A', 'The course explicitly targets newly minted technical managers, engineers considering the move, and early-career managers looking to improve.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 2, 'Which section of the course is the longest, by both lecture count and running time?', '[{"label": "A", "text": "\"Survival Tips for New Technical Managers\" (11 lectures, 42 minutes)"}, {"label": "B", "text": "\"Wrapping up\" (3 lectures, 4 minutes)"}, {"label": "C", "text": "\"Your Continued Growth as a Manager\" (3 lectures, 8 minutes)"}, {"label": "D", "text": "\"Building and Maintaining Morale\" (6 lectures, 17 minutes)"}]'::jsonb, 'A', 'At 11 lectures and 42 minutes, "Survival Tips for New Technical Managers" is the largest section in the course.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 3, 'What is the instructor''s own background, per the course description?', '[{"label": "A", "text": "He moved from software engineer to manager to senior manager at Amazon, holding patents in machine learning and personalization"}, {"label": "B", "text": "He has never managed a team himself"}, {"label": "C", "text": "He is a career HR generalist with no engineering background"}, {"label": "D", "text": "He only teaches classroom leadership theory with no industry experience"}]'::jsonb, 'A', 'Frank Kane describes his own path from software engineer to senior manager at Amazon''s Seattle HQ, and holds multiple patents in ML and personalization.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 4, 'According to the course, what is the fundamental difference new technical managers must adapt to?', '[{"label": "A", "text": "Managing people is very different from managing machines or engineering systems"}, {"label": "B", "text": "There is no real difference between managing code and managing people"}, {"label": "C", "text": "Management is purely about writing more detailed technical specifications"}, {"label": "D", "text": "Managers should keep doing the same individual-contributor work as before"}]'::jsonb, 'A', 'The course opens with the premise that managing people is a lot different from managing machines, which is the core adjustment new managers must make.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 5, 'Which pair of related skills does the "Hiring and Firing" section address together?', '[{"label": "A", "text": "Recruiting the best people for the team and best practices for letting someone go"}, {"label": "B", "text": "Writing job descriptions only, with no discussion of terminations"}, {"label": "C", "text": "Salary negotiation tactics exclusively"}, {"label": "D", "text": "Onboarding paperwork with no hiring or firing content"}]'::jsonb, 'A', 'The stated learning objectives pair "how to recruit the best people to your team" with "best practices for letting someone go."'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 6, 'What does the "Working with Upper Management" section focus on?', '[{"label": "A", "text": "Building productive relationships with senior management"}, {"label": "B", "text": "Replacing senior management entirely"}, {"label": "C", "text": "Avoiding all contact with executives"}, {"label": "D", "text": "Only how to write performance reviews"}]'::jsonb, 'A', 'One of the course''s stated outcomes is "building productive relationships with senior management," which is the focus of this section.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 7, 'A newly promoted Principal Specialist keeps jumping in to personally fix every escalated ticket instead of directing the team to resolve them. Which stated course outcome most directly addresses this pattern?', '[{"label": "A", "text": "Driving results from a team that are much bigger than what the manager could achieve alone"}, {"label": "B", "text": "Learning to write better individual bug fixes"}, {"label": "C", "text": "Avoiding all delegation to preserve technical credibility"}, {"label": "D", "text": "Optimizing the manager''s own personal ticket-closure rate"}]'::jsonb, 'A', 'The course frames success as driving results "much bigger than what you could have achieved yourself," directly addressing over-reliance on personally fixing everything.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 8, 'A manager''s calendar is suddenly packed with 1:1s, status meetings, and Slack messages after their promotion, leaving no time for deep work. Which explicitly stated course skill addresses this?', '[{"label": "A", "text": "Effective time management — how to handle all those new meetings and messages"}, {"label": "B", "text": "Advanced Excel formulas for scheduling"}, {"label": "C", "text": "A section on writing better code comments"}, {"label": "D", "text": "Learning to decline every meeting invitation without exception"}]'::jsonb, 'A', 'The course explicitly lists "effective time management - how to handle all those new meetings and messages" as one of its outcomes.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 9, 'A team is delivering results but morale is dropping and turnover risk is rising during a high-pressure quarter. Which section is most directly built to address this situation?', '[{"label": "A", "text": "\"Building and Maintaining Morale\""}, {"label": "B", "text": "\"Wrapping up\""}, {"label": "C", "text": "\"Introduction\""}, {"label": "D", "text": "\"Your Continued Growth as a Manager\""}]'::jsonb, 'A', '"Building and Maintaining Morale" (6 lectures, 17 min) is dedicated to keeping a team productive and engaged, which fits a high-pressure, high-turnover-risk scenario.'),
  ('Leading Technical Teams and Driving Engineering Excellence — Search Keywords: "technical leadership for senior engineers"', 10, 'A senior engineer is weighing whether to accept a manager role and wants to understand what the transition actually involves before committing. How does the course describe its usefulness to this person?', '[{"label": "A", "text": "It explicitly says it can help someone who is \"just considering making the move from individual contributor to manager\" understand what they are getting into"}, {"label": "B", "text": "It states the course is only for people who have already been managers for 10+ years"}, {"label": "C", "text": "It refuses to address anyone who has not yet been promoted"}, {"label": "D", "text": "It focuses exclusively on non-technical management roles"}]'::jsonb, 'A', 'The description directly addresses engineers "just considering making the move," offering to help them understand what the role entails before committing.'),
  ('Skedulo API Overview', 1, 'A customer wants to build a custom integration and asks what the Skedulo API can access. What is the accurate scope, per the overview?', '[{"label": "A", "text": "Standard and custom objects (via GraphQL), job creation/scheduling, resource allocation, dispatch/notifications, optimization engine access, and location/travel data"}, {"label": "B", "text": "Only standard objects — custom objects are never exposed via API"}, {"label": "C", "text": "Only read-only access to jobs, with no ability to create or dispatch"}, {"label": "D", "text": "Only the optimization engine, with no direct data access"}]'::jsonb, 'A', 'This matches the full capability list given in the API overview.'),
  ('Skedulo API Overview', 2, 'Which two integration approaches does the overview present as the primary ways to use the Skedulo API?', '[{"label": "A", "text": "REST API and GraphQL"}, {"label": "B", "text": "SOAP and REST"}, {"label": "C", "text": "Webhooks and the CLI"}, {"label": "D", "text": "GraphQL and the Optimization API"}]'::jsonb, 'A', 'The overview names REST API and GraphQL as the two primary approaches.'),
  ('Skedulo API Overview', 3, 'A developer building a heavy custom-object query for a Skedulo for Salesforce customer wants full flexibility to select exactly the fields needed in one call. Which approach best matches the overview''s framing?', '[{"label": "A", "text": "GraphQL, since it provides full data access to standard and custom objects"}, {"label": "B", "text": "REST API exclusively, since GraphQL only works for standard objects"}, {"label": "C", "text": "The Skedulo CLI, since it replaces API queries"}, {"label": "D", "text": "Webhooks, since they can be queried on demand"}]'::jsonb, 'A', 'The overview specifically frames GraphQL as the route to full data access across standard and custom objects.'),
  ('Skedulo API Overview', 4, 'Where does the overview direct a developer for a complete list of every supported API operation?', '[{"label": "A", "text": "The API Reference Guide"}, {"label": "B", "text": "The Optimization API getting-started guide"}, {"label": "C", "text": "The Object Reference overview alone"}, {"label": "D", "text": "The Skedulo CLI quick reference"}]'::jsonb, 'A', 'The overview links out to a dedicated API Reference Guide for the full supported API list.'),
  ('Skedulo API Overview', 5, 'What resource does the overview point to for guidance on writing efficient, high-performing API calls?', '[{"label": "A", "text": "The API Usage Best Practices guide"}, {"label": "B", "text": "The CLI troubleshooting page"}, {"label": "C", "text": "The Object Reference glossary"}, {"label": "D", "text": "The Optimization API extensions page"}]'::jsonb, 'A', 'This is explicitly named as the reference for efficient, performant API interactions.'),
  ('Skedulo API Overview', 6, 'A customization project needs to trigger an SMS the moment a job is dispatched to a resource. Is this achievable via the core API, per the overview?', '[{"label": "A", "text": "Yes — dispatching jobs and managing SMS/push notifications is a listed API capability"}, {"label": "B", "text": "No — SMS requires a bespoke third-party integration outside the API"}, {"label": "C", "text": "Only via the Optimization API, not the general API"}, {"label": "D", "text": "Only push notifications are supported, never SMS"}]'::jsonb, 'A', 'The overview explicitly lists dispatching jobs and managing SMS/push notifications together as an API capability.'),
  ('Skedulo API Overview', 7, 'A customer''s custom integration is misinterpreting timestamps returned by the API. Which linked resource addresses this directly?', '[{"label": "A", "text": "Valid Date and DateTime formats"}, {"label": "B", "text": "API Usage Best Practices"}, {"label": "C", "text": "The API Reference Guide index page"}, {"label": "D", "text": "The Optimization API documentation"}]'::jsonb, 'A', 'This exact topic is linked from the API overview as the reference for date/time formatting.'),
  ('Skedulo API Overview', 8, 'A customization consultant wants to build a feature that reacts automatically to Skedulo record changes (not just query data on demand). Is that in scope for "the API" as described in this overview alone?', '[{"label": "A", "text": "Not directly — reactive/event-driven integration is covered separately under Webhooks and Triggered Actions, not the core API overview"}, {"label": "B", "text": "Yes, the API overview fully covers event-driven triggers"}, {"label": "C", "text": "No such capability exists anywhere in Skedulo"}, {"label": "D", "text": "Only the CLI supports this"}]'::jsonb, 'A', 'The API overview covers data access, scheduling, dispatch, and optimization; reactive event handling is a distinct, separately documented capability (Webhooks/Triggered Actions).'),
  ('Skedulo API Overview', 9, 'Which engine, beyond basic scheduling, does the API overview say is accessible through the API?', '[{"label": "A", "text": "The optimization engine"}, {"label": "B", "text": "The billing/invoicing engine"}, {"label": "C", "text": "A machine-translation engine"}, {"label": "D", "text": "The Salesforce Metadata engine"}]'::jsonb, 'A', '"Optimization engine access" is explicitly listed as an API capability.'),
  ('Skedulo API Overview', 10, 'A support engineer needs to explain to a customization partner why their integration should follow the "API Usage Best Practices" guide rather than just calling endpoints as fast as possible. What is the most accurate reason, per the overview''s framing?', '[{"label": "A", "text": "It exists specifically to guide efficient, performant interactions with the API"}, {"label": "B", "text": "It exists only to document authentication scopes"}, {"label": "C", "text": "It has nothing to do with performance, only styling of requests"}, {"label": "D", "text": "It is deprecated and no longer maintained"}]'::jsonb, 'A', 'The overview describes this guide''s purpose as enabling "efficient and performant interactions" with the API.'),
  ('API Basics', 1, 'Which four APIs make up the core "Salesforce data APIs" this module focuses on?', '[{"label": "A", "text": "REST API, SOAP API, Bulk API, and Pub/Sub API"}, {"label": "B", "text": "REST API, Metadata API, Tooling API, and GraphQL API"}, {"label": "C", "text": "Connect REST API, User Interface API, Bulk API, and SOAP API"}, {"label": "D", "text": "REST API, SOAP API, Apex REST API, and Apex SOAP API"}]'::jsonb, 'A', 'The module names these four as the Salesforce data APIs it focuses on.'),
  ('API Basics', 2, 'Why is Bulk API the right choice for a data migration involving 500,000 records?', '[{"label": "A", "text": "It''s a specialized RESTful API for loading/querying large volumes asynchronously, built for tens of thousands to millions of records"}, {"label": "B", "text": "It''s the only API with authentication"}, {"label": "C", "text": "It processes records synchronously so results are instant"}, {"label": "D", "text": "It only supports SOAP, not REST"}]'::jsonb, 'A', 'The module describes Bulk API as async and purpose-built for very large record volumes (50,000+, up to millions).'),
  ('API Basics', 3, 'Which API uses a WSDL file as a formal contract and is described as great for server-to-server integrations?', '[{"label": "A", "text": "SOAP API"}, {"label": "B", "text": "REST API"}, {"label": "C", "text": "Pub/Sub API"}, {"label": "D", "text": "User Interface API"}]'::jsonb, 'A', 'The module states SOAP API uses a WSDL file to define the contract and calls it well-suited to server-to-server integration.'),
  ('API Basics', 4, 'What model does Pub/Sub API use, and what problem does it solve compared to frequent polling?', '[{"label": "A", "text": "A publish-subscribe model where clients subscribe to channels, eliminating the need for frequent polling requests"}, {"label": "B", "text": "A polling model that checks for changes every second"}, {"label": "C", "text": "A pure REST CRUD model with no event support"}, {"label": "D", "text": "A SOAP-based request-response model"}]'::jsonb, 'A', 'The module explicitly frames Pub/Sub API as reducing API requests by removing the need for frequent polling.'),
  ('API Basics', 5, 'What are the three types of API limits Salesforce enforces on an org?', '[{"label": "A", "text": "Timeout limits, concurrent request limits, and total request allocations"}, {"label": "B", "text": "Storage limits, user limits, and license limits"}, {"label": "C", "text": "Field limits, object limits, and record limits"}, {"label": "D", "text": "Only a single global limit applies to all orgs"}]'::jsonb, 'A', 'The module names exactly these three limit types.'),
  ('API Basics', 6, 'A partner is building a mobile app that needs to build native UI for records, list views, and actions, matching admin-configured metadata automatically. Which API is the best fit?', '[{"label": "A", "text": "User Interface API"}, {"label": "B", "text": "Bulk API"}, {"label": "C", "text": "SOAP API"}, {"label": "D", "text": "Metadata API"}]'::jsonb, 'A', 'The module recommends User Interface API specifically for building UI around records/list views/actions that automatically reflects org metadata changes.'),
  ('API Basics', 7, 'A customer wants to migrate custom field and object configuration from a sandbox to production. Which API is designed for that, and what tools commonly wrap it?', '[{"label": "A", "text": "Metadata API, commonly used via Salesforce Extensions for VS Code or the Ant Migration Tool"}, {"label": "B", "text": "Bulk API, via Data Loader"}, {"label": "C", "text": "REST API, via Postman"}, {"label": "D", "text": "Pub/Sub API, via a custom gRPC client"}]'::jsonb, 'A', 'The module states Metadata API is intended for migrating customizations between orgs, typically via VS Code extensions or the Ant Migration Tool.'),
  ('API Basics', 8, 'A customer needs to check how many of their org''s daily API calls remain, in real time, from within a running integration. What''s one documented way to do this?', '[{"label": "A", "text": "Check the Sforce-Limit-Info response header on REST API calls"}, {"label": "B", "text": "There is no way to check remaining API calls"}, {"label": "C", "text": "Only Salesforce Support can check this"}, {"label": "D", "text": "It requires a separate paid add-on product"}]'::jsonb, 'A', 'The module lists this response header as one of several ways to check remaining API usage, alongside System Overview and the /limits call.'),
  ('API Basics', 9, 'A developer wants a single request that returns only the specific fields a client needs, minimizing payload size and round trips. Which API is designed for exactly this?', '[{"label": "A", "text": "GraphQL API"}, {"label": "B", "text": "SOAP API"}, {"label": "C", "text": "Metadata API"}, {"label": "D", "text": "Connect REST API"}]'::jsonb, 'A', 'The module credits GraphQL API with field selection (only requested fields returned) and resource aggregation (fewer round trips).'),
  ('API Basics', 10, 'Every API call requires authentication except one specific call. Which call is exempt, and how do most other calls authenticate?', '[{"label": "A", "text": "The SOAP API login() call is exempt; other calls use OAuth flows or a session ID from that login() call"}, {"label": "B", "text": "No calls require authentication if made from a trusted IP range"}, {"label": "C", "text": "The REST API''s /limits call is exempt; all others need a session ID"}, {"label": "D", "text": "Bulk API calls never require authentication"}]'::jsonb, 'A', 'The module states all API calls require authentication except the SOAP API login() call, and describes OAuth flows or session-ID-based auth as the two supported approaches.'),
  ('Skedulo CLI', 1, 'What is the Skedulo CLI primarily used for?', '[{"label": "A", "text": "Extending and customizing a Skedulo team via command-line tooling for managing platform artifacts and deployments"}, {"label": "B", "text": "Replacing the Admin Console entirely for customer/team management"}, {"label": "C", "text": "Sending SMS and push notifications from the command line"}, {"label": "D", "text": "Running optimization jobs only"}]'::jsonb, 'A', 'The docs describe the CLI as enabling developers to extend/customize a Skedulo team via command-line artifact and deployment management.'),
  ('Skedulo CLI', 2, 'Which command authenticates the CLI to a Skedulo tenant?', '[{"label": "A", "text": "sked tenant login"}, {"label": "B", "text": "sked auth connect"}, {"label": "C", "text": "sked login tenant"}, {"label": "D", "text": "sked function login"}]'::jsonb, 'A', 'The docs name sked tenant login as the command for managing credentials across environments.'),
  ('Skedulo CLI', 3, 'Which command is used for local testing of a function during development?', '[{"label": "A", "text": "sked function dev"}, {"label": "B", "text": "sked function generate"}, {"label": "C", "text": "sked function deploy"}, {"label": "D", "text": "sked function test"}]'::jsonb, 'A', 'The docs specifically name sked function dev for local testing, distinct from sked function generate (scaffolding new functions).'),
  ('Skedulo CLI', 4, 'What does sked function generate do?', '[{"label": "A", "text": "Scaffolds a new function"}, {"label": "B", "text": "Runs a function locally for testing"}, {"label": "C", "text": "Deploys a function to production"}, {"label": "D", "text": "Deletes an existing function"}]'::jsonb, 'A', 'The docs distinguish sked function generate (scaffolding) from sked function dev (local testing).'),
  ('Skedulo CLI', 5, 'Besides functions, which of these can the CLI create, retrieve, or delete as artifacts?', '[{"label": "A", "text": "Custom objects and fields, web/mobile extensions, webhooks and triggered actions, pages, and user roles"}, {"label": "B", "text": "Only custom objects — nothing else"}, {"label": "C", "text": "Only mobile extensions"}, {"label": "D", "text": "Salesforce Apex classes"}]'::jsonb, 'A', 'The docs list this full set of artifact types the CLI can manage.'),
  ('Skedulo CLI', 6, 'A developer wants to test a web extension locally with a valid HTTPS certificate before deploying. What CLI tooling supports this?', '[{"label": "A", "text": "The web extension dev server plus SSL certificate generation for local testing"}, {"label": "B", "text": "sked function dev, since it also handles web extensions"}, {"label": "C", "text": "There is no local testing support for web extensions"}, {"label": "D", "text": "Only the Skedulo web app supports this, not the CLI"}]'::jsonb, 'A', 'The docs mention a dedicated dev server (sked web-extension dev) and SSL cert generation specifically for local web extension testing.'),
  ('Skedulo CLI', 7, 'A team wants to move a bundle of custom objects, fields, and functions from a dev tenant to production as one unit. What CLI concept supports this?', '[{"label": "A", "text": "Packages — the CLI can build, register, list, and deploy packages"}, {"label": "B", "text": "Artifacts only — packages are not a CLI concept"}, {"label": "C", "text": "This can only be done manually through the Admin Console"}, {"label": "D", "text": "Only functions can be packaged, not objects/fields"}]'::jsonb, 'A', 'The docs describe dedicated package commands covering the full package lifecycle: build, register, list, and deploy.'),
  ('Skedulo CLI', 8, 'What is the general structure of a Skedulo CLI command?', '[{"label": "A", "text": "sked [category] [action], e.g. sked artifacts function"}, {"label": "B", "text": "skedulo-cli --run [action]"}, {"label": "C", "text": "sked [action] --category [category]"}, {"label": "D", "text": "There is no consistent command structure"}]'::jsonb, 'A', 'The docs describe this exact category-then-action command structure.'),
  ('Skedulo CLI', 9, 'Where should a developer look first when a CLI deployment fails and they need step-by-step resolution guidance?', '[{"label": "A", "text": "The CLI troubleshooting guide"}, {"label": "B", "text": "The Object Reference overview"}, {"label": "C", "text": "The Optimization API getting-started guide"}, {"label": "D", "text": "The Skedulo release notes only"}]'::jsonb, 'A', 'The docs describe a dedicated troubleshooting guide as part of the CLI documentation structure.'),
  ('Skedulo CLI', 10, 'A developer needs a fast lookup of frequently used CLI commands without reading the full command reference. What resource is built for this?', '[{"label": "A", "text": "The CLI quick reference guide"}, {"label": "B", "text": "The API Reference Guide"}, {"label": "C", "text": "The Object Reference overview"}, {"label": "D", "text": "The Optimization API extensions page"}]'::jsonb, 'A', 'The docs explicitly describe a "quick reference guide" for frequently used CLI operations, separate from the full command reference and troubleshooting guide.'),
  ('Manage and control access', 1, 'What do Record Access Policy (RAP) rules implement?', '[{"label": "A", "text": "Row-level security — a user may see some records of an object type but not all of them"}, {"label": "B", "text": "Column-level (field-level) security only"}, {"label": "C", "text": "Whole-object blocking only — no partial row access is possible"}, {"label": "D", "text": "UI-only restrictions that do not affect API data access"}]'::jsonb, 'A', 'The doc explicitly frames RAP filters as row-level security, distinct from blocking a whole object or a whole field.'),
  ('Manage and control access', 2, 'What does setting a rule''s access type to "deny" mean?', '[{"label": "A", "text": "Access is denied unless the record passes the filter condition"}, {"label": "B", "text": "Access is always denied, regardless of the filter"}, {"label": "C", "text": "Access is granted only to Administrators"}, {"label": "D", "text": "The rule is disabled and has no effect"}]'::jsonb, 'A', 'The doc defines "deny" as denying access unless the filter condition passes — "deny unless true."'),
  ('Manage and control access', 3, 'When multiple deny rules apply to the same object type, how are they combined? And how are allow rules combined with an existing deny rule?', '[{"label": "A", "text": "Multiple deny filters are combined with AND (all must pass); an allow filter is combined with OR to conditionally override the deny"}, {"label": "B", "text": "Multiple deny filters are combined with OR; allow filters are combined with AND"}, {"label": "C", "text": "Only the first matching rule is ever applied; the rest are ignored"}, {"label": "D", "text": "Deny and allow rules cannot coexist on the same object type"}]'::jsonb, 'A', 'The doc states deny filters combine with AND, and an allow filter is added with OR to conditionally override an existing deny rule.'),
  ('Manage and control access', 4, 'Which users are automatically exempt from ALL record access policies, regardless of any rule configuration?', '[{"label": "A", "text": "Users with the Administrator role, or a role containing skedulo.tenant.data.viewAll and skedulo.tenant.data.modifyAll"}, {"label": "B", "text": "Every user with the Scheduler role"}, {"label": "C", "text": "No user is ever exempt — RAP rules always apply"}, {"label": "D", "text": "Only the tenant owner account is exempt"}]'::jsonb, 'A', 'The doc names these specific roles/permissions as globally exempt from all record access policies.'),
  ('Manage and control access', 5, 'What language is used to write RAP rule filters?', '[{"label": "A", "text": "Skedulo''s Elastic Query Language (EQL), the same language used in the GraphQL API"}, {"label": "B", "text": "Raw SQL"}, {"label": "C", "text": "A proprietary XML-based rules DSL"}, {"label": "D", "text": "Regular expressions only"}]'::jsonb, 'A', 'The doc states RAP filters use EQL, the same language used for GraphQL API filters.'),
  ('Manage and control access', 6, 'A customer wants a rule where resources only see jobs allocated to them, EXCEPT that schedulers should still see all jobs regardless of allocation. How is this modeled?', '[{"label": "A", "text": "A deny rule restricting access by allocation, with a permissions exclusion for the scheduler''s dispatch permission (e.g. skedulo.tenant.schedule.allocation.dispatch)"}, {"label": "B", "text": "Two separate, unrelated policies with no interaction"}, {"label": "C", "text": "This cannot be modeled — RAP rules apply identically to every role"}, {"label": "D", "text": "A roles-excluded list naming every individual scheduler by name only"}]'::jsonb, 'A', 'The doc''s own worked example uses exactly this pattern: a deny rule plus a permissionsExcluded entry for the dispatch permission so schedulers are exempted.'),
  ('Manage and control access', 7, 'A RAP rule needs to filter JobAllocations by a related Resource''s Name field. Why can''t the filter simply say Resource.Name != ''secret''?', '[{"label": "A", "text": "RAP rule filters don''t support referring to a field of a lookup field directly — a sub-query (IN clause) must be used instead"}, {"label": "B", "text": "RAP filters don''t support the != operator at all"}, {"label": "C", "text": "RAP filters can only reference the object''s own UID field"}, {"label": "D", "text": "This syntax is fully supported in RAP filters, unlike in GraphQL"}]'::jsonb, 'A', 'The doc explicitly calls out this GraphQL-vs-RAP difference and gives the ResourceId IN (SELECT UID FROM Resources WHERE Name != ''secret'') pattern as the required alternative.'),
  ('Manage and control access', 8, 'What do the {{resourceId}} and {{userId}} placeholders do in a RAP filter?', '[{"label": "A", "text": "They are substituted with the actual resource/user ID of whoever is making the request"}, {"label": "B", "text": "They are static, hard-coded example values with no runtime meaning"}, {"label": "C", "text": "They only work in Triggered Actions, not RAP filters"}, {"label": "D", "text": "They must be manually replaced by an admin before the rule can be saved"}]'::jsonb, 'A', 'The doc describes these as template variables substituted with the relevant values for the requesting user.'),
  ('Manage and control access', 9, 'What is a "pattern rule" using hasLookup:<lookup-name>, and what is the "Data isolation by region" policy an example of?', '[{"label": "A", "text": "A rule applied to every object type sharing a lookup relationship with a given name — the region-isolation policy uses hasLookup:Region as a deny pattern rule, plus extra deny/allow rules for objects linked indirectly"}, {"label": "B", "text": "A rule that can only ever apply to a single named object, never multiple types"}, {"label": "C", "text": "A deprecated feature no longer supported in current tenants"}, {"label": "D", "text": "A rule type that only affects the mobile app, not the web app or API"}]'::jsonb, 'A', 'The doc''s Data isolation by region example uses a hasLookup:Region pattern rule as its core deny mechanism, supplemented with deny rules for indirectly-linked objects (Holidays, Activities, Users) and allow rules for Jobs/Shifts/Contacts.'),
  ('Manage and control access', 10, 'Why does the doc recommend testing new record access policies in a separate environment before applying them to production?', '[{"label": "A", "text": "Because incorrectly configured rules can cause the Skedulo web or mobile app to stop functioning properly"}, {"label": "B", "text": "Because RAP changes cannot be reverted once saved"}, {"label": "C", "text": "Because RAP rules take 24 hours to propagate"}, {"label": "D", "text": "Because testing in production is against Skedulo policy but carries no functional risk"}]'::jsonb, 'A', 'The doc''s "Important" callout warns that policy rules are powerful but can break app functionality if misconfigured, hence the recommendation to test first.'),
  ('Advanced webhook scheduling and triggered-action design', 1, 'What two forms of time-based webhook behavior does Skedulo support?', '[{"label": "A", "text": "Deferred webhooks (fire relative to a timestamp field) and scheduled/cron webhooks (fire on a fixed cron schedule)"}, {"label": "B", "text": "Only cron-scheduled webhooks — deferred webhooks do not exist"}, {"label": "C", "text": "Only deferred webhooks — cron scheduling is not supported"}, {"label": "D", "text": "Retry-on-failure webhooks and rate-limited webhooks"}]'::jsonb, 'A', 'The doc covers both deferred webhooks (offset relative to a field like CreatedDate) and scheduled webhooks using cron expressions.'),
  ('Advanced webhook scheduling and triggered-action design', 2, 'For a deferred webhook, what kind of field must the "field" parameter reference?', '[{"label": "A", "text": "A field with an INSTANT value (e.g. Start, End, CreatedDate)"}, {"label": "B", "text": "Any text field on the object"}, {"label": "C", "text": "Only a custom picklist field"}, {"label": "D", "text": "A lookup relationship field"}]'::jsonb, 'A', 'The doc requires the field to hold an INSTANT (timestamp) value such as Start, End, ActualStart, EstimatedEnd, or CreatedDate.'),
  ('Advanced webhook scheduling and triggered-action design', 3, 'What does the "offset" value represent in a deferred webhook, and can it be negative?', '[{"label": "A", "text": "Milliseconds relative to the field''s timestamp; yes, negative values fire the webhook before that timestamp (e.g. a reminder 24h before a job starts)"}, {"label": "B", "text": "A fixed number of retries, and it cannot be negative"}, {"label": "C", "text": "The number of records to batch per webhook call"}, {"label": "D", "text": "A percentage discount applied to rate limiting"}]'::jsonb, 'A', 'The doc explains offset as milliseconds relative to the timestamp field, explicitly allowing negative values for pre-timestamp firing (the 24-hours-before-appointment SMS example).'),
  ('Advanced webhook scheduling and triggered-action design', 4, 'Why does the doc recommend an offset of at least 5000ms for webhooks deferred on CreatedDate or LastModifiedDate?', '[{"label": "A", "text": "Because there is a small delay between when a data change is processed and when related webhooks are updated"}, {"label": "B", "text": "Because Skedulo enforces a hard minimum offset of 5000ms on all deferred webhooks"}, {"label": "C", "text": "Because smaller offsets are rejected by the API with a validation error"}, {"label": "D", "text": "Because 5000ms is required for SMS-based webhooks only"}]'::jsonb, 'A', 'The doc explicitly attributes this recommendation to a small propagation delay between data changes and webhook updates.'),
  ('Advanced webhook scheduling and triggered-action design', 5, 'Is the "filter" field optional or required for a deferred webhook?', '[{"label": "A", "text": "Required — the doc states the filter field must be provided for deferred webhooks"}, {"label": "B", "text": "Optional — it defaults to matching all records"}, {"label": "C", "text": "Not supported at all on deferred webhooks"}, {"label": "D", "text": "Required only when the offset is negative"}]'::jsonb, 'A', 'The doc has an explicit note: "For deferred webhooks, the filter field must be provided."'),
  ('Advanced webhook scheduling and triggered-action design', 6, 'A customer wants each job type to have its own custom reminder lead time (e.g., 1 hour for some jobs, 1 day for others) rather than one fixed offset for all jobs. How can this be configured?', '[{"label": "A", "text": "Use a dynamic offset: set \"offset\" to an object with a \"field\" (a custom number/duration field) and an optional \"default\""}, {"label": "B", "text": "This requires one separate webhook per job type, since offsets must be a fixed number"}, {"label": "C", "text": "Dynamic per-record offsets are not supported by Skedulo webhooks"}, {"label": "D", "text": "Use the \"cron\" field instead of \"offset\" to vary timing per record"}]'::jsonb, 'A', 'The doc''s dynamically-deferred webhook example does exactly this — a custom number field supplies a per-record offset, with a default used when the field has no value.'),
  ('Advanced webhook scheduling and triggered-action design', 7, 'In a dynamic-offset webhook, what happens if the referenced custom field has no value AND no "default" was provided?', '[{"label": "A", "text": "The webhook is not triggered for that record"}, {"label": "B", "text": "The webhook fires immediately with a 0ms offset"}, {"label": "C", "text": "The webhook fires using the global default of 15000ms automatically"}, {"label": "D", "text": "The API call fails validation and rejects the webhook configuration"}]'::jsonb, 'A', 'The doc states explicitly: "If the field has no value and no default is provided then the webhook is not triggered for that object."'),
  ('Advanced webhook scheduling and triggered-action design', 8, 'What is the correct field order in a Skedulo cron expression, from left to right?', '[{"label": "A", "text": "minute, hour, day of month, month, day of week"}, {"label": "B", "text": "hour, minute, day of week, month, day of month"}, {"label": "C", "text": "second, minute, hour, day of month, month"}, {"label": "D", "text": "day of week, month, day of month, hour, minute"}]'::jsonb, 'A', 'The doc''s cron diagram lists the fields in exactly this order: minute, hour, day of month, month, day of week.'),
  ('Advanced webhook scheduling and triggered-action design', 9, 'What cron expression would run a scheduled webhook every Friday at 11:45 AM?', '[{"label": "A", "text": "45 11 * * 5"}, {"label": "B", "text": "11 45 * * 5"}, {"label": "C", "text": "45 11 5 * *"}, {"label": "D", "text": "5 11 45 * *"}]'::jsonb, 'A', 'The doc gives this exact example for ''every Friday at 11:45 AM'', with minute=45, hour=11, and day-of-week=5.'),
  ('Advanced webhook scheduling and triggered-action design', 10, 'A scheduled webhook of "type": "scheduled" with a cron field fires independent of what condition?', '[{"label": "A", "text": "Any Skedulo data change — it fires purely on the cron schedule, unlike deferred or event-based webhooks"}, {"label": "B", "text": "It still requires a data change to have occurred in the prior interval"}, {"label": "C", "text": "It only fires if the \"filter\" field also matches"}, {"label": "D", "text": "It requires an accompanying GraphQL subscription query"}]'::jsonb, 'A', 'The doc''s example ("scheduled_every_minute") fires purely on the cron interval with no query or filter tied to a data change, unlike deferred or standard event webhooks.'),
  ('Fundamentals of Process Improvement', 1, 'How is the course structured, per its content outline?', '[{"label": "A", "text": "8 sections and 43 lectures totalling about 4h48m, organized around What/Who/How/When/Why questions plus demonstrations"}, {"label": "B", "text": "A single 1-hour session with no sections"}, {"label": "C", "text": "20 short sections with no structure around process improvement questions"}, {"label": "D", "text": "Only a final exam with no lecture content"}]'::jsonb, 'A', 'The course content lists 8 sections • 43 lectures • 4h 48m, moving through Process improvement: What/Who/How/When/Why, then Demonstrations and Close out.'),
  ('Fundamentals of Process Improvement', 2, 'Which section of the course is the longest?', '[{"label": "A", "text": "\"Process improvement: How?\" (13 lectures, 1hr 37min)"}, {"label": "B", "text": "\"Introduction\" (3 lectures, 7min)"}, {"label": "C", "text": "\"Close out\" (3 lectures, 9min)"}, {"label": "D", "text": "\"Process improvement: Why?\" (4 lectures, 24min)"}]'::jsonb, 'A', '"Process improvement: How?" is by far the largest section at 13 lectures and 1hr 37min, reflecting its focus on the practical mapping toolkit.'),
  ('Fundamentals of Process Improvement', 3, 'What is the goal of distinguishing value-add from non-value-add steps, per the course?', '[{"label": "A", "text": "To reduce non-value-adding steps and increase value-adding ones, lowering time, effort and financial waste"}, {"label": "B", "text": "To eliminate all steps regardless of value"}, {"label": "C", "text": "To make processes longer so they look more thorough"}, {"label": "D", "text": "To avoid ever changing an existing process"}]'::jsonb, 'A', 'A core learning objective is identifying value-add vs. non-value-add steps specifically to reduce the latter and increase the former.'),
  ('Fundamentals of Process Improvement', 4, 'How does the course validate learning?', '[{"label": "A", "text": "Quizzes and an assignment"}, {"label": "B", "text": "A single multiple-choice exam only"}, {"label": "C", "text": "No validation of learning is included"}, {"label": "D", "text": "Peer code review"}]'::jsonb, 'A', 'The description states the course tests knowledge "with quizzes and an assignment."'),
  ('Fundamentals of Process Improvement', 5, 'What does the course''s process mapping toolkit include?', '[{"label": "A", "text": "A complete set of process mapping tools with practical demonstrations and templates for those that require them"}, {"label": "B", "text": "Only a single generic flowchart symbol"}, {"label": "C", "text": "A finance-only budgeting spreadsheet"}, {"label": "D", "text": "A list of software licenses with no mapping content"}]'::jsonb, 'A', 'The description promises "a complete process mapping toolkit, with practical demonstrations on how to use each one — with templates attached for those which require it."'),
  ('Fundamentals of Process Improvement', 6, 'Who does the course explicitly target as its audience?', '[{"label": "A", "text": "Business and process analysts, process owners, operations managers, and continuous improvement practitioners"}, {"label": "B", "text": "Only C-suite executives"}, {"label": "C", "text": "Software QA testers exclusively"}, {"label": "D", "text": "Graphic designers"}]'::jsonb, 'A', 'The "Who this course is for" section lists these four roles specifically.'),
  ('Fundamentals of Process Improvement', 7, 'A Specialist has mapped a process and wants leadership buy-in to actually implement the improvement. Per the course''s stated outcome, what should they be equipped to do?', '[{"label": "A", "text": "Confidently sell the vision and importance of process improvement to leaders within the organization, not just complete the mapping"}, {"label": "B", "text": "Wait silently for leadership to notice the map unprompted"}, {"label": "C", "text": "Avoid engaging leadership at all costs"}, {"label": "D", "text": "Only present the mapping toolkit templates with no narrative"}]'::jsonb, 'A', 'The description explicitly states the course builds confidence "not only to conduct wide ranging process improvement projects but also to sell the vision and importance of process improvement to leaders."'),
  ('Fundamentals of Process Improvement', 8, 'While mapping a support workflow, a Specialist finds several steps that involve internal handoffs but do not change the outcome the customer receives. What should this prompt them to consider?', '[{"label": "A", "text": "Whether these are non-value-add steps that could be reduced, per the course''s value-add/non-value-add framework"}, {"label": "B", "text": "Adding even more internal handoff steps for thoroughness"}, {"label": "C", "text": "Ignoring the finding since all steps are equally important by default"}, {"label": "D", "text": "Escalating immediately to legal for review"}]'::jsonb, 'A', 'Identifying steps that don''t connect to product, service, or customer outcomes is exactly the value-add/non-value-add analysis the course teaches.'),
  ('Fundamentals of Process Improvement', 9, 'The course states "every process map has a purpose, so this course will show you which one to use when." What does this imply about process mapping tools?', '[{"label": "A", "text": "Different mapping tools/formats suit different purposes, so choosing the right one depends on what the map needs to communicate"}, {"label": "B", "text": "Only one universal map format exists for every situation"}, {"label": "C", "text": "Process maps are purely decorative and interchangeable"}, {"label": "D", "text": "The tool choice never matters as long as a diagram exists"}]'::jsonb, 'A', 'This framing across the course''s toolkit section signals that map selection should match the specific purpose of the mapping exercise.'),
  ('Fundamentals of Process Improvement', 10, 'Per the course''s framing, why is process improvement described as an increasingly vital organizational skill?', '[{"label": "A", "text": "Because organizations are building more, increasingly complex processes across departments, making the ability to amend, improve and secure them a demonstrable, measurable value"}, {"label": "B", "text": "Because processes never change once created"}, {"label": "C", "text": "Because it replaces the need for any customer feedback"}, {"label": "D", "text": "Because it is only relevant to manufacturing companies"}]'::jsonb, 'A', 'The description opens by framing process improvement as increasingly important as organizational processes grow more numerous and complex.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 1, 'What free tool does this course standardize on for building flowcharts, and why?', '[{"label": "A", "text": "Draw.io, chosen so all students can follow along without needing a paid program"}, {"label": "B", "text": "Microsoft Visio, chosen for its enterprise licensing"}, {"label": "C", "text": "A proprietary in-house tool with no public access"}, {"label": "D", "text": "Paper and pencil only, with no digital tool"}]'::jsonb, 'A', 'The course explicitly notes it uses Draw.io "instead of a paid program, in order to ensure all students are able to follow along with activities."'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 2, 'What is the instructor''s TEACH, SHOW, DO technique?', '[{"label": "A", "text": "First teach the concept in detail, then show it applied to a real-world example, then have the student do activities and quizzes to cement it"}, {"label": "B", "text": "A single unstructured lecture per topic with no activities"}, {"label": "C", "text": "Group debate with no instructor input"}, {"label": "D", "text": "Reading assignments only, with no video content"}]'::jsonb, 'A', 'The course description names this exact three-step method (TEACH – SHOW – DO) as its core pedagogy.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 3, 'How is the course structured, and which section is the largest?', '[{"label": "A", "text": "9 sections, 81 lectures, 3h42m total; \"Beyond the Basics: Additional Symbols\" is the largest at 21 lectures/1hr22min"}, {"label": "B", "text": "3 sections with no lecture breakdown"}, {"label": "C", "text": "81 sections of 9 lectures each"}, {"label": "D", "text": "A single 3.5-hour unbroken video"}]'::jsonb, 'A', 'The course content list shows 9 sections • 81 lectures • 3h 42m, with "Beyond the Basics: Additional Symbols" the longest section by far.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 4, 'What is the purpose of a swimlane in a process flowchart, per the course?', '[{"label": "A", "text": "To show clearly who is responsible for each task within the process"}, {"label": "B", "text": "To make the flowchart more colorful with no functional purpose"}, {"label": "C", "text": "To replace the need for any process steps"}, {"label": "D", "text": "To indicate which steps are optional"}]'::jsonb, 'A', 'The course description states that visual tools like swimlanes make clear "who is responsible for each task," which is the whole point of the "Creating a Swimlane Process Flowchart" section.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 5, 'What professional certification credit does this course qualify for?', '[{"label": "A", "text": "3.5 PD Hours/CDUs toward ECBA®, CCBA®, or CBAP® certification or recertification"}, {"label": "B", "text": "A university degree credit"}, {"label": "C", "text": "No professional certification credit of any kind"}, {"label": "D", "text": "A Six Sigma Black Belt credential"}]'::jsonb, 'A', 'The description opens by noting the course "qualifies for 3.5 PD Hours/CDUs" toward these IIBA business-analysis certifications.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 6, 'What is the stated purpose of enhancing a flowchart with "Levels," per the course content?', '[{"label": "A", "text": "To let the same underlying process be represented at different levels of detail for different audiences"}, {"label": "B", "text": "To rank employees by seniority on the diagram"}, {"label": "C", "text": "To add decorative color-coding with no informational value"}, {"label": "D", "text": "To indicate how many times a process has been revised"}]'::jsonb, 'A', '"Enhance your Flowchart with Levels" is a dedicated, substantial section (16 lectures/51min) building on the idea that flowcharts can zoom from a high-level view to more granular detail.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 7, 'A Senior Specialist reviews a cross-team escalation flowchart that shows steps in sequence but never indicates which team or role owns each step. What is missing, per this course?', '[{"label": "A", "text": "Swimlanes, which the course teaches specifically to assign clear ownership of each task to a person or team"}, {"label": "B", "text": "Nothing; sequence alone is always sufficient"}, {"label": "C", "text": "A larger font size"}, {"label": "D", "text": "More decorative symbols"}]'::jsonb, 'A', 'Swimlanes are the course''s dedicated technique for showing who owns each step, which is exactly the gap in an ownership-less sequential flowchart.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 8, 'A Senior Specialist needs to present the same support-escalation process to both frontline agents (who need step-by-step detail) and to an executive (who wants only the big picture). Which technique from the course applies?', '[{"label": "A", "text": "Building the flowchart with multiple levels, so the same process can be shown at different levels of detail per audience"}, {"label": "B", "text": "Building two completely unrelated flowcharts with no shared basis"}, {"label": "C", "text": "Skipping documentation for the executive entirely"}, {"label": "D", "text": "Only ever showing the most detailed version to every audience"}]'::jsonb, 'A', 'This is precisely the scenario the course''s "Levels" section addresses: representing one process at varying granularity for different audiences.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 9, 'Why does the course emphasize learning flowchart symbols and conventions "beyond the basics," even for an audience that isn''t always working as a formal Business Analyst?', '[{"label": "A", "text": "Because process flowcharts are used across roles at any level of an organization, so the skill has broad, practical value beyond one job title"}, {"label": "B", "text": "Because only Business Analysts will ever encounter a flowchart"}, {"label": "C", "text": "Because advanced symbols are purely academic with no workplace use"}, {"label": "D", "text": "Because the basics alone are always sufficient in every situation"}]'::jsonb, 'A', 'The course explicitly states flowcharting is useful "no matter your role," not just for aspiring or current Business Analysts.'),
  ('Process Flowcharts & Process Mapping - The Beginner''s Guide', 10, 'What does the course promise in terms of ongoing access to its content?', '[{"label": "A", "text": "Lifetime access with no expiration"}, {"label": "B", "text": "Access expires after 30 days"}, {"label": "C", "text": "Access expires once the certificate of completion is issued"}, {"label": "D", "text": "Content must be repurchased annually"}]'::jsonb, 'A', 'The description states enrollment "grants you lifetime access, with no expiration, to all the course lectures, activities, handouts, and quizzes."'),
  ('Certified Process Improvement & Process Mapping Expert', 1, 'What are the two main parts (aims) of this course?', '[{"label": "A", "text": "Part one teaches process mapping/flowcharting to visualize a process; part two teaches process improvement techniques to make that process more efficient"}, {"label": "B", "text": "Part one is HR policy; part two is payroll processing"}, {"label": "C", "text": "Part one and two both cover only software installation"}, {"label": "D", "text": "There is only one part, covering certification logistics"}]'::jsonb, 'A', 'The description states the course has "two aims": part one teaches process mapping/flowcharting, part two teaches process improvement techniques built on those maps.'),
  ('Certified Process Improvement & Process Mapping Expert', 2, 'What optional, external credential can students pursue after completing this course?', '[{"label": "A", "text": "A free, optional Lean (Six Sigma) examination/certification through SSAA, occurring outside the Udemy platform and worth 10 official CPD credits (equal to 10 PDUs for PMI)"}, {"label": "B", "text": "A mandatory paid exam administered only in person"}, {"label": "C", "text": "No further credential is offered"}, {"label": "D", "text": "A university degree in engineering"}]'::jsonb, 'A', 'The description details this optional external SSAA exam and certificate, worth 10 official CPD credits equal to 10 PDUs for a PMI license.'),
  ('Certified Process Improvement & Process Mapping Expert', 3, 'Which topics does the "Process Mapping" section of the course cover?', '[{"label": "A", "text": "Reading and creating process maps/flowcharts, the contrast between BPMN and classic process maps, and using Draw.io to build them"}, {"label": "B", "text": "Only payroll tax calculations"}, {"label": "C", "text": "Physical warehouse layout design"}, {"label": "D", "text": "Legal contract drafting"}]'::jsonb, 'A', 'The course content and description both cover reading/creating maps, BPMN vs. classic process mapping, and Draw.io-based construction.'),
  ('Certified Process Improvement & Process Mapping Expert', 4, 'What does the second half of the course ("Process Improvement") add on top of process mapping?', '[{"label": "A", "text": "How to use the process flowcharts as a basis for process improvement, including visualizing and quantifying process efficiency and treating process risks"}, {"label": "B", "text": "A repeat of the same process mapping content with no new material"}, {"label": "C", "text": "Purely legal compliance training unrelated to processes"}, {"label": "D", "text": "Sales commission structures"}]'::jsonb, 'A', 'The description states process maps "form the basis for process improvement," and lists visualizing/quantifying efficiency and treating process risks as course content.'),
  ('Certified Process Improvement & Process Mapping Expert', 5, 'Who accredits this course, and what is their claimed reach?', '[{"label": "A", "text": "Six Sigma Academy Amsterdam, or SSAA, which states it has trained and certified around 150,000-200,000+ people across roughly 170-180 countries"}, {"label": "B", "text": "A single unaccredited freelance instructor with no institutional backing"}, {"label": "C", "text": "A government regulatory agency"}, {"label": "D", "text": "No accreditation body is mentioned at all"}]'::jsonb, 'A', 'SSAA''s own description states this scale of reach, and the course is taught by their university-affiliated lecturers (BKO accredited).'),
  ('Certified Process Improvement & Process Mapping Expert', 6, 'What KPI-related skill does the course specifically teach, per its learning objectives?', '[{"label": "A", "text": "How to choose the right KPIs or Key Performance Indicators for your processes"}, {"label": "B", "text": "How to calculate payroll taxes"}, {"label": "C", "text": "How to design a company logo"}, {"label": "D", "text": "How to write a legal contract"}]'::jsonb, 'A', 'The description explicitly lists "Choose the right KPIs or Key Performance Indicators for your processes" among the course''s content.'),
  ('Certified Process Improvement & Process Mapping Expert', 7, 'A Principal Specialist has already mastered basic flowcharting from an earlier course and now wants to quantify how efficient a support process actually is, not just diagram it. Which part of this course addresses that directly?', '[{"label": "A", "text": "The \"Process Improvement\" section, which teaches visualizing and quantifying process efficiency"}, {"label": "B", "text": "The \"Process Mapping\" section alone, since mapping and quantifying efficiency are identical activities"}, {"label": "C", "text": "Neither section; efficiency cannot be quantified per this course"}, {"label": "D", "text": "Only the examination/certification logistics section"}]'::jsonb, 'A', 'The course draws a clear line between mapping (visualizing a process) and improvement (quantifying and improving its efficiency) — the latter is what this scenario calls for.'),
  ('Certified Process Improvement & Process Mapping Expert', 8, 'A Principal Specialist is deciding whether to model an escalation process using classic flowchart symbols or BPMN notation. What does the course say to help with that decision?', '[{"label": "A", "text": "The course explicitly contrasts BPMN vs. classic process maps so students understand when each is appropriate"}, {"label": "B", "text": "The course insists BPMN and classic process maps are functionally identical and interchangeable in every case"}, {"label": "C", "text": "The course only teaches BPMN and never covers classic flowcharts"}, {"label": "D", "text": "The course leaves this decision entirely unaddressed"}]'::jsonb, 'A', '"BPMN Vs. Process Mapping" is a specifically named lecture in the Process Mapping section, directly addressing this contrast.'),
  ('Certified Process Improvement & Process Mapping Expert', 9, 'Why might a Principal Specialist pursuing this course value the optional SSAA certification specifically, compared to only the Udemy completion certificate?', '[{"label": "A", "text": "Because it is an independent, externally accredited (UK CPD and Dutch higher education BKO) credential worth PDUs, adding recognized weight beyond a platform completion certificate"}, {"label": "B", "text": "Because it replaces the need to actually complete the course content"}, {"label": "C", "text": "Because it costs significantly more than the course itself"}, {"label": "D", "text": "Because it has no relationship to Lean/Six Sigma competency at all"}]'::jsonb, 'A', 'The description positions the SSAA exam/certificate as academically accredited and PMI PDU-eligible, distinct from and additional to the standard Udemy completion certificate.'),
  ('Certified Process Improvement & Process Mapping Expert', 10, 'Per the course description, treating process risk is part of which broader activity?', '[{"label": "A", "text": "Process improvement — by preventing and softening the impact of process risks after a process has been mapped"}, {"label": "B", "text": "Process mapping — treating risk is identical to drawing the initial flowchart"}, {"label": "C", "text": "An unrelated compliance-only exercise outside the course"}, {"label": "D", "text": "Something the course explicitly says it does not cover"}]'::jsonb, 'A', 'The description lists "Treat process risks, by preventing and softening the impact" as one of the process-improvement activities the course teaches, building on the earlier mapping work.'),
  ('Explore Lightning Experience Reports & Dashboards', 1, 'How long is this Trailhead trail, and what points total does it award?', '[{"label": "A", "text": "About 3 hours 45 minutes, 3,100 points"}, {"label": "B", "text": "About 30 minutes, 500 points"}, {"label": "C", "text": "About 10 hours, 10,000 points"}, {"label": "D", "text": "About 1 hour, 100 points"}]'::jsonb, 'A', 'The trail overview states this duration and point total.'),
  ('Explore Lightning Experience Reports & Dashboards', 2, 'What is the primary module in this trail, and what is it designed to do?', '[{"label": "A", "text": "\"Reports & Dashboards for Lightning Experience\" — visualize key business metrics in real time"}, {"label": "B", "text": "\"Quick Start: Lightning App Builder\" — the main and only module"}, {"label": "C", "text": "\"Apex Integration Services\" — build custom API integrations"}, {"label": "D", "text": "\"API Basics\" — teach REST and SOAP fundamentals"}]'::jsonb, 'A', 'This is the largest module in the trail (2,100 pts, ~1hr50m) and is described exactly this way.'),
  ('Explore Lightning Experience Reports & Dashboards', 3, 'Which module in this trail is aimed specifically at supporting sales and marketing managers with stakeholder-facing reporting?', '[{"label": "A", "text": "\"Create Reports and Dashboards for Sales and Marketing Managers\""}, {"label": "B", "text": "\"Reports & Dashboards for Lightning Experience\""}, {"label": "C", "text": "\"Quick Start: Lightning App Builder\""}, {"label": "D", "text": "None — this trail has no manager-specific module"}]'::jsonb, 'A', 'This module is explicitly framed around tracking key business information for stakeholders.'),
  ('Explore Lightning Experience Reports & Dashboards', 4, 'What no-code capability does the "Quick Start: Lightning App Builder" module in this trail teach?', '[{"label": "A", "text": "Building an app for sales reps in the field, with no code required"}, {"label": "B", "text": "Writing Apex triggers for automated reporting"}, {"label": "C", "text": "Building a custom REST API endpoint"}, {"label": "D", "text": "Configuring Salesforce CLI deployments"}]'::jsonb, 'A', 'The trail describes this module exactly this way — a no-code app for field sales reps.'),
  ('Explore Lightning Experience Reports & Dashboards', 5, 'Which skill areas does completing this trail build, according to the trail description?', '[{"label": "A", "text": "Data analysis, data visualization, business intelligence, general sales practices, and app development/engineering practices"}, {"label": "B", "text": "Only Apex development skills"}, {"label": "C", "text": "Only marketing automation skills"}, {"label": "D", "text": "Only mobile app design skills"}]'::jsonb, 'A', 'The trail explicitly lists these five skill areas as its core competencies developed.'),
  ('Explore Lightning Experience Reports & Dashboards', 6, 'A customer support specialist needs to quickly build an internal field app for reps with zero development resources. Which trail module maps directly to that need?', '[{"label": "A", "text": "Quick Start: Lightning App Builder"}, {"label": "B", "text": "Reports & Dashboards for Lightning Experience"}, {"label": "C", "text": "Create Reports and Dashboards for Sales and Marketing Managers"}, {"label": "D", "text": "None of the modules address app building"}]'::jsonb, 'A', 'This module is specifically the no-code, ~15-minute app-building quick start for field sales reps — the direct fit.'),
  ('Explore Lightning Experience Reports & Dashboards', 7, 'A stakeholder wants a real-time visual summary of key metrics they can check without asking someone to run a report manually. Which module addresses this need most directly?', '[{"label": "A", "text": "Reports & Dashboards for Lightning Experience"}, {"label": "B", "text": "Quick Start: Lightning App Builder"}, {"label": "C", "text": "Create Reports and Dashboards for Sales and Marketing Managers"}, {"label": "D", "text": "None of these modules mention dashboards"}]'::jsonb, 'A', 'This module is specifically framed around visualizing key business metrics in real time.'),
  ('Explore Lightning Experience Reports & Dashboards', 8, 'Is this trail aimed at developers writing custom reporting code, or at administrators/users building reports through Salesforce''s declarative tools?', '[{"label": "A", "text": "Administrators/users — the trail is described as designed for administrators tackling reporting complexity, using Lightning''s built-in tools"}, {"label": "B", "text": "Developers — it focuses on writing custom Apex-based reporting logic"}, {"label": "C", "text": "Neither — it''s purely conceptual with no hands-on tool use"}, {"label": "D", "text": "It targets only Salesforce partners building managed packages"}]'::jsonb, 'A', 'The trail overview frames it as being for administrators, using Lightning Experience''s native reporting/dashboard/app-builder tools, not custom code.'),
  ('Explore Lightning Experience Reports & Dashboards', 9, 'How many total modules make up this trail?', '[{"label": "A", "text": "Three"}, {"label": "B", "text": "Five"}, {"label": "C", "text": "One"}, {"label": "D", "text": "Ten"}]'::jsonb, 'A', 'The trail lists exactly three components: the two reporting/dashboard modules plus the Lightning App Builder quick start.'),
  ('Explore Lightning Experience Reports & Dashboards', 10, 'Roughly how much of the total trail time is spent on the core "Reports & Dashboards for Lightning Experience" module alone?', '[{"label": "A", "text": "About half — roughly 1 hour 50 minutes of the ~3h45m total"}, {"label": "B", "text": "Almost none — about 5 minutes"}, {"label": "C", "text": "The entire trail — all 3h45m is this one module"}, {"label": "D", "text": "Exactly 15 minutes"}]'::jsonb, 'A', 'At ~1hr50m out of ~3h45m total, this module accounts for roughly half the trail''s time investment.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 1, 'Which section of the course is the largest, both in lecture count and total running time?', '[{"label": "A", "text": "\"Excel Pivot Table Case Studies\" (22 lectures, 2 hours 31 minutes)"}, {"label": "B", "text": "\"Getting Started\" (5 lectures, 7 minutes)"}, {"label": "C", "text": "\"Wrapping Up\" (1 lecture, 2 minutes)"}, {"label": "D", "text": "\"Formatting Data with Pivot Tables\" (9 lectures, 30 minutes)"}]'::jsonb, 'A', 'At 22 lectures and 2h31m, the case studies section is by far the longest part of the course.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 2, 'Who created this course, and what is their claimed reach?', '[{"label": "A", "text": "Chris Dutton of Maven Analytics, which has helped 2,000,000+ learners build data and AI skills"}, {"label": "B", "text": "An anonymous Udemy staff writer with no stated background"}, {"label": "C", "text": "Microsoft''s official Excel product team"}, {"label": "D", "text": "A community-sourced, uncredited set of volunteers"}]'::jsonb, 'A', 'The course is created by Chris Dutton of Maven Analytics, described as having helped over 2,000,000 learners worldwide.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 3, 'How many real-world case studies does the course promise to work through?', '[{"label": "A", "text": "10"}, {"label": "B", "text": "2"}, {"label": "C", "text": "50"}, {"label": "D", "text": "0, it is purely theoretical"}]'::jsonb, 'A', 'The course description promises "10 real-world Pivot Table case studies" covering datasets like weather, shark attacks, wine tastings, and burrito ratings.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 4, 'Which of these is one of the real-world datasets used in the course''s case studies?', '[{"label": "A", "text": "Shark attack records from 1900-2016"}, {"label": "B", "text": "Skedulo internal support ticket exports"}, {"label": "C", "text": "A proprietary Salesforce dataset"}, {"label": "D", "text": "Zendesk Explore analytics exports"}]'::jsonb, 'A', 'The listed case studies include shark attack records from 1900-2016, alongside burrito ratings, MLB stats, and wine ratings, among others.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 5, 'What are the stated Excel version requirements for the course?', '[{"label": "A", "text": "Microsoft Excel 2010-2019 or Office 365, ideally on PC/Windows, though Mac users are welcome with some interface differences"}, {"label": "B", "text": "Only Excel Online is supported, with no desktop option"}, {"label": "C", "text": "Excel 95 or earlier exclusively"}, {"label": "D", "text": "The course requires no version of Excel at all"}]'::jsonb, 'A', 'The requirements list Excel 2010-2019 or Office 365, ideally for PC/Windows, while noting Mac users are welcome but the Pivot Table interface varies.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 6, 'What does the "Enriching Data with Pivot Table Calculated Values & Fields" section teach, per the course content outline?', '[{"label": "A", "text": "How to add custom calculated fields, items and values to extend what a Pivot Table can report"}, {"label": "B", "text": "How to format cell borders and fonts only"}, {"label": "C", "text": "How to write VBA macros from scratch"}, {"label": "D", "text": "How to install Excel add-ins"}]'::jsonb, 'A', 'This 17-lecture section is dedicated to enriching data using Pivot Table calculated values and fields, per the course''s own content outline.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 7, 'A Specialist has a large, raw ticket export with inconsistent column headers and mixed data types before they can even build a Pivot Table. Which section most directly addresses preparing that kind of data?', '[{"label": "A", "text": "\"Formatting Data with Pivot Tables\""}, {"label": "B", "text": "\"Wrapping Up\""}, {"label": "C", "text": "\"Visualizing Data with Excel Pivot Charts\""}, {"label": "D", "text": "\"Getting Started\""}]'::jsonb, 'A', '"Formatting Data with Pivot Tables" (9 lectures, 30 min) is the section dedicated to cleaning up and formatting raw data for use in Pivot Tables.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 8, 'A Specialist needs to build an interactive dashboard with slicers and timelines so a manager can filter SLA data by quarter with one click. Which part of the course covers this directly?', '[{"label": "A", "text": "\"Visualizing Data with Excel Pivot Charts,\" which covers Pivot Charts, slicers, timelines, and interactive dashboards"}, {"label": "B", "text": "\"Excel Pivot Table 101\" only"}, {"label": "C", "text": "The \"Wrapping Up\" section"}, {"label": "D", "text": "The \"Getting Started\" section"}]'::jsonb, 'A', 'The course description specifically lists Pivot Charts, slicers & timelines, and interactive Excel dashboards under this section''s content.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 9, 'A Specialist wants to quickly narrow a large dataset down to just the top three ticket categories by volume before analyzing trends. Which section teaches the tools for this?', '[{"label": "A", "text": "\"Sorting, Filtering & Grouping Data with Pivot Tables\""}, {"label": "B", "text": "\"Wrapping Up\""}, {"label": "C", "text": "\"Enriching Data with Pivot Table Calculated Values & Fields\""}, {"label": "D", "text": "\"Getting Started\""}]'::jsonb, 'A', 'This 11-lecture section is specifically about sorting, filtering, and grouping data with Pivot Tables, which is exactly what narrowing to top categories requires.'),
  ('Advanced Excel / Google Sheets for Reporting — Search Keywords: "advanced excel data analysis"', 10, 'Why does the course description say Pivot Tables are valuable for someone in a data-heavy support or operations role?', '[{"label": "A", "text": "They let you quickly explore and analyze raw data, revealing insights and trends otherwise buried in the noise"}, {"label": "B", "text": "They automatically write emails to customers"}, {"label": "C", "text": "They replace the need for any reporting altogether"}, {"label": "D", "text": "They only work with pre-summarized data, never raw exports"}]'::jsonb, 'A', 'The description frames Pivot Tables as giving fast, accurate answers by revealing insights and trends in raw data that would otherwise stay hidden.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 1, 'What does this Datadog learning path prepare a learner for?', '[{"label": "A", "text": "Datadog''s APM & Distributed Tracing Fundamentals Certification exam"}, {"label": "B", "text": "A general AWS certification"}, {"label": "C", "text": "A Salesforce Trailhead superbadge"}, {"label": "D", "text": "Skedulo''s own internal certification"}]'::jsonb, 'A', 'The learning path is explicitly built around this specific Datadog certification exam.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 2, 'How many courses does the full learning path include, and what else does it provide besides courses?', '[{"label": "A", "text": "14 courses, plus an exam guide and a 25-question practice exam"}, {"label": "B", "text": "3 courses, with no practice materials"}, {"label": "C", "text": "100 courses, with no exam guide"}, {"label": "D", "text": "1 course and a certification badge only"}]'::jsonb, 'A', 'The path description states 14 courses plus an exam guide and 25-question practice exam.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 3, 'Which course teaches identifying and resolving code defects using APM features specifically?', '[{"label": "A", "text": "Diagnosing Application Bugs with Datadog APM"}, {"label": "B", "text": "The Agent on a Host"}, {"label": "C", "text": "Getting Started with Integrations"}, {"label": "D", "text": "APM Rate Limiting and Retention Control"}]'::jsonb, 'A', 'This course is explicitly described as applying APM features to identify and resolve code defects.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 4, 'A senior engineer needs to investigate a production performance regression at the code level, beyond what basic traces show. Which course targets this?', '[{"label": "A", "text": "Diagnose Code Performance Issues with Continuous Profiler"}, {"label": "B", "text": "The Agent on Docker"}, {"label": "C", "text": "Getting Started with Service Level Objectives (SLOs)"}, {"label": "D", "text": "Configure Real User Monitoring (RUM) for JavaScript"}]'::jsonb, 'A', 'This course is specifically framed around investigating production performance issues, distinct from basic trace/metric courses.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 5, 'Which course covers adding custom instrumentation and tag-based filtering to traces?', '[{"label": "A", "text": "Create Custom Spans and Span Tags with APM"}, {"label": "B", "text": "Getting Started with APM Metrics & Traces"}, {"label": "C", "text": "APM Monitors and Alerting"}, {"label": "D", "text": "Monitoring a Postgres Database with Datadog DBM"}]'::jsonb, 'A', 'This course is described exactly this way — custom spans and span tags for filtering.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 6, 'A team wants to control how much trace data is ingested and how long it is retained, to manage cost. Which course addresses this directly?', '[{"label": "A", "text": "APM Rate Limiting and Retention Control"}, {"label": "B", "text": "Getting Started with APM Metrics & Traces"}, {"label": "C", "text": "The Agent on a Host"}, {"label": "D", "text": "Getting Started with Incident Management"}]'::jsonb, 'A', 'This course is specifically about managing trace data ingestion and retention.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 7, 'Which course would a team take first if they need to monitor JavaScript-based frontend user sessions rather than backend services?', '[{"label": "A", "text": "Configure Real User Monitoring (RUM) for JavaScript"}, {"label": "B", "text": "The Agent on Docker"}, {"label": "C", "text": "Getting Started with Integrations"}, {"label": "D", "text": "APM Monitors and Alerting"}]'::jsonb, 'A', 'RUM for JavaScript is the frontend/browser-focused course in this path, distinct from backend APM courses.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 8, 'A team running a containerized service wants Datadog Agent guidance specific to their deployment model. Which course fits?', '[{"label": "A", "text": "The Agent on Docker"}, {"label": "B", "text": "The Agent on a Host"}, {"label": "C", "text": "Getting Started with Integrations"}, {"label": "D", "text": "Getting Started with APM Metrics & Traces"}]'::jsonb, 'A', 'This course specifically addresses containerized Agent deployment, distinct from "The Agent on a Host" (bare-metal/VM).'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 9, 'What does the "Getting Started with Integrations" course cover?', '[{"label": "A", "text": "Datadog''s 800+ integrations for connecting external tools and platforms"}, {"label": "B", "text": "Only Datadog''s own internal APM tooling"}, {"label": "C", "text": "Only integrations with Salesforce products"}, {"label": "D", "text": "Kubernetes-specific integrations exclusively"}]'::jsonb, 'A', 'The course description names this exact figure — 800+ integrations for external tools/platforms.'),
  ('APM & Distributed Tracing Fundamentals Certification (advanced modules)', 10, 'Does completing this entire 14-course learning path guarantee a passing score on the certification exam?', '[{"label": "A", "text": "No — the path explicitly notes that completing it does not guarantee a passing exam score"}, {"label": "B", "text": "Yes — Datadog guarantees a pass for anyone who finishes all 14 courses"}, {"label": "C", "text": "Only if the practice exam score is above 90%"}, {"label": "D", "text": "The learning path has no connection to the certification exam at all"}]'::jsonb, 'A', 'The path includes this exact disclaimer.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 1, 'What four interconnected approaches does the Integration and Automation overview present for extending Skedulo?', '[{"label": "A", "text": "API foundation (REST/GraphQL), event-driven automation (webhooks/triggered actions), Salesforce integration (Apex calls), and custom extensions (functions)"}, {"label": "B", "text": "Only webhooks and the CLI"}, {"label": "C", "text": "Only the Optimization API and Reports"}, {"label": "D", "text": "Mobile extensions, web extensions, pages, and picklists"}]'::jsonb, 'A', 'The overview names these four topics as the pillars of integration and automation.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 2, 'How does the overview describe the relationship between these four topics — a ''layered architecture''?', '[{"label": "A", "text": "APIs provide raw connectivity, webhooks/triggered actions automate reactive workflows on top, and functions embed custom logic — a layered model"}, {"label": "B", "text": "They are entirely unrelated, standalone features with no shared architecture"}, {"label": "C", "text": "Functions replace the need for APIs entirely"}, {"label": "D", "text": "Salesforce integration is the foundation everything else depends on"}]'::jsonb, 'A', 'The overview explicitly frames these components as layered: API connectivity underneath, reactive automation above it, with functions embedding custom logic.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 3, 'Which topic is described as bridging Skedulo and Salesforce specifically, for bidirectional communication?', '[{"label": "A", "text": "Making calls to the Skedulo API from Salesforce using Apex"}, {"label": "B", "text": "The GraphQL API"}, {"label": "C", "text": "Skedulo Functions"}, {"label": "D", "text": "Webhooks"}]'::jsonb, 'A', 'The overview singles this section out as bridging the two platforms via Apex-based calls.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 4, 'What do Skedulo Functions let a developer build, per the overview?', '[{"label": "A", "text": "Custom functions for web and mobile extensions, embedding logic directly within Skedulo"}, {"label": "B", "text": "New Salesforce Lightning components only"}, {"label": "C", "text": "Custom cron schedules only"}, {"label": "D", "text": "New object types in the Skedulo data model"}]'::jsonb, 'A', 'The overview describes Functions as enabling custom logic embedded in web/mobile extensions.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 5, 'Which pair of mechanisms handles "automating responses to changes" in this architecture?', '[{"label": "A", "text": "Webhooks and Triggered Actions"}, {"label": "B", "text": "Functions and the CLI"}, {"label": "C", "text": "GraphQL and REST"}, {"label": "D", "text": "Packages and Artifacts"}]'::jsonb, 'A', 'The overview names webhooks and triggered actions together as the event-driven automation layer.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 6, 'A Skedulo for Salesforce customer wants their Apex code to call the Skedulo API directly, rather than going through an external middleware layer. Which overview section is directly relevant?', '[{"label": "A", "text": "Making calls to the Skedulo API from Salesforce using Apex"}, {"label": "B", "text": "Skedulo Functions"}, {"label": "C", "text": "Webhooks and Triggered Actions"}, {"label": "D", "text": "The API Overview alone, with no Salesforce-specific section"}]'::jsonb, 'A', 'This is the exact section the overview dedicates to Salesforce-to-Skedulo Apex-based API calls.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 7, 'A partner wants to embed custom business logic that runs as part of a mobile extension, rather than calling out to an external server. Which layer of this architecture supports that?', '[{"label": "A", "text": "Skedulo Functions"}, {"label": "B", "text": "Webhooks"}, {"label": "C", "text": "The REST API alone"}, {"label": "D", "text": "Triggered Actions only"}]'::jsonb, 'A', 'Functions are the layer described as embedding custom logic directly within Skedulo web/mobile extensions.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 8, 'If a developer wants to react automatically the moment a job''s status changes, which layer of the architecture is relevant, and which underlying layer does it depend on?', '[{"label": "A", "text": "Webhooks/Triggered Actions (event-driven automation), which sits on top of the API layer for connectivity"}, {"label": "B", "text": "Skedulo Functions alone, with no dependency on the API"}, {"label": "C", "text": "The Salesforce Apex integration layer only"}, {"label": "D", "text": "None of these layers support this — status changes cannot be observed"}]'::jsonb, 'A', 'This matches the layered model: reactive automation (webhooks/triggered actions) builds on the underlying API connectivity layer.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 9, 'Why does the overview single out Salesforce integration as receiving "special treatment" among the four topics?', '[{"label": "A", "text": "Because Skedulo for Salesforce is a major, distinct integration target requiring its own dedicated Apex-based calling pattern"}, {"label": "B", "text": "Because Salesforce integration is being deprecated in favor of the other three"}, {"label": "C", "text": "Because it is the only topic that supports authentication"}, {"label": "D", "text": "Because it is the only topic available to Pulse Platform customers"}]'::jsonb, 'A', 'The overview frames Salesforce as warranting its own dedicated section because it is a primary integration target distinct from generic external API consumers.'),
  ('Skedulo Developer Guide — Integration and Automation (webhooks, triggered actions, API)', 10, 'A senior specialist is scoping a new integration project and needs to decide which of the four topics to start researching first for a "push data out on every record change" requirement. Which should they start with?', '[{"label": "A", "text": "Webhooks and Triggered Actions"}, {"label": "B", "text": "Skedulo Functions"}, {"label": "C", "text": "Making calls to the Skedulo API from Salesforce using Apex"}, {"label": "D", "text": "None of the four — this requires a custom object schema change first"}]'::jsonb, 'A', 'Pushing data out automatically on every record change is precisely the event-driven automation use case that Webhooks/Triggered Actions are built for.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 1, 'What are SLA, SLO, SLI, and Error Budget, per this course?', '[{"label": "A", "text": "DevOps concepts the course teaches by having students create a Datadog SLO for success-rate tracking"}, {"label": "B", "text": "Four unrelated billing tiers for Datadog licenses"}, {"label": "C", "text": "Types of dashboards with no relation to reliability metrics"}, {"label": "D", "text": "Legacy terms not covered anywhere in the course"}]'::jsonb, 'A', 'The course explicitly covers "SLA, SLO, SLI and Error Budget by creating Datadog SLOs for success rate tracking" as a dedicated DevOps topic.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 2, 'Which incident-notification integrations does the course cover for Datadog monitors/alerts?', '[{"label": "A", "text": "Slack and PagerDuty"}, {"label": "B", "text": "Only email, with no chat or paging integration"}, {"label": "C", "text": "SMS only"}, {"label": "D", "text": "No third-party integrations are covered"}]'::jsonb, 'A', 'The course teaches integrating monitors with Slack and PagerDuty for real-time incident notifications.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 3, 'What does Datadog APM allow you to observe, per the course?', '[{"label": "A", "text": "The entire request path, so you can quickly identify where bottlenecks or errors occur, plus traces and error tracking"}, {"label": "B", "text": "Only CPU temperature of the host machine"}, {"label": "C", "text": "Marketing campaign click-through rates"}, {"label": "D", "text": "Employee time-tracking data"}]'::jsonb, 'A', 'The description states APM lets you "visualize the entire request path and quickly identify where bottlenecks or errors occur," alongside trace search and error tracking.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 4, 'What is Synthetic Monitoring used for in this course?', '[{"label": "A", "text": "Performing API and browser tests, including GET/POST requests with Bearer token authorization"}, {"label": "B", "text": "Manually reading server logs line by line"}, {"label": "C", "text": "Estimating cloud costs before deployment"}, {"label": "D", "text": "Designing UI mockups"}]'::jsonb, 'A', 'The course explicitly covers "Synthetic Monitoring and Performing API and Browser Tests. Using GET/Post methods with request body and Authorization Bearer Token."'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 5, 'What does the course teach about Datadog Notebooks?', '[{"label": "A", "text": "Using them to investigate incidents and collaborate with team members via comments and reusable templates"}, {"label": "B", "text": "They are used exclusively for writing marketing copy"}, {"label": "C", "text": "They replace the need for dashboards entirely"}, {"label": "D", "text": "They cannot be shared with other team members"}]'::jsonb, 'A', 'The course covers using Notebooks to "investigate incidents," "collaborate with team members using comments," and "create and reuse custom templates."'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 6, 'Besides .NET, what other application stack does the course demonstrate monitoring for?', '[{"label": "A", "text": "A Node.js application with MongoDB, including custom metrics and distributed tracing"}, {"label": "B", "text": "A COBOL mainframe application"}, {"label": "C", "text": "A WordPress PHP site"}, {"label": "D", "text": "No stack besides .NET is covered"}]'::jsonb, 'A', 'The course description includes setting up and monitoring "a Node.js application with MongoDB," with custom metrics and distributed tracing.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 7, 'A Principal Specialist wants to prove, with data, whether the team is meeting its reliability commitments and how much "budget" remains before breaching them. Which Datadog concept from the course applies?', '[{"label": "A", "text": "SLO and Error Budget tracking, which the course teaches by creating a success-rate SLO"}, {"label": "B", "text": "A generic dashboard with no reliability target defined"}, {"label": "C", "text": "Synthetic browser testing alone"}, {"label": "D", "text": "Log management with no metrics involved"}]'::jsonb, 'A', 'Error Budgets are specifically the mechanism for quantifying remaining tolerance against an SLO before breaching an SLA, which the course teaches directly.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 8, 'During a live incident, a Principal Specialist wants a single place to visualize the request path, spot the slowest queries, and correlate it with recent errors, then loop in the team. Which combination of course topics best supports this?', '[{"label": "A", "text": "Datadog APM (traces, error tracking) paired with Notebooks to investigate and collaborate with comments"}, {"label": "B", "text": "Only Synthetic Monitoring, which has no relation to live incidents"}, {"label": "C", "text": "Only the Metrics Explorer, with no tracing or collaboration tooling"}, {"label": "D", "text": "None of the course topics support live incident investigation"}]'::jsonb, 'A', 'APM traces/error tracking pinpoint the technical issue, while Notebooks are the course''s named tool for incident investigation and team collaboration.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 9, 'A reviewer notes the course "needs updating to reflect the latest changes" to the Datadog console. What does this imply for a Principal Specialist using it as a training resource today?', '[{"label": "A", "text": "The core APM/monitoring/SLO concepts remain valid, but some UI navigation steps shown in the videos may no longer exactly match the current Datadog interface"}, {"label": "B", "text": "The entire course content is factually wrong and should be disregarded"}, {"label": "C", "text": "Datadog no longer supports APM or SLOs at all"}, {"label": "D", "text": "This feedback means the course covers no real Datadog functionality"}]'::jsonb, 'A', 'Reviews note the console "has undergone many updates" so some interface details are dated, while the underlying APM/SLO/dashboard concepts taught remain applicable.'),
  ('Datadog: Performance monitoring tool (from Zero to Hero)', 10, 'Why would a Principal Specialist care about Custom Tags in Datadog, per the course?', '[{"label": "A", "text": "They let you attach application-specific context (e.g. from a .NET app) to monitoring data for more precise filtering, exception handling, and facets"}, {"label": "B", "text": "They are purely cosmetic labels with no monitoring function"}, {"label": "C", "text": "They replace the need for any dashboards"}, {"label": "D", "text": "They are only usable for billing purposes"}]'::jsonb, 'A', 'The course covers "Datadog Custom Tags usage from your .NET application" together with exception handling and facets, i.e. using tags for richer filtering/context.'),
  ('Integration Architecture Designer Trailmix', 1, 'What is this Trailmix designed to help a learner prepare for?', '[{"label": "A", "text": "The Integration Architecture Designer exam/certification"}, {"label": "B", "text": "The general Salesforce Administrator exam"}, {"label": "C", "text": "The Skedulo internal onboarding certification"}, {"label": "D", "text": "A generic API-usage badge with no exam connection"}]'::jsonb, 'A', 'The Trailmix is explicitly built to prepare learners for the Integration Architecture Designer exam.'),
  ('Integration Architecture Designer Trailmix', 2, 'Which module in this Trailmix focuses on synchronizing Salesforce records with external data stores by streaming change events?', '[{"label": "A", "text": "Change Data Capture Basics"}, {"label": "B", "text": "External Services"}, {"label": "C", "text": "Apex Integration Services"}, {"label": "D", "text": "Salesforce & Heroku Integration"}]'::jsonb, 'A', 'This module is described exactly this way — streaming change events to sync with external stores.'),
  ('Integration Architecture Designer Trailmix', 3, 'Which module covers connecting an external service to Salesforce and invoking its methods?', '[{"label": "A", "text": "External Services"}, {"label": "B", "text": "Change Data Capture Basics"}, {"label": "C", "text": "Quick Start: Salesforce Connect"}, {"label": "D", "text": "Salesforce & Heroku Integration"}]'::jsonb, 'A', 'This module''s description matches exactly: connecting an external service and invoking methods based on it.'),
  ('Integration Architecture Designer Trailmix', 4, 'Which module is specifically about integrating with external apps using Apex REST and SOAP services?', '[{"label": "A", "text": "Apex Integration Services"}, {"label": "B", "text": "External Services"}, {"label": "C", "text": "Quick Start: Salesforce Connect"}, {"label": "D", "text": "Change Data Capture Basics"}]'::jsonb, 'A', 'This module description matches Apex REST/SOAP-based external app integration.'),
  ('Integration Architecture Designer Trailmix', 5, 'Which module teaches patterns for integrating apps hosted on Heroku with Salesforce?', '[{"label": "A", "text": "Salesforce & Heroku Integration"}, {"label": "B", "text": "External Services"}, {"label": "C", "text": "Change Data Capture Basics"}, {"label": "D", "text": "Quick Start: Salesforce Connect"}]'::jsonb, 'A', 'This module is explicitly about Heroku-Salesforce integration patterns and methodology.'),
  ('Integration Architecture Designer Trailmix', 6, 'A project needs to bring in real-time external data into Salesforce with no custom code. Which project in this Trailmix fits directly?', '[{"label": "A", "text": "Quick Start: Salesforce Connect"}, {"label": "B", "text": "Apex Integration Services"}, {"label": "C", "text": "Change Data Capture Basics"}, {"label": "D", "text": "Salesforce & Heroku Integration"}]'::jsonb, 'A', 'This is explicitly described as a no-code way to integrate external data into an org in real time.'),
  ('Integration Architecture Designer Trailmix', 7, 'A partner needs Salesforce to notify an external system in real time whenever specific Salesforce records change, using platform-native streaming rather than polling. Which module targets this?', '[{"label": "A", "text": "Change Data Capture Basics"}, {"label": "B", "text": "External Services"}, {"label": "C", "text": "Salesforce & Heroku Integration"}, {"label": "D", "text": "Quick Start: Salesforce Connect"}]'::jsonb, 'A', 'Change Data Capture is the module built around streaming change events for exactly this real-time sync use case.'),
  ('Integration Architecture Designer Trailmix', 8, 'A team wants Salesforce Flow to call out to an external REST API and use the response inline. Which module''s subject matter is most relevant?', '[{"label": "A", "text": "External Services"}, {"label": "B", "text": "Change Data Capture Basics"}, {"label": "C", "text": "Salesforce & Heroku Integration"}, {"label": "D", "text": "None of these modules relate to Flow-based external calls"}]'::jsonb, 'A', 'External Services is specifically about connecting an external service to Salesforce and invoking its methods, which underlies Flow-based external callouts.'),
  ('Integration Architecture Designer Trailmix', 9, 'Which two modules in this Trailmix are the shortest, at roughly 20-25 minutes each?', '[{"label": "A", "text": "External Services (~25 mins) and Quick Start: Salesforce Connect (~20 mins)"}, {"label": "B", "text": "Apex Integration Services and Change Data Capture Basics"}, {"label": "C", "text": "Salesforce & Heroku Integration and Apex Integration Services"}, {"label": "D", "text": "All five modules take roughly the same amount of time"}]'::jsonb, 'A', 'These two are the shortest listed items, at ~25 and ~20 minutes respectively.'),
  ('Integration Architecture Designer Trailmix', 10, 'Which module in the Trailmix is the longest and worth the most points?', '[{"label": "A", "text": "Apex Integration Services (~2 hrs, 2,000 points)"}, {"label": "B", "text": "Change Data Capture Basics (~1hr25m, 1,300 points)"}, {"label": "C", "text": "Salesforce & Heroku Integration (~50 mins, 500 points)"}, {"label": "D", "text": "Quick Start: Salesforce Connect (~20 mins, 400 points)"}]'::jsonb, 'A', 'At ~2 hours and 2,000 points, this is the largest module in the Trailmix.'),
  ('Skedulo Premium Support SLA escalation matrix', 1, 'Which support plan tiers include a "Senior support team" and "Support handover" as part of their SLA features?', '[{"label": "A", "text": "Premier and Enterprise only"}, {"label": "B", "text": "All four tiers, including Standard"}, {"label": "C", "text": "Enterprise only"}, {"label": "D", "text": "Standard and Plus only"}]'::jsonb, 'A', 'The plan features table shows Senior support team and Support handover as "No" for Standard/Plus and "Yes" for Premier/Enterprise.'),
  ('Skedulo Premium Support SLA escalation matrix', 2, 'How often are business reviews held for Premier vs. Enterprise customers?', '[{"label": "A", "text": "Premier: 1 per year; Enterprise: Quarterly"}, {"label": "B", "text": "Premier: Quarterly; Enterprise: Monthly"}, {"label": "C", "text": "Both tiers get the same cadence: quarterly"}, {"label": "D", "text": "Business reviews are not offered at any tier"}]'::jsonb, 'A', 'The plan features table lists exactly these cadences for Premier and Enterprise.'),
  ('Skedulo Premium Support SLA escalation matrix', 3, 'Which tiers get ''Development team priority'' on tickets, and to what extent?', '[{"label": "A", "text": "Premier gets P1-only priority; Enterprise gets P1 and P2 priority"}, {"label": "B", "text": "Only Enterprise gets any development team priority, for all priority levels"}, {"label": "C", "text": "All tiers get equal development team priority"}, {"label": "D", "text": "Development team priority does not exist as an SLA feature"}]'::jsonb, 'A', 'The table shows Premier limited to P1 only, while Enterprise extends to P1 and P2.'),
  ('Skedulo Premium Support SLA escalation matrix', 4, 'Which tier is the only one offering 24/7 P1 phone support?', '[{"label": "A", "text": "Enterprise"}, {"label": "B", "text": "Premier"}, {"label": "C", "text": "Plus"}, {"label": "D", "text": "All tiers offer this"}]'::jsonb, 'A', 'The table shows this feature as "No" for Standard, Plus, and Premier, and "Yes" only for Enterprise.'),
  ('Skedulo Premium Support SLA escalation matrix', 5, 'For a Critical P1 issue, what is the Enterprise-tier Initial Response Time, and the Restoration/workaround target?', '[{"label": "A", "text": "30 minutes initial response; 2 business hours restoration/workaround"}, {"label": "B", "text": "1 business hour initial response; 4 business hours restoration/workaround"}, {"label": "C", "text": "Same business day; dependent on complexity"}, {"label": "D", "text": "4 business hours initial response; 2 business days restoration/workaround"}]'::jsonb, 'A', 'The target response times table lists these exact figures for Enterprise/Critical P1.'),
  ('Skedulo Premium Support SLA escalation matrix', 6, 'A Premier customer opens a P1 ticket. What escalation-relevant SLA features are they entitled to that a Plus customer is not, based on the tier feature table?', '[{"label": "A", "text": "Extended P1 support hours (24x5 P1 support), enhanced contracted SLAs, support handover, senior support team access, and P1-only development team priority"}, {"label": "B", "text": "Nothing — Plus and Premier have identical feature sets"}, {"label": "C", "text": "Only enhanced contracted SLAs differ; everything else is identical"}, {"label": "D", "text": "24/7 P1 phone support, which is exclusive to Premier"}]'::jsonb, 'A', 'Cross-referencing the feature table: Premier adds 24x5 P1 support, support handover, senior support team, and P1 dev priority beyond what Plus offers (Plus only has enhanced contracted SLAs and 2hr extended P1 coverage).'),
  ('Skedulo Premium Support SLA escalation matrix', 7, 'A Standard-tier customer emails in a ticket instead of using the Support Portal. How is it categorized, and why might this matter for escalation?', '[{"label": "A", "text": "Automatically categorized as low priority — meaning it may not get the response time the customer actually needs unless re-categorized"}, {"label": "B", "text": "Automatically treated as Critical P1, since email implies urgency"}, {"label": "C", "text": "Emailed tickets are rejected outright and must be resubmitted via the Portal"}, {"label": "D", "text": "Priority is unaffected by submission channel"}]'::jsonb, 'A', 'The doc states tickets opened via email are automatically categorized as low priority — a key escalation-matrix nuance a Specialist should catch when triaging a truly urgent emailed issue.'),
  ('Skedulo Premium Support SLA escalation matrix', 8, 'A ticket is reported as affecting a single user with a cosmetic layout issue and a workaround available. Per the Incident Severity matrix, what priority is this?', '[{"label": "A", "text": "P4 Low"}, {"label": "B", "text": "P1 Critical"}, {"label": "C", "text": "P2 High"}, {"label": "D", "text": "P3 Normal"}]'::jsonb, 'A', 'P4 is defined as a partial/non-critical, primarily cosmetic issue affecting a single user or small number who can work around it — matching this scenario exactly.'),
  ('Skedulo Premium Support SLA escalation matrix', 9, 'A significant function of the Skedulo application is unavailable, and it affects two or more users with a significant business-process impact, but a full outage hasn''t occurred. What priority does this map to?', '[{"label": "A", "text": "P2 High"}, {"label": "B", "text": "P1 Critical"}, {"label": "C", "text": "P3 Normal"}, {"label": "D", "text": "P4 Low"}]'::jsonb, 'A', 'This matches the P2 High definition precisely: a significant function unavailable/faulted, affecting two-plus users with significant business impact — short of the full, no-workaround P1 scenario.'),
  ('Skedulo Premium Support SLA escalation matrix', 10, 'Why might a Specialist need to re-categorize a ticket that a customer submitted as "Low" priority?', '[{"label": "A", "text": "Because issue priority may be re-categorized by Skedulo Support based on criticality definitions and actual impact, not just the requester''s initial label"}, {"label": "B", "text": "Priority can never be changed once a customer sets it"}, {"label": "C", "text": "Only Enterprise customers'' priorities can be adjusted by Support"}, {"label": "D", "text": "Re-categorization requires the customer''s explicit written consent first"}]'::jsonb, 'A', 'The doc explicitly states priority may be re-categorized by Skedulo Support based on the criticality definitions and actual impact, regardless of how the requester initially tagged it.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 1, 'What is the subtitle of this course, describing its overall approach?', '[{"label": "A", "text": "How to choose and use KPIs effectively, using BSC, Basic Statistics and Dashboards"}, {"label": "B", "text": "A deep dive into SQL query optimization"}, {"label": "C", "text": "A certification prep course for PMP only"}, {"label": "D", "text": "An introduction to Python for data science"}]'::jsonb, 'A', 'The course subtitle is "How to choose and use KPIs effectively (using BSC, Basic Statistics and Dashboards)."'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 2, 'Which section of the course is by far the longest?', '[{"label": "A", "text": "\"Performance analysis and reporting\" (26 lectures, 1 hour 19 minutes)"}, {"label": "B", "text": "\"Course introduction\" (3 lectures, 4 minutes)"}, {"label": "C", "text": "\"Wrap-up\" (1 lecture, 2 minutes)"}, {"label": "D", "text": "\"Bonus\" (1 lecture, 1 minute)"}]'::jsonb, 'A', 'At 26 lectures and 1hr19min, "Performance analysis and reporting" is the largest section, nearly half the course.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 3, 'What is the instructor''s professional background, per her bio?', '[{"label": "A", "text": "CSM and SSBB (Six Sigma Black Belt from the Indian Statistical Institute, Delhi) and a Master of Total Quality Management, with 12+ years as a trainer and consultant"}, {"label": "B", "text": "A first-time instructor with no prior consulting experience"}, {"label": "C", "text": "A full-time software engineer with no quality-management background"}, {"label": "D", "text": "A marketing copywriter who moved into data analytics"}]'::jsonb, 'A', 'Deepika Misra describes herself as CSM, SSBB (Indian Statistical Institute, Delhi), and Master of Total Quality Management, with over 12 years of experience.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 4, 'Which four tools does Part 1 (KPI selection) teach for selecting the right key indicators?', '[{"label": "A", "text": "Balanced Scorecard methodology, Fishbone diagram, KPI tree, and Decision matrix"}, {"label": "B", "text": "SWOT analysis, PESTLE, Ansoff Matrix, and Porter''s Five Forces"}, {"label": "C", "text": "Gantt charts, critical path method, and burn-down charts only"}, {"label": "D", "text": "Regression analysis and hypothesis testing exclusively"}]'::jsonb, 'A', 'Part 1 explicitly lists these four tools for helping learners select the right key indicators to assess organizational performance.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 5, 'What method does the course use to set targets and thresholds during KPI implementation?', '[{"label": "A", "text": "The baselining method with the help of an XMR/IMR control chart"}, {"label": "B", "text": "Flipping a coin to decide arbitrary thresholds"}, {"label": "C", "text": "Copying whatever thresholds a competitor uses"}, {"label": "D", "text": "Setting all thresholds to zero by default"}]'::jsonb, 'A', 'Part 2 explains how to set targets and thresholds "using the baselining method with the help of XMR/ IMR control chart."'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 6, 'What dashboard-building tools does the course teach, and what prior experience does it say is needed?', '[{"label": "A", "text": "Simple dashboards in Excel using Pivot tables (no VBA experience needed) and Power BI"}, {"label": "B", "text": "Dashboards built exclusively in Tableau, requiring advanced scripting"}, {"label": "C", "text": "Only paper-based dashboards with no software"}, {"label": "D", "text": "Custom dashboards coded in JavaScript from scratch"}]'::jsonb, 'A', 'The course explicitly teaches creating simple dashboards in Excel using Pivot tables, stating "NO VBA experience needed," plus Power BI.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 7, 'A Specialist has a long list of metrics they currently track and needs to narrow it down to the ones that actually indicate performance rather than just being interesting numbers. Which foundational concept from Part 1 addresses this directly?', '[{"label": "A", "text": "Learning to select KPIs that are the \"real\" key indicators, distinguishing them from other metrics"}, {"label": "B", "text": "Tracking every available metric with equal weight"}, {"label": "C", "text": "Removing all metrics and reporting nothing"}, {"label": "D", "text": "Only using metrics that competitors publish publicly"}]'::jsonb, 'A', 'The first stated learning outcome is to "select KPIs that are the ''real'' Key indicators," which is exactly this filtering task.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 8, 'Before building any dashboards, the course says learners must first work through fundamental statistical concepts. What is this analysis step for?', '[{"label": "A", "text": "To make learners familiar with basic statistical terms and when and where to use them while creating reports and dashboards"}, {"label": "B", "text": "To prepare learners for an unrelated finance certification exam"}, {"label": "C", "text": "To replace the need for any KPI selection work"}, {"label": "D", "text": "To teach programming languages unrelated to reporting"}]'::jsonb, 'A', 'The description states the analysis section is included to make learners "verse with the basic statistical terms and when/ where to use them while creating reports and dashboards."'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 9, 'Which roles does the course explicitly call out in its "Who this course is for" section?', '[{"label": "A", "text": "Management students and project management aspirants, new project managers who must start using KPIs and create dashboards, and new executives implementing strategies"}, {"label": "B", "text": "Only certified Six Sigma Master Black Belts"}, {"label": "C", "text": "Exclusively software developers writing dashboard code"}, {"label": "D", "text": "Retail cashiers with no reporting responsibilities"}]'::jsonb, 'A', 'These three groups are listed verbatim in the course''s "Who this course is for" section.'),
  ('KPI Reporting & Dashboards — Search Keywords: "kpi dashboard reporting"', 10, 'A Specialist wants only the high-level, one-hour foundations of KPIs rather than the full implementation and dashboarding content. What does the course description itself suggest for that need?', '[{"label": "A", "text": "It points the learner to a separate, shorter course called \"Fundamentals of KPIs\" for just the foundation level"}, {"label": "B", "text": "It says no shorter alternative exists anywhere"}, {"label": "C", "text": "It recommends skipping KPIs altogether"}, {"label": "D", "text": "It insists the full 3-hour course is the only option available"}]'::jsonb, 'A', 'The description notes: "If you are looking for just the foundation level course (1 hour), have a look at the course- ''Fundamentals of KPIs.''"'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 1, 'Which section of this course has the most lectures?', '[{"label": "A", "text": "\"People\" (20 lectures, 47 minutes)"}, {"label": "B", "text": "\"Reports\" (1 lecture, 13 minutes)"}, {"label": "C", "text": "\"Start Here\" (5 lectures, 4 minutes)"}, {"label": "D", "text": "\"Extras\" (5 lectures, 2 minutes)"}]'::jsonb, 'A', '"People" has 20 lectures, more than any other section in the course.'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 2, 'Which section has the longest total running time?', '[{"label": "A", "text": "\"Business Rules\" (15 lectures, 1 hour 14 minutes)"}, {"label": "B", "text": "\"Guide & Gather\" (7 lectures, 18 minutes)"}, {"label": "C", "text": "\"Channels\" (11 lectures, 55 minutes)"}, {"label": "D", "text": "\"Reports\" (1 lecture, 13 minutes)"}]'::jsonb, 'A', 'At 1 hour 14 minutes, "Business Rules" is the single longest section by running time.'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 3, 'What is the instructor''s stated professional background?', '[{"label": "A", "text": "An 11-year Zendesk Premier Partner and certified consultant who has served clients including Khan Academy, Porsche, and Lowes"}, {"label": "B", "text": "A first-time freelancer with no enterprise client history"}, {"label": "C", "text": "A Salesforce-only consultant with no Zendesk experience"}, {"label": "D", "text": "An anonymous course aggregator with no named instructor"}]'::jsonb, 'A', 'Dominic The CX Guy describes 11 years as a Zendesk Consultant & Premier Partner, Zendesk certified, with clients including KhanAcademy, Porsche, and Lowes.'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 4, 'Which set of Zendesk features does the course explicitly walk through with best practices?', '[{"label": "A", "text": "Triggers, Bots, Omnichannel, Web Widget, SLAs, and Reporting"}, {"label": "B", "text": "Only email templates"}, {"label": "C", "text": "Payroll processing tools"}, {"label": "D", "text": "A generic project-management Kanban board"}]'::jsonb, 'A', 'The "What you''ll learn" section lists a "Feature walkthrough & best practices: Triggers, Bots, Omnichannel, Web Widget, SLAs, Reporting."'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 5, 'What certification outcome does the course explicitly aim to help learners achieve?', '[{"label": "A", "text": "Easily passing the official Zendesk certification exam"}, {"label": "B", "text": "Passing a general PMP exam"}, {"label": "C", "text": "Passing a Salesforce Administrator exam"}, {"label": "D", "text": "No certification is mentioned anywhere in the course"}]'::jsonb, 'A', 'One of the stated learning outcomes is to "Easily pass the official Zendesk certification exam."'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 6, 'Which of these is explicitly listed in the "Who this course is for" section?', '[{"label": "A", "text": "A CSM wanting to send the right reports to management"}, {"label": "B", "text": "A first-year university student with no CX experience"}, {"label": "C", "text": "A hardware repair technician"}, {"label": "D", "text": "A payroll administrator"}]'::jsonb, 'A', 'The course lists "CSM wanting to send the right reports to management" among its intended audiences.'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 7, 'A Senior Specialist needs to build a report that flags which accounts generate the most revenue so the team can prioritize them. Which stated course benefit matches this need?', '[{"label": "A", "text": "Creating reports to keep an eye out for the important clients that bring in the most money for the company"}, {"label": "B", "text": "Deleting all client data to simplify reporting"}, {"label": "C", "text": "Randomly sampling tickets with no regard to account value"}, {"label": "D", "text": "Ignoring revenue entirely when building reports"}]'::jsonb, 'A', 'The description states the course helps you "Create reports to keep an eye our for the important clients that bring in the most money for your company."'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 8, 'Agents are slow to react to information buried in existing reports, causing delayed responses to at-risk accounts. Which stated course outcome addresses this problem?', '[{"label": "A", "text": "Getting better reporting so agents will act quicker on information"}, {"label": "B", "text": "Removing all dashboards so agents rely purely on memory"}, {"label": "C", "text": "Increasing the number of required approval steps for every ticket"}, {"label": "D", "text": "Switching agents to a different, unrelated ticketing tool"}]'::jsonb, 'A', 'The course explicitly promises to help learners "Get better reporting so agents will act quicker on information."'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 9, 'A Senior Specialist wants dashboard and reporting data that reflects activity across several connected tools, not just Zendesk alone. Which stated benefit of the course matches this need?', '[{"label": "A", "text": "Integrating systems together to see client data across all platforms"}, {"label": "B", "text": "Restricting all data to a single spreadsheet with no integrations"}, {"label": "C", "text": "Removing Zendesk from the workflow entirely"}, {"label": "D", "text": "Manually re-typing data between systems every day"}]'::jsonb, 'A', 'The course lists "Integrate your systems together to see client data across all platforms" as one of its outcomes.'),
  ('Advanced Dashboard & Reporting Design — Search Keywords: "zendesk explore reporting" / "advanced dashboard design"', 10, 'Which single-lecture section is dedicated specifically to reporting output, distinct from the broader "Business Rules" section?', '[{"label": "A", "text": "\"Reports\" (1 lecture, 13 minutes)"}, {"label": "B", "text": "\"Extras\" (5 lectures, 2 minutes)"}, {"label": "C", "text": "\"Guide & Gather\" (7 lectures, 18 minutes)"}, {"label": "D", "text": "\"Start Here\" (5 lectures, 4 minutes)"}]'::jsonb, 'A', 'The course content outline lists a dedicated "Reports" section of 1 lecture and 13 minutes, separate from "Business Rules."'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 1, 'For a High P2 issue, how does the Resolution/workaround commitment differ between Premier and Enterprise?', '[{"label": "A", "text": "Premier: dependent on complexity (no fixed target); Enterprise: 2 business days"}, {"label": "B", "text": "Both tiers commit to the same fixed 2-business-day resolution"}, {"label": "C", "text": "Premier commits to same-day resolution; Enterprise has none"}, {"label": "D", "text": "Neither tier offers any resolution commitment for P2"}]'::jsonb, 'A', 'The target response times table shows Premier P2 Resolution as "Dependent on complexity" while Enterprise commits to a 2-business-day Restoration/workaround target — a meaningful admin-level distinction between the two paid tiers.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 2, 'For Normal P3 and Low P4 issues on Premier and Enterprise, what does "Resolution" typically map to, rather than a fixed time commitment?', '[{"label": "A", "text": "Scheduled releases"}, {"label": "B", "text": "A same-day guarantee"}, {"label": "C", "text": "A dedicated engineering sprint"}, {"label": "D", "text": "Immediate hotfix deployment"}]'::jsonb, 'A', 'The table lists "Resolution: Scheduled releases" for P3/P4 on both Premier and Enterprise — these lower-severity issues ride the normal release cadence rather than getting an expedited fix commitment.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 3, 'An admin is deciding whether Enterprise is worth the upgrade purely for named-account support. Which feature is Enterprise-exclusive on that front?', '[{"label": "A", "text": "Named Skedulo representative"}, {"label": "B", "text": "24/7 Support Portal access"}, {"label": "C", "text": "Business hours support coverage"}, {"label": "D", "text": "Enhanced contracted SLAs"}]'::jsonb, 'A', 'The feature table marks "Named Skedulo representative" as No for Standard/Plus/Premier and Yes only for Enterprise.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 4, 'How does Super-User profile allocation scale across the four tiers for 24/7 Support Portal access?', '[{"label": "A", "text": "1 (Standard), 3 (Plus), 5 (Premier), unlimited (Enterprise)"}, {"label": "B", "text": "All four tiers get unlimited Super-User profiles"}, {"label": "C", "text": "Only Enterprise gets any Super-User profiles at all"}, {"label": "D", "text": "1 profile flat across every tier, no scaling"}]'::jsonb, 'A', 'The feature table lists this exact progression of Super-User profile counts by tier.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 5, 'What exactly does "Extended support hours coverage" mean at the Plus tier versus the Premier tier?', '[{"label": "A", "text": "Plus: 2 hours before/after business hours for P1 incidents; Premier: full 24x5 P1 support"}, {"label": "B", "text": "Plus and Premier both get identical 24x5 P1 coverage"}, {"label": "C", "text": "Plus gets no extended hours; Premier gets 2 hours before/after"}, {"label": "D", "text": "Extended hours only apply to Enterprise, not Plus or Premier"}]'::jsonb, 'A', 'The feature table distinguishes these precisely — a limited before/after window for Plus vs. full 24x5 P1 coverage for Premier.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 6, 'An admin needs to explain why a P1 ticket on the Standard plan might not get a same-day response every time. What does the target response times table actually commit to for Standard/P1?', '[{"label": "A", "text": "\"Same business day or 8 hours\" as the Initial Response Time, with Resolution \"dependent on complexity\" — no fixed resolution guarantee"}, {"label": "B", "text": "A guaranteed 30-minute initial response identical to Enterprise"}, {"label": "C", "text": "A guaranteed 4-hour resolution regardless of complexity"}, {"label": "D", "text": "Standard-tier P1 tickets have no SLA commitment whatsoever"}]'::jsonb, 'A', 'This is the literal Standard/Critical P1 row: a same-day-or-8-hour initial response, with resolution explicitly uncommitted ("dependent on complexity").'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 7, 'Which SLA feature differentiates Enterprise from every other tier in terms of raw phone access during an incident?', '[{"label": "A", "text": "24/7 P1 Phone support"}, {"label": "B", "text": "24/7 Support Portal access (all tiers have this)"}, {"label": "C", "text": "Business hours support coverage"}, {"label": "D", "text": "Enhanced contracted SLAs"}]'::jsonb, 'A', '24/7 Support Portal access is common to all tiers; 24/7 P1 Phone support is the Enterprise-exclusive phone-access feature.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 8, 'An admin is auditing whether their team is entitled to quarterly business reviews with Skedulo. What tier do they need at minimum?', '[{"label": "A", "text": "Enterprise (Premier only gets 1 per year, not quarterly)"}, {"label": "B", "text": "Premier is sufficient for quarterly reviews"}, {"label": "C", "text": "Plus already includes quarterly business reviews"}, {"label": "D", "text": "Business reviews are quarterly for every paid tier"}]'::jsonb, 'A', 'Quarterly business reviews are an Enterprise-only cadence; Premier gets just one per year.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 9, 'Why might a Support Specialist need to distinguish "Initial Response Time" from "Resolution" or "Restoration/workaround" when setting customer expectations on a Premier P1 ticket?', '[{"label": "A", "text": "Premier''s P1 Initial Response Time is a fixed 1 business hour, but Resolution is explicitly ''dependent on complexity'' — so a fast first response doesn''t imply a fast fix"}, {"label": "B", "text": "Both metrics are always identical at every tier, so there''s no distinction to make"}, {"label": "C", "text": "Resolution time is always faster than Initial Response Time"}, {"label": "D", "text": "Premier has no Initial Response Time commitment, only a Resolution commitment"}]'::jsonb, 'A', 'This is exactly the nuance in the table: Premier commits to a fast first response (1 business hour) without committing to a fixed resolution timeline for P1.'),
  ('Skedulo Technical Support Plans and SLAs — administrator-level reference', 10, 'From an administrator''s standpoint, what is the practical effect of the ''Development team priority'' feature difference between Premier (P1 only) and Enterprise (P1, P2 only)?', '[{"label": "A", "text": "A Premier customer''s P2 issues do not get elevated engineering priority the way an Enterprise customer''s P2 issues do"}, {"label": "B", "text": "Premier customers get P1 and P2 priority, Enterprise gets P1 only"}, {"label": "C", "text": "There is no practical difference; both get equal engineering attention on all priorities"}, {"label": "D", "text": "This feature only affects Salesforce-based tenants, never Pulse Platform tenants"}]'::jsonb, 'A', 'Since Premier''s development-team priority is scoped to P1 only while Enterprise extends to P1 and P2, a Premier customer''s P2 ticket does not receive the same elevated engineering attention an Enterprise P2 ticket would.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 1, 'Which section of the course is the longest, by a wide margin?', '[{"label": "A", "text": "\"AI-Powered Contract Management\" (9 lectures, 1 hour 5 minutes)"}, {"label": "B", "text": "\"Risk Management in Contracts\" (3 lectures, 8 minutes)"}, {"label": "C", "text": "\"Closing and Renewing Contracts\" (4 lectures, 10 minutes)"}, {"label": "D", "text": "\"Executing and Managing Contracts\" (4 lectures, 9 minutes)"}]'::jsonb, 'A', 'At 9 lectures and 1 hour 5 minutes, "AI-Powered Contract Management" is far longer than any other section, which otherwise run 8-16 minutes each.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 2, 'What is the instructor''s stated professional background?', '[{"label": "A", "text": "Over two decades in IT Service Management, largely implementing ServiceNow at firms including Accenture and Deloitte"}, {"label": "B", "text": "A recent law school graduate with no industry experience"}, {"label": "C", "text": "A full-time marketing consultant unrelated to IT or contracts"}, {"label": "D", "text": "An anonymous, uncredited contributor"}]'::jsonb, 'A', 'Arno Esterhuizen describes over two decades in ITSM, much of it implementing ServiceNow, earned inside firms including Accenture and Deloitte.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 3, 'Which interactive course feature lets learners practice contract negotiation scenarios?', '[{"label": "A", "text": "Role Play, including AI role play exercises"}, {"label": "B", "text": "A multiple-choice-only quiz with no practice scenarios"}, {"label": "C", "text": "A group video call requirement"}, {"label": "D", "text": "An in-person workshop only"}]'::jsonb, 'A', 'The course listing highlights "Role Play" as an included feature, and the description mentions "AI role play exercises."'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 4, 'Which three specific clause categories does the course say learners will identify and interpret?', '[{"label": "A", "text": "Risk, liability, and service level agreements"}, {"label": "B", "text": "Only pricing tables, with nothing else"}, {"label": "C", "text": "Marketing claims and brand guidelines"}, {"label": "D", "text": "Payroll tax withholding tables"}]'::jsonb, 'A', 'One learning objective is to "identify and interpret key contract clauses and terms, including risk, liability, and service level agreements."'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 5, 'Which group is explicitly named in the "Who this course is for" section?', '[{"label": "A", "text": "Procurement and supply chain professionals managing vendor agreements"}, {"label": "B", "text": "Elementary school teachers"}, {"label": "C", "text": "Professional athletes"}, {"label": "D", "text": "Retail cashiers"}]'::jsonb, 'A', '"Procurement and supply chain professionals managing vendor agreements" is explicitly listed as an intended audience.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 6, 'What does the course say a strategic approach to contract management should achieve, per its stated learning objectives?', '[{"label": "A", "text": "Align with organizational goals and reduce legal and financial risk"}, {"label": "B", "text": "Maximize the number of contract disputes filed each quarter"}, {"label": "C", "text": "Remove all monitoring of contract performance"}, {"label": "D", "text": "Ignore organizational goals in favor of speed alone"}]'::jsonb, 'A', 'The course aims to help learners "develop a strategic approach to contract management that aligns with organizational goals and reduces legal and financial risk."'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 7, 'A Principal Specialist is midway through negotiating an SLA-heavy renewal with a major account and wants to identify where liability exposure sits before signing. Which stated learning objective covers this?', '[{"label": "A", "text": "Identifying and interpreting key contract clauses and terms, including risk, liability, and service level agreements"}, {"label": "B", "text": "Learning to draft marketing brochures for the account"}, {"label": "C", "text": "Learning payroll processing for the vendor"}, {"label": "D", "text": "Ignoring liability clauses since they rarely matter"}]'::jsonb, 'A', 'This objective directly covers identifying risk, liability, and SLA clauses before finalizing a negotiation.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 8, 'A contract is approaching its end date and the account team must decide whether to renew, renegotiate, or let it lapse. Which section directly addresses this stage?', '[{"label": "A", "text": "\"Closing and Renewing Contracts\""}, {"label": "B", "text": "\"Introduction to Contract Management\""}, {"label": "C", "text": "\"Drafting Contracts\""}, {"label": "D", "text": "\"Pre-Contract Stage – Planning and Negotiation\""}]'::jsonb, 'A', '"Closing and Renewing Contracts" is the section dedicated to this exact end-of-lifecycle decision point.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 9, 'A Principal Specialist wants to use generative AI tools to speed up reviewing and managing contract lifecycles. Which section is built specifically for this?', '[{"label": "A", "text": "\"AI-Powered Contract Management\""}, {"label": "B", "text": "\"Compliance and Performance Monitoring\""}, {"label": "C", "text": "\"Risk Management in Contracts\""}, {"label": "D", "text": "\"Executing and Managing Contracts\""}]'::jsonb, 'A', 'This 9-lecture, 1-hour-5-minute section is dedicated to using generative AI to manage the contract lifecycle.'),
  ('Strategic Account Management and Contract Negotiation — Search Keywords: "negotiating customer contracts and SLAs"', 10, 'Beyond a single deal, a Principal Specialist wants to build a long-term, mutually beneficial relationship with a strategic account across multiple contract cycles. Which section addresses this?', '[{"label": "A", "text": "\"Strategic Contracting and Relationship Building\""}, {"label": "B", "text": "\"Risk Management in Contracts\""}, {"label": "C", "text": "\"Drafting Contracts\""}, {"label": "D", "text": "\"Introduction to Contract Management\""}]'::jsonb, 'A', 'This section is specifically framed around strategic contracting and long-term relationship building, beyond a single transaction.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 1, 'Which section of the course has the longest running time, despite not having the most lectures?', '[{"label": "A", "text": "\"Applying ADDIE in Real-World Projects\" (6 lectures, 36 minutes)"}, {"label": "B", "text": "\"Introduction to ADDIE\" (3 lectures, 12 minutes)"}, {"label": "C", "text": "\"Conclusion\" (2 lectures, 9 minutes)"}, {"label": "D", "text": "\"Training Document Template using the ADDIE Model\" (1 lecture, 2 minutes)"}]'::jsonb, 'A', 'At 36 minutes, this section runs longer than any of the five 8-lecture ADDIE phase sections, despite having only 6 lectures.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 2, 'What five phases make up the ADDIE model, as structured in this course?', '[{"label": "A", "text": "Analysis, Design, Development, Implementation, and Evaluation"}, {"label": "B", "text": "Plan, Build, Ship, Measure, and Repeat"}, {"label": "C", "text": "Discover, Define, Design, Deliver, and Debrief"}, {"label": "D", "text": "Assess, Approve, Author, Assign, and Archive"}]'::jsonb, 'A', 'The course dedicates one 8-lecture section to each of these five ADDIE phases: Analysis, Design, Development, Implementation, Evaluation.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 3, 'What is the instructor''s stated background?', '[{"label": "A", "text": "Zubin Rashid, Founder of the Learning and Development Academy, with 25+ years of experience across 5 countries"}, {"label": "B", "text": "A recent graduate with under one year of training experience"}, {"label": "C", "text": "A full-time software developer with no training and development background"}, {"label": "D", "text": "An uncredited, anonymous author"}]'::jsonb, 'A', 'Zubin Rashid is described as Founder of the Learning and Development Academy, with 25+ years of experience having lived and worked in 5 countries.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 4, 'What does the ANALYSIS phase focus on, per the "What you''ll learn" section?', '[{"label": "A", "text": "Analyzing training needs and identifying performance gaps to inform the training design process"}, {"label": "B", "text": "Writing the final certificate of completion"}, {"label": "C", "text": "Selecting a video conferencing tool"}, {"label": "D", "text": "Designing the course marketing page"}]'::jsonb, 'A', 'The stated objective for this phase is to "Analyze training needs and identify performance gaps to inform the training design process."'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 5, 'What assessment approach does the EVALUATION phase teach, per the "What you''ll learn" section?', '[{"label": "A", "text": "Evaluating training programs using formative and summative assessment methods"}, {"label": "B", "text": "Skipping evaluation entirely once training is delivered"}, {"label": "C", "text": "Relying solely on anecdotal manager opinions"}, {"label": "D", "text": "Using only a single pass/fail exam with no other method"}]'::jsonb, 'A', 'The course states learners will "Evaluate training programs using formative and summative assessment methods to measure effectiveness."'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 6, 'What practical resource does the course provide near the end, tied directly to applying the model?', '[{"label": "A", "text": "A Training Document Template using the ADDIE Model"}, {"label": "B", "text": "A certificate template unrelated to ADDIE"}, {"label": "C", "text": "A spreadsheet of unrelated software licenses"}, {"label": "D", "text": "A generic slide deck template with no ADDIE content"}]'::jsonb, 'A', 'The course content lists a dedicated one-lecture section titled "Training Document Template using the ADDIE Model."'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 7, 'A Principal Specialist notices new hires are consistently confused by the same product feature despite completing onboarding, and needs to figure out why before redesigning anything. Which ADDIE phase should they start with?', '[{"label": "A", "text": "Analysis"}, {"label": "B", "text": "Development"}, {"label": "C", "text": "Implementation"}, {"label": "D", "text": "Evaluation"}]'::jsonb, 'A', 'Analysis is explicitly about analyzing training needs and identifying performance gaps before any redesign begins.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 8, 'After finalizing new training materials, a Principal Specialist must roll them out to a distributed global support team and ensure the delivery goes smoothly. Which ADDIE phase covers this?', '[{"label": "A", "text": "Implementation"}, {"label": "B", "text": "Design"}, {"label": "C", "text": "Analysis"}, {"label": "D", "text": "Evaluation"}]'::jsonb, 'A', 'The course''s stated objective for this phase is to "Implement training initiatives efficiently, ensuring smooth delivery and effective facilitation."'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 9, 'Several months after a new training program launches, a Principal Specialist wants to measure whether it actually improved performance outcomes. Which ADDIE phase directly addresses this?', '[{"label": "A", "text": "Evaluation"}, {"label": "B", "text": "Design"}, {"label": "C", "text": "Development"}, {"label": "D", "text": "Analysis"}]'::jsonb, 'A', 'Evaluation is the phase dedicated to measuring effectiveness and driving continuous improvement using formative and summative methods.'),
  ('Training Program Design for Adult Learners — Search Keywords: "instructional design fundamentals"', 10, 'A Principal Specialist has learned the ADDIE theory but wants to see how it plays out in completed, real-world training projects rather than in the abstract. Which section addresses this need directly?', '[{"label": "A", "text": "\"Applying ADDIE in Real-World Projects\""}, {"label": "B", "text": "\"Introduction to ADDIE\""}, {"label": "C", "text": "\"Future Trends in Training and Development\""}, {"label": "D", "text": "\"Conclusion\""}]'::jsonb, 'A', 'This 6-lecture, 36-minute section is specifically dedicated to applying the ADDIE model to real-world projects.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 1, 'What does the course teach as the first steps in preparing an organization for a crisis?', '[{"label": "A", "text": "Identifying audiences and assembling a crisis response team"}, {"label": "B", "text": "Filing an insurance claim immediately"}, {"label": "C", "text": "Issuing a press release before any internal analysis"}, {"label": "D", "text": "Terminating the employee closest to the incident"}]'::jsonb, 'A', 'The description states the course covers "identifying audiences, assembling a crisis response team, crafting an initial statement, and evaluating your response once the crisis has passed."'),
  ('Crisis Communication: Essential Skills for Crisis Management', 2, 'Who are the audiences the course teaches you to communicate with during a crisis?', '[{"label": "A", "text": "Employees, customers, suppliers, media, and the public at large"}, {"label": "B", "text": "Only the company''s legal department"}, {"label": "C", "text": "Only the CEO"}, {"label": "D", "text": "Only external media, with no internal communication"}]'::jsonb, 'A', 'The description explicitly lists these five groups as the audiences the course teaches you to prepare to communicate with.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 3, 'What quality does the course say is "critical during any crisis and emergency"?', '[{"label": "A", "text": "Precise, timely and relevant information"}, {"label": "B", "text": "Withholding all information until the crisis fully resolves"}, {"label": "C", "text": "Delegating all communication to outside consultants"}, {"label": "D", "text": "Vague, general statements to avoid commitment"}]'::jsonb, 'A', 'The description states "Precise, timely and relevant information is critical during any crisis and emergency."'),
  ('Crisis Communication: Essential Skills for Crisis Management', 4, 'How many total lectures and sections does the course have?', '[{"label": "A", "text": "5 sections, 13 lectures, about 57 minutes total"}, {"label": "B", "text": "20 sections, 100 lectures"}, {"label": "C", "text": "1 section, 1 lecture"}, {"label": "D", "text": "5 sections, 50 lectures"}]'::jsonb, 'A', 'The course content lists 5 sections • 13 lectures • 57m total length.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 5, 'What should organizations do, per the course, once a crisis has passed?', '[{"label": "A", "text": "Evaluate the crisis response that was given"}, {"label": "B", "text": "Immediately delete all records of the incident"}, {"label": "C", "text": "Avoid any follow-up communication"}, {"label": "D", "text": "Assign blame publicly to a specific employee"}]'::jsonb, 'A', 'The description states the process includes "evaluating your response once the crisis has passed," as part of building organizational resilience.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 6, 'Who is this course explicitly designed for?', '[{"label": "A", "text": "PR executives, communication teams, and business owners"}, {"label": "B", "text": "Only software engineers"}, {"label": "C", "text": "Only external auditors"}, {"label": "D", "text": "Only the finance department"}]'::jsonb, 'A', 'The "Who this course is for" section lists PR executives, Communication Teams, and Business Owners.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 7, 'A support Specialist notices a major outage is affecting customers and the media is starting to ask questions. Per the course''s crisis communication process, what should happen first, before any public statement goes out?', '[{"label": "A", "text": "Identify the different audiences affected and assemble/engage the crisis communication team"}, {"label": "B", "text": "Immediately post an unreviewed statement to social media"}, {"label": "C", "text": "Wait for the crisis to fully end before doing anything"}, {"label": "D", "text": "Have a single engineer improvise a public statement without any process"}]'::jsonb, 'A', 'The course''s process explicitly starts with identifying audiences and assembling the crisis response team before crafting any statement.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 8, 'After a resolved incident, a Specialist is asked to help improve the team''s crisis response for next time. What does the course say this evaluation step should accomplish?', '[{"label": "A", "text": "Assess the response given during the crisis to build future resilience and refine the communication strategy for next time"}, {"label": "B", "text": "Nothing further is needed once the technical issue is fixed"}, {"label": "C", "text": "Only the marketing team should be involved in any post-incident work"}, {"label": "D", "text": "The evaluation should be skipped to save time"}]'::jsonb, 'A', 'The course frames post-crisis evaluation as integral to "overall organizational resilience and strategic communication planning," not a step to skip.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 9, 'Per the course, why does proactive crisis communication planning matter even before any specific crisis occurs?', '[{"label": "A", "text": "It lets organizations anticipate and mitigate potential issues before they escalate, not just react once a crisis has already started"}, {"label": "B", "text": "Planning ahead is discouraged because crises are always unpredictable"}, {"label": "C", "text": "Only reactive, in-the-moment communication has any value"}, {"label": "D", "text": "Proactive planning is only relevant to the legal department"}]'::jsonb, 'A', 'The description states the course "delves into the proactive measures organizations can take to minimize the impact of potential crises," beyond just reacting.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 10, 'A Specialist is asked to draft the very first public statement during an active incident. Per the course''s stated process, what step does that fall under?', '[{"label": "A", "text": "Crafting an initial statement, which comes after audiences are identified and the response team is assembled"}, {"label": "B", "text": "Evaluating the response after the crisis has passed"}, {"label": "C", "text": "A step the course says should be skipped entirely"}, {"label": "D", "text": "A purely legal function outside the crisis communication process"}]'::jsonb, 'A', 'The course''s process sequence is: identify audiences, assemble the crisis response team, craft an initial statement, then evaluate the response after the crisis passes.'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 1, 'Which expert problem-analysis techniques does the course teach for Problem Management?', '[{"label": "A", "text": "Mind maps, Kepner-Tregoe analysis, and Five Whys"}, {"label": "B", "text": "Only a single generic checklist with no named technique"}, {"label": "C", "text": "SWOT analysis exclusively"}, {"label": "D", "text": "A/B testing"}]'::jsonb, 'A', 'The description states students "learn and practice best practices of expert analysis such as mind maps, Kepner Tregoe analysis, Five Whys, and others" for Problem management.'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 2, 'What does the course teach about building Incident and Request "models"?', '[{"label": "A", "text": "Creating models for certain types of user calls, i.e. standardized handling patterns for specific recurring Incident/Request types"}, {"label": "B", "text": "Building 3D physical models of the IT department"}, {"label": "C", "text": "Financial models for departmental budgeting only"}, {"label": "D", "text": "The course does not cover this topic"}]'::jsonb, 'A', 'The description states students "learn and practice on creating Incident and Request models for certain types of user calls."'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 3, 'What tool does the course teach for defining Service Desk / supporting-software requirements?', '[{"label": "A", "text": "The MoSCoW prioritizing matrix"}, {"label": "B", "text": "A random lottery-based prioritization method"}, {"label": "C", "text": "A single fixed requirements template with no prioritization"}, {"label": "D", "text": "Simple alphabetical ordering of requirements"}]'::jsonb, 'A', 'The description explicitly states students "learn and try the MoSCoW prioritizing matrix to define requirements for a Service desk and supporting software systems."'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 4, 'What work-regime patterns does the course teach you to define for a Service Desk?', '[{"label": "A", "text": "5x8, 24x7, and other work regimes"}, {"label": "B", "text": "Only a single fixed 9-to-5 schedule"}, {"label": "C", "text": "Regimes are not covered by the course"}, {"label": "D", "text": "Only seasonal, seasonal-only staffing patterns"}]'::jsonb, 'A', 'The description states students "learn how define 5x8, 24x7 and other work regimes, and develop a Service desk structure."'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 5, 'Besides Incident Management, what other Service Operation processes does Section 2 of the course cover?', '[{"label": "A", "text": "Problem management, Event management (service monitoring and control), and serving user requests (RFS)"}, {"label": "B", "text": "Only Incident Management, with no other processes"}, {"label": "C", "text": "Payroll processing and expense reporting"}, {"label": "D", "text": "Marketing campaign management"}]'::jsonb, 'A', 'Section 2 ("Service Operation processes") lists lectures on Incident Management, Problem management, Event management, and Serving user requests (RFS).'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 6, 'What does the course''s updated version add regarding modern IT operations trends?', '[{"label": "A", "text": "An AIOps overview, covering its functions, advantages, and risks/challenges"}, {"label": "B", "text": "A cryptocurrency mining module"}, {"label": "C", "text": "A section on graphic design"}, {"label": "D", "text": "Nothing has been added since the original release"}]'::jsonb, 'A', 'The description states "the updated version includes AIOps overview - its functions, advantages and risks/challenges as well."'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 7, 'A Specialist keeps seeing the same category of incident recur weekly with no permanent fix, only quick workarounds. Which course topic addresses digging into the underlying cause rather than repeating the same fix?', '[{"label": "A", "text": "Problem management, using techniques like Five Whys or Kepner-Tregoe analysis to find and address the root cause"}, {"label": "B", "text": "Event management, which only monitors infrastructure health"}, {"label": "C", "text": "Request fulfillment, which handles standard service requests, not recurring faults"}, {"label": "D", "text": "None of the course''s topics address recurring incidents"}]'::jsonb, 'A', 'Problem management is explicitly the course''s "expert area" for using structured root-cause techniques rather than repeatedly patching symptoms.'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 8, 'A Specialist is asked to help decide whether the Service Desk should run 24x7 or a reduced-hours model, and to justify the choice against several competing requirements. Which two course tools/topics combine to support that decision?', '[{"label": "A", "text": "Work-regime definition (5x8/24x7) informed by the MoSCoW prioritization matrix for requirements"}, {"label": "B", "text": "Only the Five Whys technique, which is unrelated to staffing decisions"}, {"label": "C", "text": "Only Event management dashboards, with no requirements analysis"}, {"label": "D", "text": "The course provides no framework for this kind of staffing decision"}]'::jsonb, 'A', 'The course explicitly pairs defining work regimes (5x8, 24x7, etc.) with using MoSCoW to prioritize Service Desk/software requirements that inform that structural choice.'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 9, 'A monitoring tool fires a threshold breach alert that isn''t yet impacting users. Per the course''s Service Operation processes, which process handles this, and how does it differ from Incident Management?', '[{"label": "A", "text": "Event management — it deals with monitoring/control signals like this, which is distinct from Incident Management''s focus on restoring already-disrupted service"}, {"label": "B", "text": "Incident Management, since all alerts are automatically incidents regardless of user impact"}, {"label": "C", "text": "Request Fulfillment, since any system alert is treated as a user service request"}, {"label": "D", "text": "The course treats events and incidents as fully identical with no distinction"}]'::jsonb, 'A', 'The course separates "Event management - Service monitoring and control" as its own Service Operation process, distinct from Incident Management.'),
  ('IT service operations and Service Desk management - Section 2: Incident Management', 10, 'Why does the course pair "Problem management" with structured root-cause tools rather than leaving it purely reactive?', '[{"label": "A", "text": "Because Problem management is described as \"mostly an expert area\" requiring deliberate analysis techniques to find durable solutions, not quick fixes"}, {"label": "B", "text": "Because Problem management is the simplest, least technical process in the course"}, {"label": "C", "text": "Because root-cause tools are only relevant to Event management, not Problem management"}, {"label": "D", "text": "Because the course treats every problem as unsolvable without escalation to engineering"}]'::jsonb, 'A', 'The description calls Problem management "mostly an expert area" and pairs it with mind maps, Kepner-Tregoe, and Five Whys precisely because it needs structured analysis rather than ad hoc fixes.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 11, 'Which two sections of the course focus specifically on standing up the people/structure needed to respond to a crisis?', '[{"label": "A", "text": "\"Notifying\" and \"Crisis Communication Team\""}, {"label": "B", "text": "\"Introduction\" and \"Conclusion\" only"}, {"label": "C", "text": "There are no sections dedicated to team/structure topics"}, {"label": "D", "text": "\"Statements\" and \"Conclusion\""}]'::jsonb, 'A', 'The course content lists "Notifying" (3 lectures) and "Crisis Communication Team" (3 lectures) as distinct sections building the response structure.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 12, 'What does the course teach about establishing a "chain of command" during a crisis?', '[{"label": "A", "text": "It is one of the core learning objectives, alongside assessing technical and physical resources"}, {"label": "B", "text": "The course explicitly says chain of command is irrelevant during a crisis"}, {"label": "C", "text": "Chain of command is only discussed for post-crisis legal review"}, {"label": "D", "text": "It is not mentioned anywhere in the course"}]'::jsonb, 'A', '"Describe how to establish a chain of command" is listed directly among the course''s stated learning objectives.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 13, 'What does the course teach about avoiding "common crisis response mistakes"?', '[{"label": "A", "text": "It is an explicit learning objective — identifying how to avoid the mistakes organizations typically make in crisis response"}, {"label": "B", "text": "The course claims no common mistakes exist across organizations"}, {"label": "C", "text": "This topic is only covered in an optional, non-graded appendix"}, {"label": "D", "text": "The course only covers mistakes made by external vendors, not the organization itself"}]'::jsonb, 'A', '"Identify how to avoid common crisis response mistakes" is listed as one of the course''s core learning objectives.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 14, 'What resources does the course say a crisis leader should assess?', '[{"label": "A", "text": "Technical and physical resources"}, {"label": "B", "text": "Only the marketing budget"}, {"label": "C", "text": "Only headcount in the legal department"}, {"label": "D", "text": "The course does not mention assessing resources at all"}]'::jsonb, 'A', '"Assess technical and physical resources" is listed directly among the course''s learning objectives.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 15, 'What is the focus of the "Statements" section, which is the longest section in the course?', '[{"label": "A", "text": "Crafting the statements an organization issues during a crisis (3 lectures, 21 minutes — the longest section)"}, {"label": "B", "text": "A single short lecture with no real depth"}, {"label": "C", "text": "Statements only about financial reporting"}, {"label": "D", "text": "Legal disclaimers unrelated to crisis response"}]'::jsonb, 'A', '"Statements" is the longest section at 3 lectures/21 minutes, reflecting its central role in the crisis communication process the course teaches.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 16, 'What is the course''s definition of crisis communication''s place within public relations?', '[{"label": "A", "text": "A sub-specialty of the PR profession designed to protect and defend an individual, company, or organization facing a public challenge to its reputation"}, {"label": "B", "text": "An entirely separate discipline unrelated to public relations"}, {"label": "C", "text": "A purely internal HR function with no external component"}, {"label": "D", "text": "A legal specialty with no communications component"}]'::jsonb, 'A', 'The course description defines crisis communication exactly this way: "a sub-specialty of the public relations profession that is designed to protect and defend...facing a public challenge to its reputation."'),
  ('Crisis Communication: Essential Skills for Crisis Management', 17, 'A Senior Specialist is asked to lead the response to a multi-day outage and needs to make sure the right people can act quickly without waiting on ad hoc approvals. Which course concept most directly addresses this need?', '[{"label": "A", "text": "Establishing a clear chain of command ahead of time, so roles and decision authority are already defined when the crisis hits"}, {"label": "B", "text": "Assessing physical resources only, with no attention to decision authority"}, {"label": "C", "text": "Drafting the final statement first, before anything else"}, {"label": "D", "text": "Avoiding any structure so the team can improvise freely"}]'::jsonb, 'A', 'Chain of command is precisely the mechanism the course teaches for ensuring fast, unambiguous decision-making authority during a crisis.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 18, 'A Senior Specialist is reviewing how the team handled the last major incident and wants to avoid repeating the same missteps next time. Which explicit course objective directly supports this review?', '[{"label": "A", "text": "Identifying how to avoid common crisis response mistakes"}, {"label": "B", "text": "Assessing technical and physical resources, which is unrelated to past mistakes"}, {"label": "C", "text": "The course does not support any retrospective review process"}, {"label": "D", "text": "Drafting a brand-new initial statement, unrelated to reviewing past performance"}]'::jsonb, 'A', 'This learning objective is specifically about recognizing and avoiding the mistakes organizations commonly make, which is exactly what a post-incident review targets.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 19, 'Before drafting any public statement, the course says a crisis leader should assess technical and physical resources. Why would this matter to a Senior Specialist coordinating an incident response?', '[{"label": "A", "text": "Because knowing what resources (systems, staff, physical/technical capacity) are actually available shapes what commitments and timelines can credibly be communicated"}, {"label": "B", "text": "Because resource assessment is purely a finance function with no bearing on communication"}, {"label": "C", "text": "Because the course says resources should never be discussed publicly or internally"}, {"label": "D", "text": "Because resource assessment only matters after the crisis has fully ended"}]'::jsonb, 'A', 'Assessing available resources before communicating is what prevents an organization from making promises (e.g. resolution timelines) it cannot actually keep.'),
  ('Crisis Communication: Essential Skills for Crisis Management', 20, 'Per the course, what should a Senior Specialist understand about the relationship between the "Notifying" and "Crisis Communication Team" sections and the later "Statements" section?', '[{"label": "A", "text": "Notification and team assembly are meant to happen first, establishing who is involved and informed, so that the statements crafted later are coordinated rather than improvised"}, {"label": "B", "text": "Statements should always be issued before any team is assembled or notified"}, {"label": "C", "text": "These sections are entirely independent and their order does not matter"}, {"label": "D", "text": "Only the Statements section matters; Notifying and Team sections are optional filler"}]'::jsonb, 'A', 'The course''s own section order — Notifying, then Crisis Communication Team, then Statements — reflects this build-up: know who to inform and assemble before crafting coordinated public messaging.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 1, 'How is each ITSM process lecture structured in this course?', '[{"label": "A", "text": "Into 5 parts: definition, personas most suitable, use case(s)/real-life scenarios, a process diagram, and hands-on demonstration(s)"}, {"label": "B", "text": "As a single unstructured video with no consistent format"}, {"label": "C", "text": "As a pure reading assignment with no video"}, {"label": "D", "text": "As a single multiple-choice quiz per process with no explanation"}]'::jsonb, 'A', 'The description states each lecture is "divided into 5 parts": Definition, Personas, Use case(s), Process Diagram, and Demonstration(s).'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 2, 'Which ITSM processes does the course cover, per its description?', '[{"label": "A", "text": "Request Fulfillment, Problem Management, Change Management, CMDB, Knowledge Management, and Service Level Management"}, {"label": "B", "text": "Only Incident Management, with no other processes"}, {"label": "C", "text": "Only financial/budgeting processes"}, {"label": "D", "text": "Only HR onboarding workflows"}]'::jsonb, 'A', 'The description explicitly lists these six processes as covered "in addition to" the intro to ITSM and ServiceNow.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 3, 'What is CMDB, as covered in this course?', '[{"label": "A", "text": "Configuration Management Database, one of the core ITSM processes taught"}, {"label": "B", "text": "A customer billing ledger unrelated to ITSM"}, {"label": "C", "text": "A marketing analytics dashboard"}, {"label": "D", "text": "A type of Service Desk ticket priority level"}]'::jsonb, 'A', 'The description lists "CMDB – Configuration Management Database process" as one of the ITSM processes the course covers.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 4, 'What specific Incident Management topic is highlighted among the course''s learning objectives?', '[{"label": "A", "text": "Major Incident Management"}, {"label": "B", "text": "Only minor, low-priority tickets"}, {"label": "C", "text": "The course explicitly excludes Incident Management"}, {"label": "D", "text": "Only cosmetic UI navigation with no process content"}]'::jsonb, 'A', '"Major Incident Management" is explicitly listed as one of the course''s "What you''ll learn" items, alongside general Incident Management.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 5, 'What does each process lecture''s "Use case(s)" component provide?', '[{"label": "A", "text": "Real-life scenarios illustrating how the process is actually applied"}, {"label": "B", "text": "A legal disclaimer with no practical content"}, {"label": "C", "text": "A list of unrelated ServiceNow pricing tiers"}, {"label": "D", "text": "A summary of unrelated HR policies"}]'::jsonb, 'A', 'The description states each lecture''s structure includes "Use case(s) - real life scenarios" as one of its five parts.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 6, 'What kind of practical component accompanies each process lecture, beyond the process diagram?', '[{"label": "A", "text": "Hands-on demonstration(s)"}, {"label": "B", "text": "A written essay assignment with no hands-on element"}, {"label": "C", "text": "No practical component; theory only"}, {"label": "D", "text": "A group debate with no ServiceNow interaction"}]'::jsonb, 'A', 'The description lists "Demonstration(s) - Hands - On" as the fifth part of each lecture''s structure.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 7, 'A Principal Specialist is designing an escalation path for a sev-1 incident in ServiceNow and wants to distinguish "routine incident" handling from something requiring cross-team, executive-visible coordination. Which course topic addresses that distinction directly?', '[{"label": "A", "text": "Major Incident Management, called out specifically alongside general Incident Management"}, {"label": "B", "text": "CMDB, which is unrelated to incident severity"}, {"label": "C", "text": "Knowledge Management, which only covers documentation"}, {"label": "D", "text": "The course treats all incidents identically regardless of severity"}]'::jsonb, 'A', 'The course explicitly separates "Major Incident Management" from ordinary Incident Management as a distinct learning objective, matching this escalation-path distinction.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 8, 'A Principal Specialist wants to justify a proposed ServiceNow Change Management workflow to both a technical admin and a non-technical business stakeholder, using the course''s own lecture format as a model. What should that justification include?', '[{"label": "A", "text": "A clear definition of the process, the personas involved, a concrete use case, a process diagram, and a demonstration — mirroring the course''s 5-part structure"}, {"label": "B", "text": "Only a raw configuration export with no explanation"}, {"label": "C", "text": "Only a legal disclaimer with no process content"}, {"label": "D", "text": "A single sentence summary with no supporting detail"}]'::jsonb, 'A', 'This mirrors the course''s own teaching structure (definition, personas, use case, diagram, demonstration), which is an effective template for explaining a process to mixed audiences.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 9, 'Why does the course pair CMDB with Change Management and Problem Management rather than treating it as a standalone topic?', '[{"label": "A", "text": "Because an accurate configuration record underpins impact analysis for changes and root-cause investigation for problems, so these processes rely on each other in practice"}, {"label": "B", "text": "Because CMDB has no functional relationship to any other ITSM process"}, {"label": "C", "text": "Because Change Management and Problem Management are actually the same process"}, {"label": "D", "text": "Because CMDB is only used for Service Level Management reporting"}]'::jsonb, 'A', 'ITSM practice (and the course''s inclusion of CMDB alongside Change and Problem Management) reflects that configuration data is what change-impact analysis and problem root-cause work both depend on.'),
  ('ServiceNow ITSM Processes > Section 3 > 7. Incident and Major Incident Management', 10, 'Per its own framing, why might this ~2-hour course still be useful preparation for a Principal Specialist, despite reviewers noting it has not been updated since 2021?', '[{"label": "A", "text": "Because it teaches ITSM process fundamentals (definitions, personas, use cases) that remain conceptually valid even if some ServiceNow UI screens shown are now outdated"}, {"label": "B", "text": "Because ITSM processes have changed completely since 2021 and the course is now entirely obsolete"}, {"label": "C", "text": "Because the course only ever covered UI navigation with no process concepts"}, {"label": "D", "text": "Because ServiceNow no longer supports any of the processes covered"}]'::jsonb, 'A', 'The course''s value is in the underlying ITSM process concepts (Incident, Problem, Change, CMDB, Knowledge, SLM), which remain valid independent of any dated UI screenshots.'),
  ('TED — Margaret Heffernan: Dare to disagree', 1, 'What is Heffernan''s core argument about disagreement in this talk?', '[{"label": "A", "text": "Constructive conflict drives progress — teams that embrace disagreement think better together than those chasing consensus"}, {"label": "B", "text": "All conflict at work is destructive and should be eliminated"}, {"label": "C", "text": "Disagreement is only useful in academic research, not business"}, {"label": "D", "text": "Consensus-seeking always produces the best outcomes"}]'::jsonb, 'A', 'This is the talk''s central thesis.'),
  ('TED — Margaret Heffernan: Dare to disagree', 2, 'What did Dr. Alice Stewart discover, and how long did it take before her finding changed practice?', '[{"label": "A", "text": "That prenatal X-rays caused childhood cancers — it took 25 years for the practice to stop, despite clear statistical evidence"}, {"label": "B", "text": "That prenatal X-rays were completely safe — adopted within a year"}, {"label": "C", "text": "A vaccine breakthrough adopted almost immediately"}, {"label": "D", "text": "A statistical error in her own prior research, corrected within weeks"}]'::jsonb, 'A', 'This is the talk''s central historical example of how hard it is for disagreement/new evidence to overturn consensus.'),
  ('TED — Margaret Heffernan: Dare to disagree', 3, 'What was statistician George Kneale''s stated role in his collaboration with Dr. Stewart?', '[{"label": "A", "text": "\"My job is to prove Dr. Stewart wrong\" — actively seeking disconfirmation"}, {"label": "B", "text": "To simply validate her conclusions without challenge"}, {"label": "C", "text": "To manage her research budget and staffing"}, {"label": "D", "text": "To publish her results without independent analysis"}]'::jsonb, 'A', 'Kneale is quoted with this exact framing of his role as her "thinking partner.".'),
  ('TED — Margaret Heffernan: Dare to disagree', 4, 'What survey statistic does Heffernan cite about executives and workplace conflict?', '[{"label": "A", "text": "85% of executives avoid raising concerns at work due to conflict anxiety"}, {"label": "B", "text": "85% of executives actively seek out disagreement daily"}, {"label": "C", "text": "Only 15% of executives ever avoid conflict"}, {"label": "D", "text": "No such survey is cited in the talk"}]'::jsonb, 'A', 'This is the exact statistic Heffernan cites to illustrate the scale of conflict avoidance in organizations.'),
  ('TED — Margaret Heffernan: Dare to disagree', 5, 'What happened when "Joe," a medical device executive, finally voiced his safety concerns instead of quitting?', '[{"label": "A", "text": "Colleagues revealed they shared the same concerns, enabling collaborative problem-solving, and he became a recognized leader rather than a \"whistleblower\""}, {"label": "B", "text": "He was fired immediately for raising the issue"}, {"label": "C", "text": "No one else agreed with him and the issue was dropped"}, {"label": "D", "text": "The company ignored the concern entirely with no consequence"}]'::jsonb, 'A', 'This is the outcome Heffernan describes for the Joe example.'),
  ('TED — Margaret Heffernan: Dare to disagree', 6, 'A support team has a recurring bug that two engineers privately suspect is caused by a risky architectural shortcut, but neither raises it in team meetings. Which of the talk''s core lessons applies most directly?', '[{"label": "A", "text": "Like the 85% of conflict-avoidant executives, staying silent to avoid friction likely means the organization loses the benefit of their genuine, if uncomfortable, insight"}, {"label": "B", "text": "Silence is always the safer and more professional choice in a team setting"}, {"label": "C", "text": "Only senior engineers are qualified to raise architectural concerns"}, {"label": "D", "text": "This has no connection to the talk''s argument about disagreement"}]'::jsonb, 'A', 'This mirrors the talk''s central point: silence driven by conflict-avoidance costs the organization real learning and problem-solving.'),
  ('TED — Margaret Heffernan: Dare to disagree', 7, 'Why does Heffernan frame the Stewart-Kneale partnership as a model of "thinking partners" rather than just co-workers?', '[{"label": "A", "text": "Because they had complementary personalities and approaches and used genuine intellectual sparring/disconfirmation rather than polite agreement to reach sound conclusions"}, {"label": "B", "text": "Because they never actually worked on the same project"}, {"label": "C", "text": "Because Kneale simply agreed with everything Stewart proposed"}, {"label": "D", "text": "Because their partnership was purely social, with no bearing on the research itself"}]'::jsonb, 'A', 'The talk frames this pairing specifically as an example of productive conflict — actively trying to disprove each other''s ideas rather than validate them.'),
  ('TED — Margaret Heffernan: Dare to disagree', 8, 'A new hire on a support team disagrees with a senior teammate''s diagnosis of a customer issue but stays quiet to avoid seeming inexperienced. What does the talk suggest this pattern costs the team?', '[{"label": "A", "text": "The team loses access to a potentially valid alternative diagnosis — exactly the kind of withheld insight the talk argues organizations can''t afford to lose"}, {"label": "B", "text": "Nothing — junior team members rarely have useful insight worth surfacing"}, {"label": "C", "text": "It protects team harmony, which the talk argues should always come first"}, {"label": "D", "text": "It has no bearing on outcomes, since senior staff are usually right"}]'::jsonb, 'A', 'This directly extends the talk''s argument that silence — driven by fear of looking wrong — deprives the group of real thinking.'),
  ('TED — Margaret Heffernan: Dare to disagree', 9, 'What does the talk say is required to develop genuine "conflict skills," beyond simply being open-minded?', '[{"label": "A", "text": "Courage to engage in difficult conversations — openness alone, without courage, fails"}, {"label": "B", "text": "A formal doctoral degree in conflict resolution"}, {"label": "C", "text": "Nothing further is required beyond stating a willingness to listen"}, {"label": "D", "text": "Avoiding conflict entirely until a neutral third party is present"}]'::jsonb, 'A', 'The talk''s call to action is explicit that openness without courage isn''t enough — people need to actually engage, not just tolerate disagreement in theory.'),
  ('TED — Margaret Heffernan: Dare to disagree', 10, 'A manager wants to build a culture where disagreement is treated as a feature, not a threat. Based on the Stewart/Kneale example, what practice should they encourage?', '[{"label": "A", "text": "Actively inviting someone to try to disprove a proposed conclusion, as a normal and expected part of the process"}, {"label": "B", "text": "Requiring unanimous agreement before any decision is finalized"}, {"label": "C", "text": "Assigning one person to always play devil''s advocate in every single meeting regardless of topic"}, {"label": "D", "text": "Discouraging any follow-up questions once a senior person has spoken"}]'::jsonb, 'A', 'This mirrors Kneale''s explicit role — normalizing active, structured disconfirmation as a way to strengthen conclusions, not undermine them.'),
  ('Fostering Psychological Safety & Belonging on Teams', 1, 'How many steps does the course teach for building psychological safety on a team?', '[{"label": "A", "text": "Six steps"}, {"label": "B", "text": "Two steps"}, {"label": "C", "text": "Twelve steps"}, {"label": "D", "text": "The course does not specify a number of steps"}]'::jsonb, 'A', 'The course''s own learning objectives state "Six steps to build Psychological Safety on your team to foster inclusion."'),
  ('Fostering Psychological Safety & Belonging on Teams', 2, 'Who is this course specifically designed for, per its framing?', '[{"label": "A", "text": "Managers, to take actionable steps to create psychological safety and foster inclusion and belonging on their team"}, {"label": "B", "text": "New hires with no management responsibility"}, {"label": "C", "text": "External auditors reviewing a company''s culture"}, {"label": "D", "text": "Customers evaluating a vendor''s support quality"}]'::jsonb, 'A', 'The description states "This course is designed for managers to take actionable steps to create Psychological Safety and foster inclusion and belonging on their team."'),
  ('Fostering Psychological Safety & Belonging on Teams', 3, 'What does the course say belonging requires, beyond a generic company-wide policy?', '[{"label": "A", "text": "Practical steps tailored to create the conditions for everyone to belong, since belonging is personal and means something different to everyone"}, {"label": "B", "text": "A single one-size-fits-all script that works identically for every employee"}, {"label": "C", "text": "Nothing; belonging is described as entirely outside a manager''s influence"}, {"label": "D", "text": "An HR policy document with no manager involvement"}]'::jsonb, 'A', 'The description states "Belonging is personal. It means something different to everyone, but there are practical steps you can take to create the conditions for everyone to belong."'),
  ('Fostering Psychological Safety & Belonging on Teams', 4, 'What does the course say about the relationship between inclusion/belonging and business outcomes?', '[{"label": "A", "text": "Employees who feel included and can be authentic at work are more engaged and creative, and their organization thrives"}, {"label": "B", "text": "Inclusion and belonging have no measurable connection to engagement or performance"}, {"label": "C", "text": "Only financial incentives drive engagement, not inclusion"}, {"label": "D", "text": "The course explicitly avoids linking culture work to business outcomes"}]'::jsonb, 'A', 'The description states that when employees "feel included...and are able to be their authentic selves at work, they are more engaged and creative, and their organization thrives."'),
  ('Fostering Psychological Safety & Belonging on Teams', 5, 'What prerequisite understanding does the course assume students already have?', '[{"label": "A", "text": "A baseline understanding of what diversity and equity are, and of Unconscious Bias (though Unconscious Bias itself is not covered in this course)"}, {"label": "B", "text": "Formal certification in organizational psychology"}, {"label": "C", "text": "No prior knowledge of any kind is assumed"}, {"label": "D", "text": "Prior completion of a coding bootcamp"}]'::jsonb, 'A', 'The course''s requirements state students should have a baseline understanding of diversity, equity, and Unconscious Bias, explicitly noting Unconscious Bias itself "will not be covered in this course."'),
  ('Fostering Psychological Safety & Belonging on Teams', 6, 'What framework does the course offer for discussing inclusion and belonging with a team?', '[{"label": "A", "text": "A framework for having brave conversations about inclusion and belonging"}, {"label": "B", "text": "A rigid legal script with no room for conversation"}, {"label": "C", "text": "The course explicitly avoids any framework for these conversations"}, {"label": "D", "text": "A framework only for use in exit interviews"}]'::jsonb, 'A', 'The description lists "Establish a framework for having brave conversations about inclusion and belonging with your team" as a course learning objective.'),
  ('Fostering Psychological Safety & Belonging on Teams', 7, 'A Specialist newly promoted to lead a small team notices one team member rarely speaks up in meetings, even when they likely have relevant input. Per this course, what would be the most direct first step to address this?', '[{"label": "A", "text": "Apply the six-step approach to building psychological safety so that team member feels safe taking the interpersonal risk of speaking up"}, {"label": "B", "text": "Address it only in that person''s annual performance review"}, {"label": "C", "text": "Assume the employee simply has nothing to contribute and move on"}, {"label": "D", "text": "Escalate immediately to HR without first trying any team-level intervention"}]'::jsonb, 'A', 'The course''s core framework is exactly this: building psychological safety so team members feel safe taking risks like speaking up, rather than defaulting to formal escalation.'),
  ('Fostering Psychological Safety & Belonging on Teams', 8, 'A Specialist wants to create a sense of belonging for a newly distributed, culturally diverse team, but worries a single generic "team culture" email won''t work for everyone. What does the course say about this instinct?', '[{"label": "A", "text": "It confirms this instinct — belonging is personal and requires practical, individualized conditions rather than one uniform approach"}, {"label": "B", "text": "It says belonging is identical for everyone, so a single email is always sufficient"}, {"label": "C", "text": "It says belonging only applies to co-located, in-person teams"}, {"label": "D", "text": "It says belonging is solely HR''s responsibility, not a team leader''s"}]'::jsonb, 'A', 'The course explicitly frames belonging as personal and different for everyone, meaning a single generic message is unlikely to create it for the whole team.'),
  ('Fostering Psychological Safety & Belonging on Teams', 9, 'Per the course, why is fostering inclusion and belonging described as "ongoing work" rather than a one-time initiative?', '[{"label": "A", "text": "Because it is critical to organizational success on a continuing basis, not a task to complete once and move past"}, {"label": "B", "text": "Because the course says it is only relevant during onboarding week"}, {"label": "C", "text": "Because inclusion work has no measurable connection to retention or engagement"}, {"label": "D", "text": "Because the course recommends revisiting it only once every several years"}]'::jsonb, 'A', 'The course lists "Understand why fostering belonging at your company is ongoing work critical to your success" as a specific learning objective, framing it as continuous rather than one-off.'),
  ('Fostering Psychological Safety & Belonging on Teams', 10, 'What is the final, action-oriented step the course pushes learners toward after covering the conceptual material?', '[{"label": "A", "text": "A closing \"Take action!\" section, translating the six-step psychological safety framework and belonging conditions into concrete next steps"}, {"label": "B", "text": "A purely theoretical wrap-up with no call to action"}, {"label": "C", "text": "A section focused only on legal compliance paperwork"}, {"label": "D", "text": "A sales pitch for a follow-on paid certification"}]'::jsonb, 'A', 'The course content lists "Take action!" as its final section, reinforcing that the material is meant to be applied, not just understood conceptually.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 1, 'How does Edmondson define psychological safety?', '[{"label": "A", "text": "A belief that it''s absolutely okay, in fact expected, to speak up with concerns, questions, ideas, and mistakes"}, {"label": "B", "text": "A guarantee that no one will ever be held accountable for errors"}, {"label": "C", "text": "An environment where all disagreement is discouraged to preserve harmony"}, {"label": "D", "text": "A workplace with no performance expectations"}]'::jsonb, 'A', 'This is Edmondson''s own definition, given verbatim in the talk.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 2, 'What surprising result did Edmondson find when studying medication errors across hospital units?', '[{"label": "A", "text": "Better-performing teams reported MORE errors — not because they made more mistakes, but because they were more willing to discuss them openly"}, {"label": "B", "text": "Better-performing teams reported dramatically fewer errors, full stop"}, {"label": "C", "text": "Error rates were identical across every team regardless of performance"}, {"label": "D", "text": "Reporting rates had no relationship to team performance at all"}]'::jsonb, 'A', 'This counterintuitive finding is central to Edmondson''s research and argument.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 3, 'What does Edmondson call the unconscious, self-protective habit of avoiding questions to protect one''s image?', '[{"label": "A", "text": "Impression management"}, {"label": "B", "text": "Cognitive dissonance"}, {"label": "C", "text": "Groupthink"}, {"label": "D", "text": "The bystander effect"}]'::jsonb, 'A', 'The talk names this exact term for the behavior, noting it starts in childhood and becomes automatic by adulthood.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 4, 'What are the three strategies Edmondson recommends for leaders to build psychological safety?', '[{"label": "A", "text": "Frame work as a learning problem, acknowledge your own fallibility, and model curiosity by asking frequent questions"}, {"label": "B", "text": "Enforce strict hierarchy, minimize questions, and reward silence"}, {"label": "C", "text": "Reward only flawless performance and eliminate all uncertainty from messaging"}, {"label": "D", "text": "Delegate all decision-making to avoid appearing fallible"}]'::jsonb, 'A', 'These are the three leader strategies Edmondson names explicitly.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 5, 'What are the four zones in Edmondson''s performance framework (based on psychological safety vs. accountability)?', '[{"label": "A", "text": "Apathy zone (low/low), anxiety zone (high accountability/low safety), learning zone (high/high), and a fourth comfort zone (low accountability/high safety)"}, {"label": "B", "text": "Only two zones exist: safe and unsafe"}, {"label": "C", "text": "Beginner, intermediate, advanced, and expert zones"}, {"label": "D", "text": "Red, yellow, green, and blue zones"}]'::jsonb, 'A', 'Edmondson''s framework maps four zones along the two axes of accountability and psychological safety, with the learning zone (high on both) being where sustained high performance happens.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 6, 'A support team has high performance pressure but team members are afraid to admit when they don''t know how to solve a ticket. Which zone does this describe, and what is the risk?', '[{"label": "A", "text": "The anxiety zone (high accountability, low safety) — people may hide gaps or mistakes rather than get help, limiting learning and performance"}, {"label": "B", "text": "The learning zone — this is actually the ideal state"}, {"label": "C", "text": "The apathy zone — low accountability means no real risk exists"}, {"label": "D", "text": "This scenario is not covered by the framework"}]'::jsonb, 'A', 'High pressure combined with fear of admitting not knowing something matches the anxiety zone exactly — accountability without safety.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 7, 'A team lead wants to move their team from the anxiety zone into the learning zone. Based on the three leader strategies, what should they do first?', '[{"label": "A", "text": "Start acknowledging their own mistakes/fallibility openly and framing work as uncertain and interdependent, inviting more open discussion"}, {"label": "B", "text": "Increase accountability pressure further while keeping expectations unstated"}, {"label": "C", "text": "Stop asking any questions so as not to seem unsure of the plan"}, {"label": "D", "text": "Remove all deadlines and stop tracking outcomes entirely"}]'::jsonb, 'A', 'This directly reflects two of Edmondson''s three named strategies for leaders building psychological safety.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 8, 'Why does Edmondson''s hospital research findings matter for interpreting raw error-reporting metrics in any team, including a support org?', '[{"label": "A", "text": "A low reported-error count doesn''t necessarily mean fewer actual errors — it might mean people are afraid to report them, the opposite of what leaders might assume"}, {"label": "B", "text": "Error counts always map perfectly to actual mistake rates, with no confounding factors"}, {"label": "C", "text": "High reported-error counts always indicate a poorly performing team"}, {"label": "D", "text": "Error reporting has no relationship to team culture at all"}]'::jsonb, 'A', 'This is the direct, generalizable lesson from Edmondson''s hospital study — reported error rates can be a signal of psychological safety, not just raw performance.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 9, 'What does Edmondson''s opening set of examples (nurse, pilot, executive) illustrate about the cost of silence?', '[{"label": "A", "text": "In each case, someone stayed quiet due to fear of looking bad, and the organization lost a chance to prevent a problem"}, {"label": "B", "text": "In each case, speaking up made the situation worse"}, {"label": "C", "text": "These examples show silence is usually the correct choice under uncertainty"}, {"label": "D", "text": "These examples are unrelated to psychological safety"}]'::jsonb, 'A', 'These vignettes open the talk specifically to illustrate the real-world cost of impression-management-driven silence.'),
  ('TED — Amy Edmondson: Building a psychologically safe workplace', 10, 'Why does Edmondson emphasize "complex, interdependent" environments specifically when describing where the learning zone matters most?', '[{"label": "A", "text": "Because in such environments, no single person has all the answers, so open, safe information-sharing is what allows the team as a whole to catch problems and improve"}, {"label": "B", "text": "Because complex environments require less communication, not more"}, {"label": "C", "text": "Because interdependence is irrelevant to psychological safety"}, {"label": "D", "text": "Because simple, independent tasks benefit more from psychological safety than complex ones do"}]'::jsonb, 'A', 'Edmondson frames the learning zone as essential specifically where work is uncertain and interdependent — conditions where no one person can succeed alone, making open communication critical.'),
  ('Leadership: Transforming Culture and Company Performance', 1, 'How many core leadership principles does this course present?', '[{"label": "A", "text": "Nine"}, {"label": "B", "text": "Three"}, {"label": "C", "text": "Twelve"}, {"label": "D", "text": "The course does not specify a number"}]'::jsonb, 'A', 'The course title itself describes "The Nine Principles of Transformational Leadership," and the syllabus is built around exactly nine principles.'),
  ('Leadership: Transforming Culture and Company Performance', 2, 'What does the course say is the basis of both career success and corporate success in the marketplace?', '[{"label": "A", "text": "Brand equity built through consistent adherence to worthy principles, i.e. trustworthiness"}, {"label": "B", "text": "Aggressive short-term cost-cutting alone"}, {"label": "C", "text": "Avoiding any public commitment to values"}, {"label": "D", "text": "Frequent leadership turnover"}]'::jsonb, 'A', 'The description states "brand equity is the basis of both career success and corporate success in the marketplace," built through consistent adherence to principles.'),
  ('Leadership: Transforming Culture and Company Performance', 3, 'What is the course''s stated purpose in presenting its nine principles?', '[{"label": "A", "text": "Not to prescribe principles, but to offer them for consideration and discussion as a basis for transformational leadership"}, {"label": "B", "text": "To mandate that every leader adopt these exact nine principles without discussion"}, {"label": "C", "text": "To replace the need for any individual reflection on personal values"}, {"label": "D", "text": "To provide a legal compliance checklist"}]'::jsonb, 'A', 'The description explicitly states "the purpose of this course is not to prescribe principles, but to offer for consideration and discussion" this set of nine principles.'),
  ('Leadership: Transforming Culture and Company Performance', 4, 'What does the course say generates dedication and loyalty from a team toward its leader?', '[{"label": "A", "text": "The leader''s adherence to principles"}, {"label": "B", "text": "Strict enforcement of arbitrary rules with no explanation"}, {"label": "C", "text": "High salaries alone, regardless of leadership behavior"}, {"label": "D", "text": "Frequent reorganizations"}]'::jsonb, 'A', 'The description states "Leaders generate dedication and loyalty based on their adherence to principles."'),
  ('Leadership: Transforming Culture and Company Performance', 5, 'Which section of the course, by lecture count, covers the actual nine transformational leadership principles in depth?', '[{"label": "A", "text": "\"The Transformational Leadership Principles\" (21 lectures, 2hr 47min — by far the largest section)"}, {"label": "B", "text": "\"Introduction\" (1 lecture, 4min)"}, {"label": "C", "text": "\"Brand Value & Brand Equity\" (3 lectures, 29min)"}, {"label": "D", "text": "None of the sections cover the principles directly"}]'::jsonb, 'A', 'The course content shows "The Transformational Leadership Principles" as by far the largest section, at 21 of the course''s 27 total lectures.'),
  ('Leadership: Transforming Culture and Company Performance', 6, 'What real-world experience does the instructor draw on in building this course?', '[{"label": "A", "text": "More than forty years coaching leaders and leading cultural transformation in Fortune 100 companies like Corning, Shell Oil, 3M, and Xerox"}, {"label": "B", "text": "No professional experience; the course is purely theoretical"}, {"label": "C", "text": "A single 2-year consulting engagement"}, {"label": "D", "text": "Experience limited to academic research with no corporate clients"}]'::jsonb, 'A', 'The instructor bio states "more than forty years coaching leaders and leading cultural transformation in dozens of Fortune 100 companies like Corning, Shell Oil Company, 3M, Xerox and others."'),
  ('Leadership: Transforming Culture and Company Performance', 7, 'A Senior Specialist has been asked to help define what "good culture" looks like for their support org, but leadership disagrees on specifics. Per this course''s framing, what is the recommended approach?', '[{"label": "A", "text": "Offer the nine principles for consideration and discussion, letting the team examine and commit to a set of principles rather than having them dictated top-down"}, {"label": "B", "text": "Impose the instructor''s exact nine principles verbatim with no adaptation or discussion"}, {"label": "C", "text": "Avoid discussing principles at all and focus solely on process metrics"}, {"label": "D", "text": "Delay any culture discussion until company-wide alignment happens organically"}]'::jsonb, 'A', 'This mirrors the course''s own stated approach: presenting principles "for consideration and discussion," not as a rigid mandate.'),
  ('Leadership: Transforming Culture and Company Performance', 8, 'A Senior Specialist wants their team to trust escalation decisions even when those decisions are unpopular in the moment. Per the course, what ultimately builds that kind of trust?', '[{"label": "A", "text": "Consistent adherence to principles over time, which builds the leader''s brand equity and trustworthiness"}, {"label": "B", "text": "Making decisions that are always popular, regardless of principle"}, {"label": "C", "text": "Avoiding transparency about the reasoning behind decisions"}, {"label": "D", "text": "Rotating decision-makers frequently so no one is accountable"}]'::jsonb, 'A', 'The course frames trust and loyalty as generated by consistent principled behavior, i.e. brand equity built over time, not by popularity of individual decisions.'),
  ('Leadership: Transforming Culture and Company Performance', 9, 'Why does the course link personal leadership principles directly to organizational "brand value" and "brand equity," rather than treating them as a purely private, personal matter?', '[{"label": "A", "text": "Because a leader''s trustworthy, principle-based reputation is treated as a career and corporate asset that affects marketplace success, not just personal ethics"}, {"label": "B", "text": "Because brand value is described as entirely disconnected from leadership behavior"}, {"label": "C", "text": "Because the course argues personal principles should never be discussed at work"}, {"label": "D", "text": "Because brand equity in this course refers only to product packaging design"}]'::jsonb, 'A', 'The course explicitly frames personal brand equity/trustworthiness as "an asset" underpinning both career and corporate success, not a private-only matter.'),
  ('Leadership: Transforming Culture and Company Performance', 10, 'Who does the course identify as its intended audience?', '[{"label": "A", "text": "Managers, entrepreneurs, and those aspiring to become effective leaders of people, teams, and organizations"}, {"label": "B", "text": "Only recent college graduates with no work experience"}, {"label": "C", "text": "Only C-suite executives at Fortune 100 companies"}, {"label": "D", "text": "Only external consultants, not internal leaders"}]'::jsonb, 'A', 'The "Who this course is for" section states it targets "Managers, Entrepreneurs and those aspiring to become effective leaders of people, teams and organizations."'),
  ('TED — Simon Sinek: How great leaders inspire action', 1, 'What are the three layers of Sinek''s "Golden Circle," from outer to inner?', '[{"label": "A", "text": "What, How, Why"}, {"label": "B", "text": "Why, How, What"}, {"label": "C", "text": "How, What, Why"}, {"label": "D", "text": "Why, What, How"}]'::jsonb, 'A', 'The Golden Circle is structured with What on the outside, How in the middle, and Why at the core — though inspired communicators start from the center (Why) and work outward.'),
  ('TED — Simon Sinek: How great leaders inspire action', 2, 'What is Sinek''s core claim about why people buy from inspired organizations?', '[{"label": "A", "text": "People don''t buy what you do, they buy why you do it"}, {"label": "B", "text": "People only ever buy based on price and features"}, {"label": "C", "text": "People buy from whichever company communicates ''What'' most clearly"}, {"label": "D", "text": "Purpose has no measurable effect on purchasing decisions"}]'::jsonb, 'A', 'This is Sinek''s central, direct quote and thesis.'),
  ('TED — Simon Sinek: How great leaders inspire action', 3, 'How does Sinek characterize Apple''s typical communication approach, as an example of Why-first messaging?', '[{"label": "A", "text": "Leading with belief — \"everything we do, we believe in challenging the status quo\" — rather than leading with product specs"}, {"label": "B", "text": "Leading with a detailed technical spec sheet before mentioning any belief"}, {"label": "C", "text": "Leading exclusively with price comparisons to competitors"}, {"label": "D", "text": "Refusing to communicate any belief or mission at all"}]'::jsonb, 'A', 'Sinek uses this exact "we believe in challenging the status quo" framing as the Apple example of Why-first communication.'),
  ('TED — Simon Sinek: How great leaders inspire action', 4, 'According to Sinek, why did people join Martin Luther King''s movement?', '[{"label": "A", "text": "Because they believed in his vision, not because they were told to or given a detailed plan"}, {"label": "B", "text": "Because King distributed a comprehensive step-by-step logistical plan"}, {"label": "C", "text": "Because it was legally mandated for them to participate"}, {"label": "D", "text": "Because King offered financial incentives to participants"}]'::jsonb, 'A', 'Sinek explicitly contrasts King''s conviction-based appeal ("I believe...") with a plan-based pitch, arguing belief is what drove participation.'),
  ('TED — Simon Sinek: How great leaders inspire action', 5, 'In the Law of Diffusion of Innovation that Sinek references, what percentage of the market are "innovators," and what market-penetration range represents the "chasm" that must be crossed for mass adoption?', '[{"label": "A", "text": "Innovators are about 2.5%; the chasm sits around 15-18% market penetration"}, {"label": "B", "text": "Innovators are about 50%; the chasm is at 90%"}, {"label": "C", "text": "Innovators are 100% of any market by definition"}, {"label": "D", "text": "There is no chasm concept in this framework"}]'::jsonb, 'A', 'Sinek cites these specific figures from the diffusion-of-innovation model.'),
  ('TED — Simon Sinek: How great leaders inspire action', 6, 'A product team wants to pitch a new internal tool to skeptical engineers by leading with a long list of technical features. Based on Sinek''s framework, what would he likely suggest instead?', '[{"label": "A", "text": "Lead with the \"Why\" — the belief or purpose behind building the tool — before getting into the \"What\" (the feature list)"}, {"label": "B", "text": "Skip explaining \"Why\" entirely, since it never affects adoption"}, {"label": "C", "text": "Only ever communicate \"What,\" since \"How\" and \"Why\" are irrelevant to engineers"}, {"label": "D", "text": "Present features and beliefs in a random order for variety"}]'::jsonb, 'A', 'This directly applies Sinek''s inside-out Golden Circle model — start with purpose/belief, then how, then what.'),
  ('TED — Simon Sinek: How great leaders inspire action', 7, 'A leader wants their team to feel like they''ve chosen to embrace a new initiative rather than being told to comply. Which of Sinek''s examples most directly models this distinction?', '[{"label": "A", "text": "The Martin Luther King example — people chose to join because they believed, not because they were commanded"}, {"label": "B", "text": "The Apple example, since Apple''s customers are legally required to buy their products"}, {"label": "C", "text": "Neither example in the talk relates to voluntary buy-in"}, {"label": "D", "text": "The diffusion-of-innovation chasm, which is unrelated to voluntary participation"}]'::jsonb, 'A', 'Sinek uses King''s movement specifically to illustrate belief-driven, voluntary participation as opposed to compliance.'),
  ('TED — Simon Sinek: How great leaders inspire action', 8, 'Why does Sinek argue that early adopters matter disproportionately in the diffusion-of-innovation model?', '[{"label": "A", "text": "Because they are motivated by shared values/belief rather than needing full rational proof, and their adoption helps pull in the early majority across the chasm"}, {"label": "B", "text": "Because they represent the largest segment of any market"}, {"label": "C", "text": "Because they always have the most money to spend"}, {"label": "D", "text": "Because late majority and laggards adopt first in this model"}]'::jsonb, 'A', 'Sinek frames early believers as value-driven adopters whose early buy-in is what allows an idea to cross the chasm into mass-market adoption.'),
  ('TED — Simon Sinek: How great leaders inspire action', 9, 'A Skedulo internal champion wants customer success teams to adopt a new support workflow enthusiastically rather than grudgingly. Per Sinek''s framework, what''s the risk of only communicating the ''What'' (the new steps to follow)?', '[{"label": "A", "text": "Without a ''Why,'' people may comply without genuine belief or enthusiasm, weakening voluntary long-term adoption"}, {"label": "B", "text": "There is no risk — the ''What'' is all that ever matters for adoption"}, {"label": "C", "text": "Communicating ''What'' guarantees the same result as communicating ''Why''"}, {"label": "D", "text": "''What''-only messaging always outperforms ''Why''-first messaging"}]'::jsonb, 'A', 'This applies Sinek''s central argument: ''What''-only messaging drives compliance at best, while ''Why''-first messaging drives genuine belief-based buy-in.'),
  ('TED — Simon Sinek: How great leaders inspire action', 10, 'What is the fundamental difference Sinek draws between "manipulation" (e.g., price, fear, peer pressure) and "inspiration" as means of driving action?', '[{"label": "A", "text": "Manipulation can drive short-term behavior without loyalty or belief, while inspiration (Why-first) builds lasting, voluntary commitment"}, {"label": "B", "text": "There is no meaningful difference between the two in his framework"}, {"label": "C", "text": "Manipulation always produces more loyal customers than inspiration does"}, {"label": "D", "text": "Inspiration is only relevant to non-profit or political movements, never business"}]'::jsonb, 'A', 'This reflects Sinek''s broader argument that Why-first, belief-driven approaches create durable loyalty that manipulation-based tactics cannot.'),
  ('Organizational Change Management & Culture Transformation', 1, 'How many stages does the change model taught in this course have?', '[{"label": "A", "text": "Six stages"}, {"label": "B", "text": "Two stages"}, {"label": "C", "text": "Ten stages"}, {"label": "D", "text": "The course does not use a staged model"}]'::jsonb, 'A', 'The description repeatedly refers to "the six-stage change model" used with companies like Merck, Shell, Honeywell, and Honda.'),
  ('Organizational Change Management & Culture Transformation', 2, 'What are the two most important words in change management, per the course''s own framing?', '[{"label": "A", "text": "Engagement and resistance"}, {"label": "B", "text": "Budget and headcount"}, {"label": "C", "text": "Speed and secrecy"}, {"label": "D", "text": "Compliance and audit"}]'::jsonb, 'A', 'The description states "Two of the most important words in change management are engagement and resistance."'),
  ('Organizational Change Management & Culture Transformation', 3, 'What does the course say management often does that inadvertently creates resistance to change?', '[{"label": "A", "text": "Fails to engage employees and other stakeholders in the analysis and decision process leading to the change"}, {"label": "B", "text": "Over-engages employees to the point of decision paralysis"}, {"label": "C", "text": "Provides too much advance notice of upcoming changes"}, {"label": "D", "text": "Change management consultants create resistance on purpose, per the course"}]'::jsonb, 'A', 'The description states "management often creates that resistance by failing to engage employees and other stakeholders in the analysis and decision process that leads to the change."'),
  ('Organizational Change Management & Culture Transformation', 4, 'What method of change design does this course use as its core methodology?', '[{"label": "A", "text": "Whole-system design that engages stakeholders in the creation and implementation of change"}, {"label": "B", "text": "A closed-door executive-only planning process"}, {"label": "C", "text": "A purely software-automated change ticketing workflow"}, {"label": "D", "text": "A method that explicitly excludes customer and supplier input"}]'::jsonb, 'A', 'The description states the course''s method "is whole-system design that engages stakeholders in the creation and implementation of change."'),
  ('Organizational Change Management & Culture Transformation', 5, 'How many assignments does the course contain to walk students through the change design process?', '[{"label": "A", "text": "Fifteen assignments"}, {"label": "B", "text": "Zero; the course is lecture-only"}, {"label": "C", "text": "One single final assignment"}, {"label": "D", "text": "Three assignments"}]'::jsonb, 'A', 'The description states "the course contains fifteen assignments that lead the student through the design process."'),
  ('Organizational Change Management & Culture Transformation', 6, 'What two outcomes does the course say happen when stakeholders are engaged in creating a change, rather than having it imposed on them?', '[{"label": "A", "text": "The quality of decisions improves, and there is little resistance to implementation"}, {"label": "B", "text": "Decisions take longer with no improvement in quality or resistance"}, {"label": "C", "text": "Stakeholders become less committed to any outcome"}, {"label": "D", "text": "The course says engagement has no measurable effect on outcomes"}]'::jsonb, 'A', 'The description states "When stakeholders are engaged in creating the change two things happen: first the quality of decisions improve and second, there is little resistance to the implementation of that change."'),
  ('Organizational Change Management & Culture Transformation', 7, 'A Principal Specialist is planning a major process overhaul across support, engineering, and customer success, and expects heavy pushback once it''s announced. Per this course''s core premise, what is the most likely root cause of that anticipated resistance?', '[{"label": "A", "text": "The stakeholders in those groups were not engaged in analyzing the problem and shaping the change before it was decided"}, {"label": "B", "text": "Resistance is unavoidable regardless of how the change was designed"}, {"label": "C", "text": "The change is being announced too far in advance"}, {"label": "D", "text": "The course says resistance only ever comes from customers, never internal stakeholders"}]'::jsonb, 'A', 'This is the course''s central premise: resistance is typically produced by a lack of stakeholder engagement in the decision process, not an unavoidable fact of change itself.'),
  ('Organizational Change Management & Culture Transformation', 8, 'A Principal Specialist wants to redesign an escalation workflow and needs buy-in from external customers, internal support staff, and engineering leadership simultaneously. Which course concept best matches this multi-stakeholder need?', '[{"label": "A", "text": "Whole-system design, which explicitly engages customers, suppliers, and employees together in creating the change"}, {"label": "B", "text": "A model that only ever considers internal employees and excludes customers or suppliers entirely"}, {"label": "C", "text": "A model that requires each stakeholder group to redesign the workflow independently with no coordination"}, {"label": "D", "text": "The course provides no method for multi-stakeholder change design"}]'::jsonb, 'A', 'The description explicitly states the method presented "engages all stakeholders, including customers, suppliers, and employees" in developing the change together.'),
  ('Organizational Change Management & Culture Transformation', 9, 'Why does the course frame stakeholder engagement as improving decision quality, not just reducing resistance?', '[{"label": "A", "text": "Because involving the people closest to the work surfaces information and perspectives that improve the substance of the decision itself, beyond just securing buy-in"}, {"label": "B", "text": "Because decision quality and resistance are described as completely unrelated outcomes"}, {"label": "C", "text": "Because the course claims engagement always slows down decisions without improving them"}, {"label": "D", "text": "Because only executive-level input can improve decision quality, per the course"}]'::jsonb, 'A', 'The course explicitly claims engagement improves "the quality of decisions," implying the input from engaged stakeholders makes the decision substantively better, not merely more accepted.'),
  ('Organizational Change Management & Culture Transformation', 10, 'What real-world scale of client experience does the course draw on to support its six-stage model?', '[{"label": "A", "text": "Forty-five years of experience helping companies like Merck, Shell Oil, Honeywell, Honda, Coca-Cola, and Mack Trucks manage major change and culture transformation"}, {"label": "B", "text": "A single small-business case study with no larger corporate experience"}, {"label": "C", "text": "Purely academic research with no corporate clients named"}, {"label": "D", "text": "Experience limited to one industry (retail) only"}]'::jsonb, 'A', 'The description states the course "is based on the forty five years of experience helping companies like Merck, Shell Oil, Honeywell, Honda and dozens of others."'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 1, 'Whose research is this course''s growth mindset content inspired by?', '[{"label": "A", "text": "Carol Dweck''s research"}, {"label": "B", "text": "B.F. Skinner''s behaviorist research"}, {"label": "C", "text": "Sigmund Freud''s psychoanalytic theory"}, {"label": "D", "text": "The course is not based on any named researcher"}]'::jsonb, 'A', 'The course subtitle and objectives explicitly state it is "Inspired by Carol Dweck''s research" and asks students to "Recognize key findings from Carol Dweck''s growth mindset research."'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 2, 'How many common growth-mindset roadblocks does the course cover?', '[{"label": "A", "text": "Six roadblocks"}, {"label": "B", "text": "Two roadblocks"}, {"label": "C", "text": "Ten roadblocks"}, {"label": "D", "text": "The course says there are no common roadblocks"}]'::jsonb, 'A', 'The course explicitly lists "Six Common Growth Mindset Roadblocks" as a dedicated section and learning objective.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 3, 'Which of these is explicitly named as one of the six roadblocks to a growth mindset?', '[{"label": "A", "text": "Fear of failure"}, {"label": "B", "text": "Excessive vacation time"}, {"label": "C", "text": "Too much positive feedback from managers"}, {"label": "D", "text": "Overly generous budgets"}]'::jsonb, 'A', 'The description explicitly lists "Fear of failure" (alongside lack of confidence, fear of success, perfectionism, inertia, and feeling stuck) as one of the six roadblocks.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 4, 'What is the "One Yes" challenge in this course?', '[{"label": "A", "text": "An exercise to step out of your comfort zone, adopt a stretch goal, and reflect on what you learned"}, {"label": "B", "text": "A requirement to get unanimous team approval before making any decision"}, {"label": "C", "text": "A one-time compliance sign-off with no reflection component"}, {"label": "D", "text": "A single yes/no quiz question at the end of the course"}]'::jsonb, 'A', 'The course lists "Take the One Yes challenge to step out of your comfort zone, adopt stretch goals, and reflect on what you learned" as a specific learning objective.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 5, 'What professional accreditation does this course carry?', '[{"label": "A", "text": "NASBA CPE credits (1.8), in the field of Personal Development"}, {"label": "B", "text": "A university-granted master''s degree credit"}, {"label": "C", "text": "No accreditation of any kind"}, {"label": "D", "text": "A government-issued professional license"}]'::jsonb, 'A', 'The course explicitly lists "NASBA CPE credits: 1.8" with recommended field of study "Personal Development."'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 6, 'What does the course say a growth mindset requires becoming comfortable with?', '[{"label": "A", "text": "Taking risks, receiving feedback, learning from experience, and reframing \"failure\""}, {"label": "B", "text": "Avoiding all feedback from peers and managers"}, {"label": "C", "text": "Never taking on unfamiliar or difficult tasks"}, {"label": "D", "text": "Relying solely on natural talent rather than effort"}]'::jsonb, 'A', 'The description states becoming comfortable with exactly these things — risk, feedback, learning from experience, reframing failure — is "on your way to a growth mindset."'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 7, 'A Specialist notices a colleague avoids volunteering for stretch assignments and gets visibly defensive after constructive feedback. Per this course, which roadblock(s) is this behavior most likely to reflect?', '[{"label": "A", "text": "Fear of failure and/or lack of confidence, two of the six named roadblocks to a growth mindset"}, {"label": "B", "text": "A roadblock the course does not address at all"}, {"label": "C", "text": "Simply a scheduling conflict unrelated to mindset"}, {"label": "D", "text": "Excessive growth mindset, per the course''s framework"}]'::jsonb, 'A', 'Avoiding stretch assignments and reacting defensively to feedback map directly onto the course''s named roadblocks of fear of failure and lack of confidence.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 8, 'A Specialist wants to help a peer move from a fixed to a growth mindset heading into a high-visibility project. Per the course''s framing, what should the peer try first?', '[{"label": "A", "text": "Take the One Yes challenge — commit to one stretch goal outside their comfort zone and reflect on the experience afterward"}, {"label": "B", "text": "Wait passively until the mindset shifts on its own with no action taken"}, {"label": "C", "text": "Avoid the high-visibility project entirely to minimize any risk of failure"}, {"label": "D", "text": "Request that all feedback on the project be withheld to reduce discomfort"}]'::jsonb, 'A', 'The One Yes challenge is the course''s concrete mechanism for practicing a growth mindset via a real stretch goal and reflection, rather than waiting passively.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 9, 'Per the course, how does bringing a growth mindset to an organization (not just an individual) affect outcomes?', '[{"label": "A", "text": "It can positively impact culture, innovation, engagement, and retention"}, {"label": "B", "text": "It has no measurable organizational effect, only individual effect"}, {"label": "C", "text": "It only affects how quickly performance reviews are completed"}, {"label": "D", "text": "It negatively affects innovation by discouraging risk-taking"}]'::jsonb, 'A', 'The course explicitly states organizations benefit via "culture, innovation, engagement, and retention" when a growth mindset is adopted more broadly, not just individually.'),
  ('Growth Mindset: The Key to Confidence, Impact & Fulfillment', 10, 'What shift in mindset does the course summarize as moving "from a need to prove to a desire to..."?', '[{"label": "A", "text": "IMprove"}, {"label": "B", "text": "Impress"}, {"label": "C", "text": "Ignore"}, {"label": "D", "text": "Isolate"}]'::jsonb, 'A', 'The description explicitly frames this shift as moving "from a need to prove to a desire to IMprove," capturing the growth-mindset reframing of effort and feedback.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 1, 'What are Briceño''s two core "zones," and how do their goals differ?', '[{"label": "A", "text": "Learning zone (goal: improve, embrace mistakes) vs. Performance zone (goal: execute well, minimize errors)"}, {"label": "B", "text": "Beginner zone vs. Expert zone, based purely on tenure"}, {"label": "C", "text": "Comfort zone vs. Panic zone, with no middle ground"}, {"label": "D", "text": "Practice zone vs. Rest zone"}]'::jsonb, 'A', 'These are Briceño''s own named zones and their defining goals.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 2, 'What does Briceño say is the common problem with how most people spend their time?', '[{"label": "A", "text": "They spend nearly all their time in the performance zone, which hinders long-term growth"}, {"label": "B", "text": "They spend nearly all their time in the learning zone, neglecting execution"}, {"label": "C", "text": "They split time evenly between zones, which he says is the core problem"}, {"label": "D", "text": "They spend no time in either zone"}]'::jsonb, 'A', 'This imbalance — nearly all performing, almost no deliberate learning — is the problem Briceño opens with.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 3, 'What deliberate-practice activities does Briceño attribute to Demosthenes, ancient Greece''s greatest orator?', '[{"label": "A", "text": "Studying law/philosophy/acting, practicing speeches before mirrors, using stones in his mouth to fix a lisp, and projecting his voice against ocean waves"}, {"label": "B", "text": "Only memorizing speeches by rote with no other practice"}, {"label": "C", "text": "Delivering unrehearsed speeches directly in front of large audiences from day one"}, {"label": "D", "text": "Avoiding all public speaking until he felt fully confident"}]'::jsonb, 'A', 'This is the exact set of practice activities Briceño describes as Demosthenes'' deliberate practice, all outside his "performance zone."'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 4, 'Drawing on Anders Ericsson, what four elements does Briceño say define deliberate practice?', '[{"label": "A", "text": "Breaking skills into components, working just beyond current ability, seeking frequent feedback, and ideally working with skilled coaches"}, {"label": "B", "text": "Repeating the exact same task at the same difficulty level indefinitely"}, {"label": "C", "text": "Practicing only when fully rested and only in isolation from any feedback"}, {"label": "D", "text": "Avoiding coaches so as not to bias your natural technique"}]'::jsonb, 'A', 'These four elements are given as the Ericsson-based definition of deliberate practice.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 5, 'What are Briceño''s four requirements for effective learning?', '[{"label": "A", "text": "Growth mindset, motivation to improve, knowledge of improvement strategies, and low-stakes settings"}, {"label": "B", "text": "High stakes, fixed mindset, natural talent, and public accountability"}, {"label": "C", "text": "A formal coach, a large budget, a long timeline, and public performance pressure"}, {"label": "D", "text": "Isolation, repetition, competition, and reward"}]'::jsonb, 'A', 'These four are named explicitly as Briceño''s requirements for learning to occur.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 6, 'A support engineer wants to get better at handling a rare but tricky class of ticket, but only ever encounters it live, under time pressure, in front of the customer. What does Briceño''s framework suggest is missing?', '[{"label": "A", "text": "A low-stakes learning-zone setting (e.g., practicing with sample tickets or mock scenarios) separate from the high-stakes performance-zone moment"}, {"label": "B", "text": "Nothing — live, high-pressure encounters are the ideal way to build this skill per the talk"}, {"label": "C", "text": "More performance-zone repetition is the only fix needed"}, {"label": "D", "text": "The engineer should stop handling these tickets entirely"}]'::jsonb, 'A', 'Briceño''s framework argues real skill-building requires a distinct, low-stakes learning zone — not just repeated high-stakes performance.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 7, 'A support specialist reviews their own resolved-ticket transcripts each week specifically to spot what they could have done better. Which modern example from the talk does this most resemble?', '[{"label": "A", "text": "Beyoncé reviewing concert footage nightly to identify improvements"}, {"label": "B", "text": "Top salespeople dedicating time only to closing more deals, never reviewing past calls"}, {"label": "C", "text": "Elite chess players only playing more games, never analyzing them"}, {"label": "D", "text": "None of the modern examples involve reviewing past performance"}]'::jsonb, 'A', 'This is the closest parallel among Briceño''s examples — deliberately reviewing past performance specifically to extract improvement.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 8, 'Why does Briceño emphasize "low-stakes settings" as a requirement for learning, rather than saying practice should always happen live?', '[{"label": "A", "text": "Because when mistakes carry severe consequences, people default to the performance zone''s mistake-minimizing mindset instead of taking the risks needed to learn"}, {"label": "B", "text": "Because low-stakes settings guarantee mastery regardless of effort"}, {"label": "C", "text": "Because live, high-stakes settings are always the fastest way to learn any skill"}, {"label": "D", "text": "Because low-stakes settings eliminate the need for feedback"}]'::jsonb, 'A', 'This is the underlying logic in the talk for why low-stakes conditions are necessary — they free people to embrace the mistakes that learning-zone practice requires.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 9, 'A manager wants to help their team build a genuine "learning zone" habit rather than only ever executing live work. Which practice best reflects Briceño''s recommendation?', '[{"label": "A", "text": "Dedicating protected time for deliberate, mistake-tolerant practice on specific sub-skills, separate from live ticket handling"}, {"label": "B", "text": "Adding more live tickets to everyone''s queue so they \"learn by doing\" exclusively"}, {"label": "C", "text": "Eliminating feedback sessions to reduce pressure"}, {"label": "D", "text": "Assigning only fully-mastered tasks so no mistakes ever occur"}]'::jsonb, 'A', 'This reflects Briceño''s core recommendation: carve out real learning-zone time distinct from performance-zone execution.'),
  ('TED — Eduardo Briceño: How to get better at the things you care about', 10, 'What is the overall conclusion Briceño reaches about replacing constant performance?', '[{"label": "A", "text": "People should replace constant performing with deliberate exploration, reflection, and continuous improvement"}, {"label": "B", "text": "People should eliminate the performance zone entirely and only ever practice"}, {"label": "C", "text": "People should perform constantly and never set aside time to reflect"}, {"label": "D", "text": "People should avoid feedback since it undermines confidence"}]'::jsonb, 'A', 'This is Briceño''s closing recommendation.'),
  ('Mentor for Impact - Start Mentoring', 1, 'What conversational model does the course teach for structuring mentoring conversations?', '[{"label": "A", "text": "The GROW model"}, {"label": "B", "text": "The SMART model"}, {"label": "C", "text": "The RACI model"}, {"label": "D", "text": "The SWOT model"}]'::jsonb, 'A', 'The course lists "GROW model - a structure for mentoring conversations" as a core lecture, and a printable GROW worksheet is included as a bonus resource.'),
  ('Mentor for Impact - Start Mentoring', 2, 'How does the course distinguish mentoring from coaching, counselling, and consulting?', '[{"label": "A", "text": "It has a dedicated lecture specifically explaining \"What is the difference between mentoring, coaching, counselling and consulting?\""}, {"label": "B", "text": "It claims these four terms are entirely interchangeable with no distinction"}, {"label": "C", "text": "It only defines mentoring and ignores the other three terms"}, {"label": "D", "text": "It says the difference is irrelevant to becoming a mentor"}]'::jsonb, 'A', 'This is a named lecture in the course content, explicitly addressing how mentoring differs from these adjacent disciplines.'),
  ('Mentor for Impact - Start Mentoring', 3, 'What does the course teach about sharing your own experience as a mentor?', '[{"label": "A", "text": "A framework for sharing your experience through storytelling"}, {"label": "B", "text": "That mentors should never reference their own experience"}, {"label": "C", "text": "That mentors should read from a fixed script with no personal input"}, {"label": "D", "text": "That experience-sharing is discouraged in favor of pure question-asking"}]'::jsonb, 'A', 'The description lists "Framework for sharing your experience through storytelling" among the course''s core content.'),
  ('Mentor for Impact - Start Mentoring', 4, 'What is this course explicitly designed to help someone become?', '[{"label": "A", "text": "A volunteer mentor, e.g. in an organization or a youth program"}, {"label": "B", "text": "A paid professional coaching or consulting business owner"}, {"label": "C", "text": "A certified HR business partner"}, {"label": "D", "text": "A licensed therapist"}]'::jsonb, 'A', 'The "Who this course is for" section states it targets people "planning to become a volunteer mentor," and explicitly says it is "not for those who want to start a paid coaching, mentoring or consulting business."'),
  ('Mentor for Impact - Start Mentoring', 5, 'What bonus materials does the course provide beyond the video lectures?', '[{"label": "A", "text": "A printable GROW model worksheet, a goal-setting worksheet, and a list of powerful questions for mentoring conversations"}, {"label": "B", "text": "No supplementary materials of any kind"}, {"label": "C", "text": "Only a certificate template with no practical tools"}, {"label": "D", "text": "A separate paid software license"}]'::jsonb, 'A', 'The description explicitly lists these three bonus items: a GROW worksheet, a goalsetting worksheet, and powerful mentoring questions.'),
  ('Mentor for Impact - Start Mentoring', 6, 'What does the course teach about motivating a mentee "to follow through"?', '[{"label": "A", "text": "Tips to motivate your mentee to follow through and get results, as a dedicated lecture topic"}, {"label": "B", "text": "That follow-through is entirely the mentee''s responsibility with no mentor role"}, {"label": "C", "text": "That mentors should complete tasks on the mentee''s behalf"}, {"label": "D", "text": "The topic is not addressed anywhere in the course"}]'::jsonb, 'A', '"How to get the mentee to follow through?" is a named lecture explicitly covering this exact topic.'),
  ('Mentor for Impact - Start Mentoring', 7, 'A Senior Specialist begins informally mentoring a junior teammate but keeps giving direct instructions rather than asking questions. Per the course''s GROW model, what would a more effective structure look like?', '[{"label": "A", "text": "Guiding the mentee through Goal, Reality, Options, and Will/way-forward stages via powerful questions, rather than issuing direct instructions"}, {"label": "B", "text": "Reading a fixed script verbatim with no adaptation"}, {"label": "C", "text": "Skipping any structured conversation and only giving orders"}, {"label": "D", "text": "Delegating the entire mentoring relationship to HR"}]'::jsonb, 'A', 'GROW (Goal, Reality, Options, Will/Way forward) is a question-driven coaching/mentoring structure, which is the course''s core alternative to simply issuing instructions.'),
  ('Mentor for Impact - Start Mentoring', 8, 'A Senior Specialist mentoring a new teammate isn''t sure whether their role should be to fix the mentee''s problems directly or something else. Which course lecture would help clarify that distinction?', '[{"label": "A", "text": "\"What is the difference between mentoring, coaching, counselling and consulting?\" — since these roles differ in how directive/prescriptive they are"}, {"label": "B", "text": "\"Course introduction,\" which only covers logistics"}, {"label": "C", "text": "None of the lectures address this kind of role clarity"}, {"label": "D", "text": "\"Next steps and additional resources,\" which only lists follow-on materials"}]'::jsonb, 'A', 'This lecture directly addresses how mentoring differs from more directive/prescriptive relationships like consulting, which is exactly the ambiguity in this scenario.'),
  ('Mentor for Impact - Start Mentoring', 9, 'Why does the course pair the GROW model with a storytelling framework for sharing experience, rather than teaching them as unrelated skills?', '[{"label": "A", "text": "Because effective mentoring combines structured, question-led conversation (GROW) with well-timed, relevant personal experience shared as story, rather than either alone"}, {"label": "B", "text": "Because storytelling is meant to entirely replace asking any questions"}, {"label": "C", "text": "Because GROW and storytelling are described as mutually exclusive techniques"}, {"label": "D", "text": "Because the course only ever uses one of the two techniques"}]'::jsonb, 'A', 'The course teaches both the GROW structure and a storytelling framework for sharing experience as complementary tools within the same mentoring toolkit.'),
  ('Mentor for Impact - Start Mentoring', 10, 'What review feedback does the course have that a Senior Specialist should weigh when deciding how to supplement it for a technical mentoring context?', '[{"label": "A", "text": "A reviewer noted the material \"was not engaging\" and that \"check your knowledge questions could encourage learners to participate,\" suggesting the course may benefit from added interactivity for some learners"}, {"label": "B", "text": "All reviews are unanimously perfect with zero critical feedback"}, {"label": "C", "text": "Reviewers universally say the course is far too advanced for any audience"}, {"label": "D", "text": "The course has been removed from the platform due to negative reviews"}]'::jsonb, 'A', 'One visible review states the "material was not engaging" and suggests more interactive knowledge checks, which is realistic context for a Senior Specialist judging fit for their own team.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 1, 'What conventional idea does Kaufman challenge with his "20 hours" claim?', '[{"label": "A", "text": "The ''10,000-hour rule'' for mastery"}, {"label": "B", "text": "The idea that talent alone determines skill"}, {"label": "C", "text": "The idea that skills can never be learned as an adult"}, {"label": "D", "text": "The idea that coaching is required for any new skill"}]'::jsonb, 'A', 'Kaufman explicitly positions his 20-hour claim as a contrast to the popularized 10,000-hour rule for mastery, not for basic competence.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 2, 'What does Kaufman identify as the primary barrier to learning a new skill?', '[{"label": "A", "text": "The initial frustration phase, when learners feel incompetent and give up"}, {"label": "B", "text": "A lack of natural talent"}, {"label": "C", "text": "Not having access to a professional coach"}, {"label": "D", "text": "Not having enough total free time in a given year"}]'::jsonb, 'A', 'This is the barrier Kaufman names as the main reason people quit before making progress.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 3, 'What is the first of Kaufman''s four steps to rapid skill acquisition?', '[{"label": "A", "text": "Decompose the skill into smaller, manageable components"}, {"label": "B", "text": "Commit to 10,000 hours immediately"}, {"label": "C", "text": "Hire a professional coach before doing anything else"}, {"label": "D", "text": "Take a written test to establish a baseline"}]'::jsonb, 'A', 'Decomposition is the first named step, illustrated with the bread-baking and yoga examples.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 4, 'What does Kaufman recommend for the "study strategically" step, and what pitfall does he warn against?', '[{"label": "A", "text": "Gather three to five resources to recognize mistakes, but avoid using research itself as a form of procrastination"}, {"label": "B", "text": "Read as many books as possible before ever practicing"}, {"label": "C", "text": "Avoid any external resources entirely and rely purely on trial and error"}, {"label": "D", "text": "Only ever use one single resource to avoid confusion"}]'::jsonb, 'A', 'Kaufman explicitly names this resource-count guidance and the procrastination risk of over-researching instead of practicing.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 5, 'What technique does Kaufman suggest for the "eliminate distractions" step, and what is it called?', '[{"label": "A", "text": "\"Temptation bundling\" — pairing practice with an enjoyable activity, like listening to a podcast while practicing"}, {"label": "B", "text": "Working in complete isolation with no other activity ever combined"}, {"label": "C", "text": "Practicing only late at night to avoid any distractions"}, {"label": "D", "text": "Avoiding practice on weekends entirely"}]'::jsonb, 'A', 'Kaufman names this exact technique and gives these exact pairing examples.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 6, 'A support specialist wants to learn a new scripting language for automating repetitive tasks but keeps reading tutorials for weeks without writing any code. What does Kaufman''s framework say about this pattern?', '[{"label": "A", "text": "They may be using research as a form of procrastination instead of starting to practice — Kaufman warns against over-researching at the expense of doing"}, {"label": "B", "text": "This is the ideal approach and they should keep reading indefinitely before writing any code"}, {"label": "C", "text": "Kaufman recommends skipping resources entirely and never reading documentation"}, {"label": "D", "text": "This pattern has no bearing on his framework"}]'::jsonb, 'A', 'This directly matches Kaufman''s warning about the ''study strategically'' step being misused as a stalling tactic.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 7, 'A manager wants a new hire to build basic competence in a new internal tool quickly. Based on Kaufman''s model, roughly how much dedicated practice time should get them there, and over what timeframe?', '[{"label": "A", "text": "About 20 hours, roughly 45 minutes a day for about a month"}, {"label": "B", "text": "10,000 hours, over roughly 5-10 years"}, {"label": "C", "text": "2 hours total, in a single afternoon"}, {"label": "D", "text": "There is no meaningful correlation between hours and basic competence in this model"}]'::jsonb, 'A', 'This is Kaufman''s specific figure and framing for reaching basic competence, not mastery.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 8, 'Why does Kaufman choose 20 hours specifically as his benchmark, according to the talk?', '[{"label": "A", "text": "It is chosen for practical feasibility, making skill acquisition feel achievable for busy people — not because of some precise scientific threshold"}, {"label": "B", "text": "It is based on a rigid scientific formula applicable to literally any skill to reach true mastery"}, {"label": "C", "text": "It represents the exact time needed to reach expert-level mastery in any domain"}, {"label": "D", "text": "It has no stated reasoning at all in the talk"}]'::jsonb, 'A', 'Kaufman is explicit that the number is chosen for approachability, not as a precise mastery threshold.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 9, 'A learner hits the "I''m terrible at this" phase a few hours into practicing a new skill and considers quitting. What does Kaufman say about this moment?', '[{"label": "A", "text": "This is the expected \"frustration barrier\" — persisting through it is exactly what leads to the payoff by hour 20"}, {"label": "B", "text": "This means the skill was chosen poorly and should be abandoned immediately"}, {"label": "C", "text": "This phase never actually occurs if the four steps are followed correctly"}, {"label": "D", "text": "This indicates a lack of natural talent that no amount of practice will overcome"}]'::jsonb, 'A', 'Kaufman names this exact frustration barrier as a normal, expected part of the 20-hour process, not a sign to quit.'),
  ('TED — Josh Kaufman: The first 20 hours — how to learn anything', 10, 'What is the relationship between Kaufman''s 20-hour method and true mastery of a skill?', '[{"label": "A", "text": "The 20-hour method is about reaching basic competence quickly, not full mastery — mastery still requires far more sustained deliberate practice"}, {"label": "B", "text": "20 hours is presented as sufficient for full mastery of any skill"}, {"label": "C", "text": "The talk claims mastery is impossible for adults regardless of hours invested"}, {"label": "D", "text": "There is no distinction drawn between competence and mastery in the talk"}]'::jsonb, 'A', 'Kaufman''s framing directly opposes the 10,000-hour mastery rule by narrowing his claim to reaching competence, not expertise.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 1, 'Which of Headlee''s 10 rules does she call "the most important one"?', '[{"label": "A", "text": "Listen"}, {"label": "B", "text": "Be brief"}, {"label": "C", "text": "Don''t multitask"}, {"label": "D", "text": "Use open-ended questions"}]'::jsonb, 'A', 'Headlee explicitly singles this rule out as the most important of the ten.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 2, 'What does the "use open-ended questions" rule recommend?', '[{"label": "A", "text": "Asking who/what/when/where/why/how questions to encourage deeper responses"}, {"label": "B", "text": "Only asking yes/no questions to keep things efficient"}, {"label": "C", "text": "Avoiding questions altogether to let the other person talk uninterrupted"}, {"label": "D", "text": "Asking only rhetorical questions"}]'::jsonb, 'A', 'This is Headlee''s stated guidance for this rule.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 3, 'What does "don''t equate your experience with theirs" mean as a rule?', '[{"label": "A", "text": "Focus on their story rather than pivoting to your own similar experience"}, {"label": "B", "text": "Always share a matching personal story to build rapport"}, {"label": "C", "text": "Point out how your experience was harder than theirs"}, {"label": "D", "text": "Refuse to ever discuss your own experiences in any conversation"}]'::jsonb, 'A', 'This is the exact behavior Headlee warns against — redirecting the conversation to your own similar story.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 4, 'What does the "be brief" rule say about how long a good contribution should be?', '[{"label": "A", "text": "Short enough to retain interest, but long enough to cover the subject"}, {"label": "B", "text": "As long as possible to demonstrate thorough knowledge"}, {"label": "C", "text": "A single word whenever possible"}, {"label": "D", "text": "Exactly the same length as the other person''s turn"}]'::jsonb, 'A', 'This is Headlee''s own phrasing of the rule.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 5, 'What does "stay out of the weeds" advise against?', '[{"label": "A", "text": "Getting bogged down in unnecessary details instead of focusing on broader themes and emotions"}, {"label": "B", "text": "Discussing any technical topic at all"}, {"label": "C", "text": "Asking any follow-up questions"}, {"label": "D", "text": "Talking about feelings instead of facts"}]'::jsonb, 'A', 'This matches Headlee''s described rule about avoiding excessive, unnecessary detail.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 6, 'A support engineer is on a call with a frustrated customer and keeps checking Slack messages while the customer explains the issue. Which rule are they violating?', '[{"label": "A", "text": "Don''t multitask"}, {"label": "B", "text": "Be brief"}, {"label": "C", "text": "Use open-ended questions"}, {"label": "D", "text": "Don''t repeat yourself"}]'::jsonb, 'A', 'This is a direct violation of the "be fully present" rule, which specifically calls out divided attention as the problem.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 7, 'A teammate responds to a customer''s frustration by immediately launching into their own similar bad experience with another product, rather than staying with the customer''s story. Which rule does this violate?', '[{"label": "A", "text": "Don''t equate your experience with theirs"}, {"label": "B", "text": "Use open-ended questions"}, {"label": "C", "text": "Stay out of the weeds"}, {"label": "D", "text": "Go with the flow"}]'::jsonb, 'A', 'This is precisely the pattern Headlee warns against — redirecting to your own comparable experience instead of staying with theirs.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 8, 'A support engineer explains the same troubleshooting step three different ways in the same reply because they''re worried the customer missed it the first time. Which rule addresses this directly?', '[{"label": "A", "text": "Try not to repeat yourself — restating points can feel condescending"}, {"label": "B", "text": "Don''t pontificate"}, {"label": "C", "text": "If you don''t know, say that you don''t know"}, {"label": "D", "text": "Go with the flow"}]'::jsonb, 'A', 'Headlee''s rule specifically warns that repeating yourself can come across as condescending, even when the intent is helpful clarity.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 9, 'A specialist is asked a question they genuinely don''t know the answer to, and they guess at an answer rather than admit uncertainty. Which rule does this violate?', '[{"label": "A", "text": "If you don''t know, say that you don''t know"}, {"label": "B", "text": "Don''t pontificate"}, {"label": "C", "text": "Be brief"}, {"label": "D", "text": "Stay out of the weeds"}]'::jsonb, 'A', 'This rule directly addresses being honest about knowledge gaps rather than pretending expertise.'),
  ('TED — Celeste Headlee: 10 ways to have a better conversation', 10, 'Which rule specifically addresses entering a conversation ready to deliver opinions rather than to learn something new?', '[{"label": "A", "text": "Don''t pontificate"}, {"label": "B", "text": "Be brief"}, {"label": "C", "text": "Go with the flow"}, {"label": "D", "text": "Listen"}]'::jsonb, 'A', 'Headlee''s rule frames this exact posture — arriving to lecture rather than to learn — as the thing to avoid.'),
  ('Mastering Collaboration: Work together for the best results', 1, 'What does Section 3, "Leading collaborative teams," specifically cover, per the course?', '[{"label": "A", "text": "The fundamentals of forming and leading a collaborative team"}, {"label": "B", "text": "Only how to join an existing team as a member"}, {"label": "C", "text": "Legal contract negotiation between companies"}, {"label": "D", "text": "Personal productivity tips unrelated to teams"}]'::jsonb, 'A', 'The course''s stated learning objectives include "The fundamentals of forming and leading a collaborative team," which is the focus of Section 3.'),
  ('Mastering Collaboration: Work together for the best results', 2, 'What statistic does the course cite about employees and performance reviews?', '[{"label": "A", "text": "Only 18% of employees get communication evaluations during their performance reviews, despite nearly 75% of employers rating collaboration as one of the most important activities"}, {"label": "B", "text": "100% of employees are evaluated on collaboration every review cycle"}, {"label": "C", "text": "The course cites no statistics on this topic"}, {"label": "D", "text": "Only 5% of employers consider collaboration important at all"}]'::jsonb, 'A', 'The course description opens with exactly this statistic: 75% of employers value collaboration highly, yet only 18% of employees get communication evaluations in reviews.'),
  ('Mastering Collaboration: Work together for the best results', 3, 'What percentage of employees, per the course, believe their organization would be more successful with more flexible and collaborative ways of working?', '[{"label": "A", "text": "73%"}, {"label": "B", "text": "10%"}, {"label": "C", "text": "50%"}, {"label": "D", "text": "The course does not cite this statistic"}]'::jsonb, 'A', 'The course states "73% of employees believe their organization would be more successful if they were able to work in more flexible and collaborative ways."'),
  ('Mastering Collaboration: Work together for the best results', 4, 'What organizational-level benefit of effective collaboration does the course specifically list, beyond individual-level benefits?', '[{"label": "A", "text": "Shortened development time and lower costs"}, {"label": "B", "text": "Guaranteed elimination of all project risk"}, {"label": "C", "text": "Reduced need for any documentation"}, {"label": "D", "text": "Automatic compliance with all regulations"}]'::jsonb, 'A', 'The course lists organizational-level benefits including "Shorten development time" and "Lower costs," distinct from the individual-level benefits it also names.'),
  ('Mastering Collaboration: Work together for the best results', 5, 'What does Section 4, "Ensuring effective collaboration within your company," address, per the course''s objectives?', '[{"label": "A", "text": "How to ensure collaborative teams work successfully within a company"}, {"label": "B", "text": "Only how to collaborate with external vendors, not internal teams"}, {"label": "C", "text": "Payroll processing for cross-functional teams"}, {"label": "D", "text": "The course does not include a section on company-wide collaboration"}]'::jsonb, 'A', 'This is one of the course''s stated learning objectives, directly mapping to Section 4''s content.'),
  ('Mastering Collaboration: Work together for the best results', 6, 'Who is this course explicitly designed to help, per its "Who this course is for" section?', '[{"label": "A", "text": "Employees, managers, and leaders/executives at any level looking to collaborate more effectively"}, {"label": "B", "text": "Only senior executives, excluding individual contributors"}, {"label": "C", "text": "Only new hires during onboarding week"}, {"label": "D", "text": "Only external contractors, not full-time employees"}]'::jsonb, 'A', 'The course lists employees, managers, and leaders/executives all as intended audiences, at multiple organizational levels.'),
  ('Mastering Collaboration: Work together for the best results', 7, 'A Specialist has been asked to help form a new cross-functional working group from scratch, not just participate in an existing one. Which part of the course speaks most directly to that responsibility?', '[{"label": "A", "text": "Section 3, \"Leading collaborative teams,\" which covers the fundamentals of forming and leading such a team"}, {"label": "B", "text": "Section 2, which only covers being a team member"}, {"label": "C", "text": "Section 5, \"Wrapping up,\" which has no formation content"}, {"label": "D", "text": "None of the sections address forming a new team"}]'::jsonb, 'A', 'Forming a new team from scratch is precisely what Section 3 (forming/leading collaborative teams) addresses, beyond the more basic being-a-team-member content in Section 2.'),
  ('Mastering Collaboration: Work together for the best results', 8, 'A Specialist wants to make the case to their manager that the organization should invest more in collaboration tooling and practices. Which statistic from the course most directly supports that pitch?', '[{"label": "A", "text": "86% of employees and executives cite lack of collaboration and ineffective communication as the cause of most workplace failures"}, {"label": "B", "text": "A statistic claiming collaboration has no measurable effect on workplace outcomes"}, {"label": "C", "text": "A statistic about unrelated marketing conversion rates"}, {"label": "D", "text": "The course provides no statistics that could support such a pitch"}]'::jsonb, 'A', 'This is exactly the kind of business-case statistic the course cites, tying poor collaboration directly to workplace failure.'),
  ('Mastering Collaboration: Work together for the best results', 9, 'Why does the course pair "online collaboration and effectively collaborating across different teams" with organizational culture-building, rather than treating them as separate topics?', '[{"label": "A", "text": "Because sustaining collaboration across distributed or cross-functional teams depends on the same supportive culture, values, and practices the course teaches for building a \"thriving culture of collaboration\""}, {"label": "B", "text": "Because online collaboration tools automatically create a collaborative culture with no other input needed"}, {"label": "C", "text": "Because the course treats remote collaboration as entirely unrelated to culture"}, {"label": "D", "text": "Because cross-team collaboration is described as impossible without in-person meetings"}]'::jsonb, 'A', 'The course''s own objectives link online/cross-team collaboration and "what you need to create and support a thriving culture of collaboration" as connected topics, not separate ones.'),
  ('Mastering Collaboration: Work together for the best results', 10, 'At the individual level, what benefit does the course say effective collaboration provides, beyond simply "working well with others"?', '[{"label": "A", "text": "It teaches new skills and techniques and strengthens business understanding"}, {"label": "B", "text": "It guarantees an immediate promotion"}, {"label": "C", "text": "It has no individual-level benefit, only organizational benefit"}, {"label": "D", "text": "It eliminates the need for any individual skill development"}]'::jsonb, 'A', 'The course explicitly lists "Teach new skills and techniques" and "Strengthen business understanding" among the individual-level benefits of effective collaboration.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 1, 'How does Siegel define "simplicity" in this talk?', '[{"label": "A", "text": "A means to achieving clarity, transparency, and empathy — building humanity into communications"}, {"label": "B", "text": "Removing all detail from any document regardless of context"}, {"label": "C", "text": "A purely aesthetic, design-only concern with no communication purpose"}, {"label": "D", "text": "A legal requirement with no connection to customer experience"}]'::jsonb, 'A', 'This is Siegel''s own definition, given verbatim.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 2, 'What was the outcome of President Obama''s challenge related to consumer credit agreements?', '[{"label": "A", "text": "Siegel developed a one-page, plain-English credit agreement verified with top consumer credit lawyers"}, {"label": "B", "text": "All credit agreements were legally banned"}, {"label": "C", "text": "Nothing changed — the challenge was declined"}, {"label": "D", "text": "Credit agreements were made twice as long to cover more edge cases"}]'::jsonb, 'A', 'This is the exact project outcome described in the talk.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 3, 'What computational aid did Siegel add to the online credit agreement, working with Harvard Business School?', '[{"label": "A", "text": "A tool showing real cost impact, e.g. how a $62 meal ends up costing $99.17 with minimum payments"}, {"label": "B", "text": "A tool that hides all fees from the customer entirely"}, {"label": "C", "text": "A currency converter with no connection to repayment costs"}, {"label": "D", "text": "A tool that only shows the minimum payment amount, with no total-cost context"}]'::jsonb, 'A', 'This specific example is used in the talk to show the value of making real costs transparent.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 4, 'How did Siegel approach simplifying the roughly 200 million IRS letters sent annually?', '[{"label": "A", "text": "Tested a \"simplicity lab\" on 1,000 letters covering 70% of transactions, rewriting them in plain English"}, {"label": "B", "text": "Eliminated all written communication from the IRS entirely"}, {"label": "C", "text": "Left the content unchanged but only altered the font"}, {"label": "D", "text": "Only simplified letters sent to businesses, not individuals"}]'::jsonb, 'A', 'This matches the exact scope and method described for the IRS letters project.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 5, 'What format did Siegel use to redesign the IBM agreement, and what did it clarify?', '[{"label": "A", "text": "A grid-based calendar format defining mutual responsibilities by date"}, {"label": "B", "text": "A single unbroken paragraph with no headings"}, {"label": "C", "text": "A slide deck with no written agreement at all"}, {"label": "D", "text": "A purely verbal agreement with no documentation"}]'::jsonb, 'A', 'This is the specific redesign approach described for the IBM agreement.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 6, 'A support team is drafting a customer-facing knowledge base article full of internal jargon and legal caveats. Which of Siegel''s principles applies most directly?', '[{"label": "A", "text": "Simplicity should serve clarity, transparency, and empathy — the article should be rewritten so a real customer can understand it, not just satisfy internal reviewers"}, {"label": "B", "text": "Legal caveats should always be maximized regardless of customer readability"}, {"label": "C", "text": "Jargon should be preserved to sound more authoritative"}, {"label": "D", "text": "Siegel''s principles apply only to government documents, not company knowledge bases"}]'::jsonb, 'A', 'This directly extends Siegel''s core philosophy to a support-team documentation context.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 7, 'Why does Siegel call out ''stealth provisions'' in business agreements as a problem worth opposing?', '[{"label": "A", "text": "Because hidden or buried terms undermine the transparency and empathy simplicity is meant to provide"}, {"label": "B", "text": "Because stealth provisions are required by law in every contract"}, {"label": "C", "text": "Because they make contracts shorter, which he otherwise supports"}, {"label": "D", "text": "Because they have no actual effect on customers"}]'::jsonb, 'A', 'Siegel frames opposing "stealth provisions" as part of his broader call for transparency in agreements.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 8, 'What real-world consequence does Siegel cite for veterans navigating benefits paperwork?', '[{"label": "A", "text": "A \"blizzard of paperwork\" that creates real difficulty accessing benefits"}, {"label": "B", "text": "No paperwork is required at all for veterans"}, {"label": "C", "text": "Veterans receive automatic benefits with zero documentation"}, {"label": "D", "text": "This example is not part of the talk"}]'::jsonb, 'A', 'This is one of Siegel''s opening examples of the real-world harm caused by unintelligible official documents.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 9, 'Why does Siegel use a grid/calendar format for the IBM agreement rather than more prose?', '[{"label": "A", "text": "Because it proved effective for clearly defining mutual responsibilities tied to specific dates, which prose often obscures"}, {"label": "B", "text": "Because it was required by IBM''s legal department with no clarity benefit"}, {"label": "C", "text": "Because grids are always shorter than prose regardless of content"}, {"label": "D", "text": "Because this format removes the need for any legal review"}]'::jsonb, 'A', 'The grid format is specifically credited with making mutual, date-based responsibilities clearer than a prose contract would.'),
  ('TED — Alan Siegel: Let''s simplify legal jargon!', 10, 'What is Siegel''s overall call to action at the end of the talk?', '[{"label": "A", "text": "Make clarity, transparency, and simplicity a national priority in both government and business communication"}, {"label": "B", "text": "Abandon all legal review of consumer documents"}, {"label": "C", "text": "Restrict plain-language efforts to government documents only, leaving business agreements unchanged"}, {"label": "D", "text": "Increase the length of consumer agreements to cover more contingencies"}]'::jsonb, 'A', 'This is Siegel''s closing call to action.'),
  ('Stakeholder Management', 1, 'What two dimensions does the course teach for mapping stakeholders?', '[{"label": "A", "text": "Their level of engagement and their level of influence"}, {"label": "B", "text": "Only their job title, with no other dimension"}, {"label": "C", "text": "Only their physical office location"}, {"label": "D", "text": "Only their years of tenure at the company"}]'::jsonb, 'A', 'The course''s objectives state you''ll "identify them and find their level of engagement and influence" as the basis for stakeholder mapping.'),
  ('Stakeholder Management', 2, 'What does the course say is needed throughout the project life cycle, not just at kickoff, regarding stakeholders?', '[{"label": "A", "text": "Ongoing engagement, collaborating with them successfully to achieve the shared goal at every stage"}, {"label": "B", "text": "A single stakeholder meeting at the very start, with no further contact"}, {"label": "C", "text": "Stakeholder engagement only at project close-out"}, {"label": "D", "text": "The course says stakeholder engagement is unnecessary after initial planning"}]'::jsonb, 'A', 'The description states you need to "engage with your stakeholders throughout the project life cycle collaborating with them successfully to achieve the goal."'),
  ('Stakeholder Management', 3, 'What does the course say about stakeholders being at "different engagement and influence levels" across project stages?', '[{"label": "A", "text": "At each stage and phase of a release, you deal with different types of stakeholders at different engagement/influence levels, so their goals must be identified and matched to the project''s goal"}, {"label": "B", "text": "Stakeholder engagement and influence levels never change across a project"}, {"label": "C", "text": "Only the highest-influence stakeholder matters at any given stage"}, {"label": "D", "text": "The course treats all stakeholders as having identical influence at all times"}]'::jsonb, 'A', 'The description explicitly states this: at each stage/phase of releases you deal with different stakeholders at different levels, whose goals need to be identified and matched with the project''s goal.'),
  ('Stakeholder Management', 4, 'What communication-related skill does the course explicitly teach for managing stakeholders?', '[{"label": "A", "text": "Effective communication skills to manage the stakeholders"}, {"label": "B", "text": "Only written memos, with no verbal communication content"}, {"label": "C", "text": "Legal contract drafting"}, {"label": "D", "text": "Social media marketing copywriting"}]'::jsonb, 'A', 'The course''s learning objectives explicitly list "learn the effective communication skills to manage the stakeholders."'),
  ('Stakeholder Management', 5, 'Which section of the course is dedicated specifically to reinforcing what was learned?', '[{"label": "A", "text": "\"Quiz and Revision Time\""}, {"label": "B", "text": "\"Who is a Stakeholder?\""}, {"label": "C", "text": "\"Map Your Stakeholders and Requirements\""}, {"label": "D", "text": "The course includes no revision or review section"}]'::jsonb, 'A', 'The course content list includes "Quiz and Revision Time" as one of its six sections, dedicated to reinforcing the material.'),
  ('Stakeholder Management', 6, 'Beyond project delivery, what other use cases does the course say its stakeholder tools and techniques apply to?', '[{"label": "A", "text": "Sales pitches and team management, among other uses"}, {"label": "B", "text": "Only project delivery, with no other stated application"}, {"label": "C", "text": "Only academic research papers"}, {"label": "D", "text": "Only legal contract negotiation"}]'::jsonb, 'A', 'The course''s objectives state the techniques "can be used for project delivery, sales pitch, team management, etc."'),
  ('Stakeholder Management', 7, 'A Senior Specialist is planning a cross-functional escalation process change and has a long list of interested parties. Per the course, what should they do before deciding how much time to invest engaging each one?', '[{"label": "A", "text": "Map each stakeholder''s engagement level and influence level, so effort can be prioritized based on both dimensions rather than treating everyone identically"}, {"label": "B", "text": "Engage every stakeholder with exactly equal time and attention regardless of influence"}, {"label": "C", "text": "Only engage the single most senior stakeholder and ignore the rest entirely"}, {"label": "D", "text": "Skip stakeholder mapping since it is described as optional busywork"}]'::jsonb, 'A', 'The course''s core stakeholder-mapping approach is explicitly two-dimensional (engagement and influence), which is meant to guide where to focus effort, not to treat every stakeholder identically.'),
  ('Stakeholder Management', 8, 'Midway through a multi-quarter initiative, a Senior Specialist notices a previously low-influence stakeholder has become much more influential after a reorg. Per the course, what does this imply for the stakeholder management approach?', '[{"label": "A", "text": "Stakeholder mapping should be revisited across the project life cycle, since engagement and influence levels can shift over time and at different stages"}, {"label": "B", "text": "The original stakeholder map from kickoff should never be revisited once set"}, {"label": "C", "text": "Reorgs are explicitly stated to have no effect on stakeholder influence"}, {"label": "D", "text": "Only stakeholders present at the original kickoff meeting should ever be tracked"}]'::jsonb, 'A', 'The course explicitly frames stakeholder types, engagement, and influence as varying "at each and every stage and phase," implying the map needs revisiting as circumstances (like a reorg) change.'),
  ('Stakeholder Management', 9, 'Why might a Senior Specialist find the stakeholder-management techniques from this course useful outside formal project management, e.g. in an internal sales pitch to leadership for more support tooling?', '[{"label": "A", "text": "Because the course explicitly states its tools and techniques generalize to sales pitches and team management, not just formal projects"}, {"label": "B", "text": "Because the course explicitly restricts its techniques to certified Project Managers only"}, {"label": "C", "text": "Because stakeholder mapping is described as irrelevant to any internal pitch"}, {"label": "D", "text": "Because the course only applies to external customer relationships, never internal ones"}]'::jsonb, 'A', 'The course explicitly lists sales pitches and team management as applications of the same stakeholder techniques, beyond formal project delivery.'),
  ('Stakeholder Management', 10, 'What broad range of learners does the course say can benefit from it, per its "Who this course is for" list?', '[{"label": "A", "text": "Students, professionals, project managers, consultants, teams, and software developers/engineers"}, {"label": "B", "text": "Only certified PMP holders"}, {"label": "C", "text": "Only C-level executives"}, {"label": "D", "text": "Only external auditors"}]'::jsonb, 'A', 'The "Who this course is for" list explicitly names all of these groups as intended learners.'),
  ('TED — Derek Sivers: How to start a movement', 1, 'What does Sivers say is required of the initial "lone nut" who starts dancing alone?', '[{"label": "A", "text": "Courage to stand out and accept ridicule"}, {"label": "B", "text": "A formal title or authority over the group"}, {"label": "C", "text": "A guarantee that others will join immediately"}, {"label": "D", "text": "A pre-written plan distributed to the crowd"}]'::jsonb, 'A', 'This is the trait Sivers attributes to the initial leader figure in his example.'),
  ('TED — Derek Sivers: How to start a movement', 2, 'What does Sivers say is the critical, most underestimated role in starting a movement?', '[{"label": "A", "text": "The first follower"}, {"label": "B", "text": "The second follower"}, {"label": "C", "text": "The original \"lone nut\" leader"}, {"label": "D", "text": "The crowd of onlookers who never join"}]'::jsonb, 'A', 'Sivers'' central claim is that "the first follower is what transforms a lone nut into a leader" — an underappreciated form of leadership.'),
  ('TED — Derek Sivers: How to start a movement', 3, 'What happens, per Sivers, once a second person joins the original dancer?', '[{"label": "A", "text": "Momentum builds — \"three is a crowd, and a crowd is news\""}, {"label": "B", "text": "The movement typically collapses at that point"}, {"label": "C", "text": "Nothing changes until at least ten people join"}, {"label": "D", "text": "The original leader is expected to step aside immediately"}]'::jsonb, 'A', 'This is Sivers'' exact phrasing describing the tipping point once a third participant joins.'),
  ('TED — Derek Sivers: How to start a movement', 4, 'Why does joining become progressively less risky as more people participate, according to Sivers?', '[{"label": "A", "text": "People increasingly join to avoid standing out negatively, becoming part of the \"in-crowd\" rather than risking being the odd one out"}, {"label": "B", "text": "Because official rules require participation once a quorum is reached"}, {"label": "C", "text": "Because the risk profile is identical regardless of how many people have joined"}, {"label": "D", "text": "Because Sivers argues risk actually increases as more people join"}]'::jsonb, 'A', 'This is Sivers'' explanation for why participation snowballs as the "crowd" grows.'),
  ('TED — Derek Sivers: How to start a movement', 5, 'What is Sivers'' central, somewhat provocative claim about leadership itself?', '[{"label": "A", "text": "Leadership is over-glorified — the first follower deserves as much credit as the leader for transforming a lone nut into a movement"}, {"label": "B", "text": "Leadership is the only role that matters; followers are interchangeable and unimportant"}, {"label": "C", "text": "There is no meaningful concept of \"followership\" in his framework"}, {"label": "D", "text": "Movements never actually require a leader at all"}]'::jsonb, 'A', 'This is Sivers'' explicit reframing of leadership at the heart of the talk.'),
  ('TED — Derek Sivers: How to start a movement', 6, 'A junior support engineer sees a senior colleague quietly start a new best practice (e.g., writing better internal notes) that nobody official asked for. If the junior engineer is the first to adopt it too, how would Sivers frame their role?', '[{"label": "A", "text": "As the critical ''first follower,'' whose adoption is what actually turns the senior colleague''s solo effort into something others will follow"}, {"label": "B", "text": "As irrelevant, since only the original person who started the practice matters"}, {"label": "C", "text": "As a follower with no leadership significance at all"}, {"label": "D", "text": "As someone who should wait for a formal directive before adopting anything"}]'::jsonb, 'A', 'This directly applies Sivers'' first-follower framing to a workplace context — the first follower''s buy-in is what starts the momentum.'),
  ('TED — Derek Sivers: How to start a movement', 7, 'Why does Sivers say the ''lone nut'' needs the first follower specifically, rather than needing many followers all at once?', '[{"label": "A", "text": "Because the first follower''s public endorsement is what legitimizes the idea and reduces the risk for everyone who comes after"}, {"label": "B", "text": "Because ideas never need any endorsement to spread"}, {"label": "C", "text": "Because Sivers argues the lone nut should recruit followers privately, one at a time, in secret"}, {"label": "D", "text": "Because the first follower''s role is purely symbolic and has no practical effect on adoption"}]'::jsonb, 'A', 'This captures why the first follower specifically (not just followers in general) is pivotal — their visible buy-in changes the risk calculus for everyone watching.'),
  ('TED — Derek Sivers: How to start a movement', 8, 'What does Sivers urge listeners to do, based on his closing message?', '[{"label": "A", "text": "Have the courage to follow and show others how to follow, not assume everyone must lead"}, {"label": "B", "text": "Always aim to be the original \"lone nut\" and never a follower"}, {"label": "C", "text": "Avoid joining any new idea until it has near-universal adoption"}, {"label": "D", "text": "Wait for formal permission before supporting any new idea"}]'::jsonb, 'A', 'This is Sivers'' explicit closing call to action.'),
  ('TED — Derek Sivers: How to start a movement', 9, 'A new internal process is proposed but no one adopts it, and it quietly dies. Per Sivers'' framework, what is the most likely missing ingredient?', '[{"label": "A", "text": "A visible first follower whose adoption would have legitimized the idea for others"}, {"label": "B", "text": "A written policy document, which Sivers says is the only thing that matters"}, {"label": "C", "text": "Nothing was missing — ideas succeed or fail purely at random"}, {"label": "D", "text": "The original proposer needed to have higher formal authority"}]'::jsonb, 'A', 'Per Sivers'' model, ideas often stall not from a weak original idea but from the absence of that crucial first, visible follower.'),
  ('TED — Derek Sivers: How to start a movement', 10, 'How does Sivers characterize the ongoing participants who join once the movement already has momentum, compared to the first follower?', '[{"label": "A", "text": "They join to avoid standing out negatively (an \"in-crowd\" dynamic), which is a different motivation than the first follower''s original risk-taking endorsement"}, {"label": "B", "text": "They are described as taking on exactly the same risk as the first follower"}, {"label": "C", "text": "Sivers argues later joiners are always more important than the first follower"}, {"label": "D", "text": "Sivers does not distinguish between early and late joiners at all"}]'::jsonb, 'A', 'Sivers explicitly separates the courageous, risk-taking first follower from later joiners who are mainly avoiding being left out.'),
  ('Collaboration with Emotional Intelligence', 1, 'What does the course say about labeling emotions as simply "positive" and "negative"?', '[{"label": "A", "text": "This is \"not that helpful,\" since emotions cannot really be labeled that way, and the course covers the myths around this framing"}, {"label": "B", "text": "The course fully endorses a strict positive/negative emotion framework"}, {"label": "C", "text": "The course says only negative emotions are relevant to collaboration"}, {"label": "D", "text": "The course avoids discussing emotions at all"}]'::jsonb, 'A', 'The description explicitly states labeling emotions positive/negative "is not that helpful. This is not that helpful because emotions cannot really be labelled in that way," and covers the related myths.'),
  ('Collaboration with Emotional Intelligence', 2, 'How many practical activities does the course include, and what do they require?', '[{"label": "A", "text": "Seven practical activities, requiring engagement with your collaborative team and work outside the course itself"}, {"label": "B", "text": "Zero activities; the course is video-only"}, {"label": "C", "text": "One single optional activity with no team involvement"}, {"label": "D", "text": "Fifty structured group exercises"}]'::jsonb, 'A', 'The description states "There are SEVEN practical activities...All of them require you to engage with your collaborative team and do some work outside of the course."'),
  ('Collaboration with Emotional Intelligence', 3, 'What does the course say about behavioural styles?', '[{"label": "A", "text": "It reviews the strengths and liabilities of each style, with a self-assessment questionnaire to identify your own preferred style"}, {"label": "B", "text": "It claims there is only one correct behavioural style for effective collaboration"}, {"label": "C", "text": "Behavioural styles are described as irrelevant to collaboration"}, {"label": "D", "text": "The course provides no self-assessment component"}]'::jsonb, 'A', 'The description states behavioural styles "are reviewed looking at the strengths and liabilities of each," with a questionnaire to identify your own preferred style.'),
  ('Collaboration with Emotional Intelligence', 4, 'What technique does the course teach for running more effective collaborative meetings?', '[{"label": "A", "text": "Mindfulness techniques"}, {"label": "B", "text": "Robert''s Rules of Order exclusively"}, {"label": "C", "text": "A rigid fixed agenda template with no flexibility"}, {"label": "D", "text": "The course does not address meeting facilitation"}]'::jsonb, 'A', 'The course explicitly lists "Explore how to use mindfulness techniques to run collaborative meetings more effectively" among its learning objectives.'),
  ('Collaboration with Emotional Intelligence', 5, 'What does the course say about where collaboration "most often" happens within organizations?', '[{"label": "A", "text": "Within fairly small teams — functional teams, time-limited project teams, or cross-functional management teams"}, {"label": "B", "text": "Only across an entire company of thousands simultaneously"}, {"label": "C", "text": "Only between two individuals in a one-on-one setting, never in teams"}, {"label": "D", "text": "Only at the board-of-directors level"}]'::jsonb, 'A', 'The description states "Most often collaboration happens within fairly small teams - functional teams, time-limited project teams or cross-functional management teams."'),
  ('Collaboration with Emotional Intelligence', 6, 'What explicit prerequisite commitment does the course require of students, beyond watching the videos?', '[{"label": "A", "text": "A willingness to complete practical activities that involve reflective thinking, getting feedback, and discussing development with others"}, {"label": "B", "text": "No commitment beyond passive video viewing"}, {"label": "C", "text": "A requirement to have five years of management experience"}, {"label": "D", "text": "A requirement to already hold a psychology degree"}]'::jsonb, 'A', 'The description explicitly warns "you won''t get the best from the course unless you are prepared" to do reflective thinking, get feedback, and discuss development with others — not just watch videos.'),
  ('Collaboration with Emotional Intelligence', 7, 'A Principal Specialist is trying to improve collaboration across several teams but keeps hearing the same behavioural friction recur in every project kickoff. Per the course, what tool would help pinpoint the source of that recurring friction?', '[{"label": "A", "text": "A behavioural-style self-assessment, to understand each person''s preferred style and where it helps or hinders collaboration"}, {"label": "B", "text": "A single company-wide policy memo with no individual assessment"}, {"label": "C", "text": "Ignoring the pattern since the course says behavioural style has no bearing on collaboration"}, {"label": "D", "text": "Replacing the entire team rather than examining behavioural dynamics"}]'::jsonb, 'A', 'The course''s behavioural-styles questionnaire is designed exactly to surface how a person''s style helps or hinders their collaborative working, which is the root of this recurring friction.'),
  ('Collaboration with Emotional Intelligence', 8, 'A Principal Specialist wants to increase trust between two departments that collaborate only occasionally and somewhat warily. Which course topic most directly addresses building that trust?', '[{"label": "A", "text": "\"The Importance of Trust in Collaboration,\" a dedicated section of the course"}, {"label": "B", "text": "\"Review of the Course,\" which only summarizes prior content"}, {"label": "C", "text": "The course does not address trust at all"}, {"label": "D", "text": "\"More Resources,\" which lists supplementary links only"}]'::jsonb, 'A', 'This is a named section (8 lectures, 22 minutes) specifically covering how trust is built in collaborative relationships.'),
  ('Collaboration with Emotional Intelligence', 9, 'Why does the course pair emotional intelligence so closely with collaboration, rather than teaching collaboration as a purely structural/process topic?', '[{"label": "A", "text": "Because effective collaboration requires balancing emotional needs with clear thinking, building authentic relationships, and communicating with empathy at all levels of an organization"}, {"label": "B", "text": "Because emotional intelligence is described as entirely unrelated to how well teams collaborate"}, {"label": "C", "text": "Because the course claims structure and process are the only things that matter for collaboration"}, {"label": "D", "text": "Because emotional intelligence is presented as relevant only to customer-facing roles, not internal teamwork"}]'::jsonb, 'A', 'The description frames good emotional intelligence as what lets collaborators "balance emotional needs with their thinking, build authentic relationships and make good quality decisions," tying EI directly to collaboration quality.'),
  ('Collaboration with Emotional Intelligence', 10, 'What explicit caveat does the course give about who should NOT take it?', '[{"label": "A", "text": "It is not for people unwilling to work through the practical activities, since collaboration skill cannot be developed from watching video lectures alone"}, {"label": "B", "text": "It says no one should take the course unless they already have a doctorate"}, {"label": "C", "text": "It excludes anyone who has never managed a team before"}, {"label": "D", "text": "It excludes anyone working in a technical role"}]'::jsonb, 'A', 'The description states plainly "this course is NOT for you if you are not prepared to work through the practical activities... Collaboration cannot be developed just by watching the video lectures."'),
  ('Continuous Improvement / Operational Excellence', 1, 'What foundational disciplines does the course say Continuous Improvement/Operational Excellence is built on?', '[{"label": "A", "text": "Lean, six sigma, change management, project management, coaching, and engagement"}, {"label": "B", "text": "Only accounting principles"}, {"label": "C", "text": "Only marketing strategy"}, {"label": "D", "text": "Only legal compliance frameworks"}]'::jsonb, 'A', 'The description states Continuous Improvement "is built on the foundations of lean, six sigma, change management, project management, coaching and engagement."'),
  ('Continuous Improvement / Operational Excellence', 2, 'Which root cause analysis tools does the course specifically name?', '[{"label": "A", "text": "Fishbone/Ishikawa, interrelationship diagram, 5 Whys, and convergent/divergent thinking"}, {"label": "B", "text": "Only a single generic \"problem list\" with no named technique"}, {"label": "C", "text": "SWOT analysis exclusively"}, {"label": "D", "text": "A/B testing exclusively"}]'::jsonb, 'A', 'The description explicitly lists these specific tools under "Root cause analysis and associated tools."'),
  ('Continuous Improvement / Operational Excellence', 3, 'What does "Gemba" mean, in the context of this course?', '[{"label": "A", "text": "Go-see the work, i.e. observing the actual place where work happens"}, {"label": "B", "text": "A financial reporting term unrelated to process observation"}, {"label": "C", "text": "A synonym for a formal audit report"}, {"label": "D", "text": "A specific brand of software tool"}]'::jsonb, 'A', 'The course description explicitly defines "Gemba (go-see the work)" as one of its specific skills/tools covered.'),
  ('Continuous Improvement / Operational Excellence', 4, 'What is the "X matrix" used for, per the course?', '[{"label": "A", "text": "Strategy deployment/cascade, linking high-level goals to detailed strategies"}, {"label": "B", "text": "Calculating employee overtime pay"}, {"label": "C", "text": "Designing a company logo"}, {"label": "D", "text": "Scheduling shift rotations only"}]'::jsonb, 'A', 'The course lists "X matrix and vision tree" under strategy development/deployment/cascade, connecting top-level objectives to detailed strategy and execution.'),
  ('Continuous Improvement / Operational Excellence', 5, 'What does the course teach about "visual performance management"?', '[{"label": "A", "text": "Setting effective and visual performance measures so team performance against goals is more visible"}, {"label": "B", "text": "Avoiding any visible tracking of team performance"}, {"label": "C", "text": "Only tracking performance data privately with managers, never visibly to the team"}, {"label": "D", "text": "The course does not cover performance visualization"}]'::jsonb, 'A', 'The course''s learning objectives explicitly include "how to set effective and visual performance measures to make team performance to goals more visual."'),
  ('Continuous Improvement / Operational Excellence', 6, 'What does the course mean by "coaching upward"?', '[{"label": "A", "text": "Coaching your boss/line management chain to enable them to help your team drive performance improvement"}, {"label": "B", "text": "A junior employee formally evaluating a senior executive''s salary"}, {"label": "C", "text": "A one-way process where only managers coach subordinates, never the reverse"}, {"label": "D", "text": "The course does not use this term"}]'::jsonb, 'A', 'The course''s learning objectives explicitly state you''ll "learn how to ''coach upward'' to your boss/line management chain to enable them to help your team...drive performance improvement."'),
  ('Continuous Improvement / Operational Excellence', 7, 'A Specialist''s team keeps fixing the same recurring support issue with quick patches, never addressing why it keeps happening. Which specific tool from the course would help the team drill into the true underlying cause?', '[{"label": "A", "text": "The 5 Whys technique or a Fishbone/Ishikawa diagram, both named root cause analysis tools in the course"}, {"label": "B", "text": "A generic team morale survey, unrelated to root cause work"}, {"label": "C", "text": "A vision and mission statement rewrite, which the course frames as unrelated to root cause"}, {"label": "D", "text": "None of the course''s tools address recurring issues"}]'::jsonb, 'A', 'These are the specific data-driven root cause tools the course teaches for exactly this kind of recurring-symptom problem.'),
  ('Continuous Improvement / Operational Excellence', 8, 'A Specialist wants their team to see, at a glance, whether they are on pace against a weekly goal without waiting for a formal report. Which course concept applies?', '[{"label": "A", "text": "Visual performance management, using visible measures to make team performance against goals immediately clear"}, {"label": "B", "text": "The X matrix, which is unrelated to day-to-day visibility"}, {"label": "C", "text": "Coaching upward, which only applies to managing your boss"}, {"label": "D", "text": "None of the course''s concepts address real-time visibility"}]'::jsonb, 'A', 'Visual performance management is exactly the course''s named technique for making day-to-day progress against goals immediately visible to the team.'),
  ('Continuous Improvement / Operational Excellence', 9, 'Why does the course pair strategy deployment tools (like the X matrix and vision tree) with team-level root cause analysis, rather than treating strategy and problem-solving as unrelated?', '[{"label": "A", "text": "Because the course''s aim is to help every individual understand how their daily work connects to organizational strategy, with root cause tools ensuring that work removes real obstacles to those goals"}, {"label": "B", "text": "Because strategy and root cause analysis are described as entirely separate disciplines with no connection in the course"}, {"label": "C", "text": "Because only senior leaders are meant to engage with strategy tools, with root cause tools reserved for junior staff"}, {"label": "D", "text": "Because the X matrix replaces the need for any root cause analysis"}]'::jsonb, 'A', 'The course explicitly aims to help staff "understand how our day to day work contributes to the bigger picture," linking strategy cascade and ground-level problem solving as parts of one system.'),
  ('Continuous Improvement / Operational Excellence', 10, 'Per the course, what common organizational frustration does a lack of standard, documented procedures cause?', '[{"label": "A", "text": "People doing work in very different ways depending on personal preference, contributing to a chaotic, disorganized feel"}, {"label": "B", "text": "No frustration at all; the course says undocumented work is always preferable"}, {"label": "C", "text": "Excessive documentation with no practical downside"}, {"label": "D", "text": "The course does not address documentation of procedures"}]'::jsonb, 'A', 'The course lists "We do not have good documented standard procedures for our work" and "People do work in very different ways depending on their personal preference" among the common frustrations it targets.'),
  ('TED — Dan Pink: The puzzle of motivation', 1, 'What is the ''Candle Problem,'' and what does solving it require?', '[{"label": "A", "text": "Karl Duncker''s 1945 experiment requiring attaching a candle to a wall without dripping wax, solved by overcoming ''functional fixedness'' (seeing the thumbtack box as more than just a container)"}, {"label": "B", "text": "A modern coding challenge Pink created for the talk"}, {"label": "C", "text": "A problem that can only be solved with a financial incentive"}, {"label": "D", "text": "A purely physical strength test with no cognitive component"}]'::jsonb, 'A', 'This is the exact experiment and its cognitive twist as described in the talk.'),
  ('TED — Dan Pink: The puzzle of motivation', 2, 'What did Sam Glucksberg''s replication of the Candle Problem find about monetary incentives?', '[{"label": "A", "text": "They slowed problem-solving by 3.5 minutes on average — the opposite of conventional wisdom"}, {"label": "B", "text": "They sped up problem-solving significantly"}, {"label": "C", "text": "They had no measurable effect either way"}, {"label": "D", "text": "They only affected people who were told about the incentive in advance"}]'::jsonb, 'A', 'This is the specific, counterintuitive finding Pink cites.'),
  ('TED — Dan Pink: The puzzle of motivation', 3, 'According to Pink, for which type of task do "if-then" rewards actually work well?', '[{"label": "A", "text": "Tasks with a simple set of rules and a clear destination"}, {"label": "B", "text": "Creative, conceptual tasks requiring novel thinking"}, {"label": "C", "text": "All tasks, without exception"}, {"label": "D", "text": "No tasks at all — Pink argues rewards never help"}]'::jsonb, 'A', 'Pink is explicit that if-then rewards work for mechanical/simple tasks, but backfire for creative, conceptual work like the candle problem.'),
  ('TED — Dan Pink: The puzzle of motivation', 4, 'What are Pink''s three intrinsic motivators that he argues should replace carrot-and-stick approaches for creative work?', '[{"label": "A", "text": "Autonomy, Mastery, and Purpose"}, {"label": "B", "text": "Salary, Bonus, and Title"}, {"label": "C", "text": "Competition, Deadline pressure, and Public recognition"}, {"label": "D", "text": "Fear, Urgency, and Scarcity"}]'::jsonb, 'A', 'These are Pink''s three named intrinsic motivators.'),
  ('TED — Dan Pink: The puzzle of motivation', 5, 'Which example does Pink cite as evidence that intrinsic motivation can outperform incentivized, extrinsic-motivation projects for complex work?', '[{"label": "A", "text": "Wikipedia''s success over Microsoft''s incentivized Encarta"}, {"label": "B", "text": "A paid focus group that outperformed a volunteer group"}, {"label": "C", "text": "A sales team that only succeeded once bonuses were introduced"}, {"label": "D", "text": "A factory line that improved output only after piece-rate pay was introduced"}]'::jsonb, 'A', 'Pink uses this exact comparison as a landmark example of intrinsic motivation outperforming a well-funded, incentivized alternative.'),
  ('TED — Dan Pink: The puzzle of motivation', 6, 'A support team lead wants to boost creative problem-solving on ambiguous, novel tickets by offering a cash bonus per ticket closed quickly. What does Pink''s research suggest about this approach?', '[{"label": "A", "text": "It risks backfiring — monetary incentives tend to narrow focus and slow performance on tasks requiring creative, open-ended thinking"}, {"label": "B", "text": "It will reliably speed up creative problem-solving, per Glucksberg''s findings"}, {"label": "C", "text": "Pink''s research only applies to lab settings, never real workplaces"}, {"label": "D", "text": "This approach is guaranteed to have no effect either way"}]'::jsonb, 'A', 'This directly applies Pink''s central finding — extrinsic rewards can hinder rather than help on tasks that require flexible, creative thinking, which many ambiguous tickets do.'),
  ('TED — Dan Pink: The puzzle of motivation', 7, 'Which of Pink''s examples involves giving engineers a full day to work on anything they want, tied to the "Autonomy" motivator?', '[{"label": "A", "text": "Atlassian''s FedEx Days"}, {"label": "B", "text": "Google''s incentivized Encarta project"}, {"label": "C", "text": "The Candle Problem experiment itself"}, {"label": "D", "text": "The ROWE environment''s fixed 9-to-5 schedule"}]'::jsonb, 'A', 'Atlassian''s FedEx Days (alongside Google''s 20% time) are the examples Pink cites for autonomy-driven innovation.'),
  ('TED — Dan Pink: The puzzle of motivation', 8, 'What is a ROWE environment, as referenced in the talk, and which motivator does it primarily support?', '[{"label": "A", "text": "A results-only work environment (judging output, not hours/location) — supporting Autonomy"}, {"label": "B", "text": "A rewards-only work environment based purely on bonuses — supporting extrinsic motivation"}, {"label": "C", "text": "A rigid, fixed-schedule office environment — opposing Autonomy"}, {"label": "D", "text": "A rotating on-call work environment unrelated to motivation theory"}]'::jsonb, 'A', 'ROWE (Results-Only Work Environment) is cited as an example supporting the Autonomy motivator, letting people direct their own work.'),
  ('TED — Dan Pink: The puzzle of motivation', 9, 'A manager wants to apply Pink''s "Mastery" motivator to a support team. Which of these best fits that goal?', '[{"label": "A", "text": "Giving engineers time and support to deliberately improve at meaningful, challenging aspects of their work, not just hit quotas"}, {"label": "B", "text": "Offering a flat bonus for every ticket closed, regardless of complexity"}, {"label": "C", "text": "Removing all opportunities for skill growth to keep work simple"}, {"label": "D", "text": "Assigning only the easiest tickets so no one ever struggles"}]'::jsonb, 'A', 'Mastery, per Pink, is about the drive to improve at something that matters — not volume-based incentives or avoiding challenge.'),
  ('TED — Dan Pink: The puzzle of motivation', 10, 'Why does Pink open the talk with his own law school experience before presenting the research?', '[{"label": "A", "text": "To set up a personal, self-deprecating anecdote before making an evidence-based case for rethinking business motivation"}, {"label": "B", "text": "Because his law school performance is the main data source for his argument"}, {"label": "C", "text": "Because it directly proves the Candle Problem findings"}, {"label": "D", "text": "Because it has no connection to the rest of the talk"}]'::jsonb, 'A', 'This is simply Pink''s rhetorical opening, not a data point in the argument itself.'),
  ('Process Improvement with Automation: Certification', 1, 'What is the course''s central premise about the relationship between process improvement and automation?', '[{"label": "A", "text": "You should improve a process before automating it — map, simplify, and redesign the workflow first, then assess automation fit"}, {"label": "B", "text": "Automation should always come first, before any process mapping"}, {"label": "C", "text": "Process improvement and automation are described as entirely unrelated activities"}, {"label": "D", "text": "Automating a broken process is described as the recommended default approach"}]'::jsonb, 'A', 'The course''s own subtitle states "Improve before automating: map, simplify and redesign workflows, assess automation fit and control the solution."'),
  ('Process Improvement with Automation: Certification', 2, 'What does the course teach about mapping "as-is" versus "to-be" processes?', '[{"label": "A", "text": "How to map both the current (\"as-is\") process in full and the desired future (\"to-be\") process in full"}, {"label": "B", "text": "Only the future state is ever mapped; the current state is skipped"}, {"label": "C", "text": "Only the current state is mapped; future state design is not covered"}, {"label": "D", "text": "The course does not distinguish between current and future state maps"}]'::jsonb, 'A', 'The course''s learning objectives explicitly list "How to map as-is processes in full" and "How to map to-be processes in full" as separate, named skills.'),
  ('Process Improvement with Automation: Certification', 3, 'What collaborative technique does the course teach for finding the right automation solution?', '[{"label": "A", "text": "Ideating with a team in a workshop format"}, {"label": "B", "text": "A single individual making the decision alone with no team input"}, {"label": "C", "text": "An anonymous online poll with no discussion"}, {"label": "D", "text": "The course does not cover solution ideation"}]'::jsonb, 'A', 'The course''s learning objectives explicitly state "How to ideate with a team in a workshop for the right solutions."'),
  ('Process Improvement with Automation: Certification', 4, 'What does the course mean by setting "guiding design principles" for a process?', '[{"label": "A", "text": "Identifying and setting principles up front that guide how the redesigned process should be shaped"}, {"label": "B", "text": "A legal compliance checklist unrelated to process design"}, {"label": "C", "text": "A financial budget line item"}, {"label": "D", "text": "The course does not address design principles"}]'::jsonb, 'A', 'The course''s learning objectives list "How to identify and set guiding design principles for your process" as a specific skill.'),
  ('Process Improvement with Automation: Certification', 5, 'How does the course structure its teaching of this material?', '[{"label": "A", "text": "Through a realistic scenario (the largest section, 20 lectures/2hr) that walks through the end-to-end deployment of automation via process improvement"}, {"label": "B", "text": "Through unrelated case studies from a different industry with no scenario continuity"}, {"label": "C", "text": "Through a single lecture with no worked example"}, {"label": "D", "text": "Through a purely theoretical, example-free approach"}]'::jsonb, 'A', 'The course content shows "Scenario" as by far the largest section (20 of 33 lectures), used to build a real-life example of the end-to-end approach.'),
  ('Process Improvement with Automation: Certification', 6, 'What does the course cover regarding the deployment phase of an automated process?', '[{"label": "A", "text": "The deployment activities involved when deploying an automated process"}, {"label": "B", "text": "Only pre-deployment planning, with no coverage of the deployment itself"}, {"label": "C", "text": "Deployment is explicitly described as out of scope"}, {"label": "D", "text": "Only post-deployment reporting, skipping deployment activities entirely"}]'::jsonb, 'A', 'The course''s learning objectives explicitly list "The deployment activities when deploying an automated process" as covered content.'),
  ('Process Improvement with Automation: Certification', 7, 'A Senior Specialist is asked to automate an escalation workflow that is currently inconsistent and poorly understood across teams. Per this course''s central premise, what should happen before any automation tooling is selected?', '[{"label": "A", "text": "Map the as-is process in full and simplify/redesign it, since the course teaches improving a process before automating it"}, {"label": "B", "text": "Select and configure automation software immediately, since mapping is described as unnecessary"}, {"label": "C", "text": "Automate the process exactly as it currently runs, inconsistencies included"}, {"label": "D", "text": "Skip directly to writing deployment documentation with no prior process work"}]'::jsonb, 'A', 'This is precisely the course''s stated approach: "Improve before automating" by mapping and redesigning the workflow first, rather than automating a flawed process as-is.'),
  ('Process Improvement with Automation: Certification', 8, 'A Senior Specialist has redesigned a workflow and now needs buy-in from stakeholders on which parts to automate and how. Which technique from the course would help facilitate that decision collaboratively rather than unilaterally?', '[{"label": "A", "text": "Running a team ideation workshop to identify the right solutions together"}, {"label": "B", "text": "Making the automation-scope decision alone with no stakeholder involvement"}, {"label": "C", "text": "Delaying the decision indefinitely, since the course says group input is discouraged"}, {"label": "D", "text": "Outsourcing the decision entirely to an external vendor with no internal input"}]'::jsonb, 'A', 'Team workshop ideation is the course''s named technique for collaboratively identifying the right automation solutions.'),
  ('Process Improvement with Automation: Certification', 9, 'Why does the course emphasize setting "guiding design principles" before diving into the to-be process map, rather than jumping straight to redesign?', '[{"label": "A", "text": "Because principles set upfront (e.g. around consistency, simplicity, or control) give the team a shared standard to design the to-be process against, rather than redesigning ad hoc"}, {"label": "B", "text": "Because guiding principles are described as purely decorative with no bearing on the redesign"}, {"label": "C", "text": "Because the course says principles should only be set after the process is already automated"}, {"label": "D", "text": "Because setting principles is presented as optional busywork with no effect on outcomes"}]'::jsonb, 'A', 'Setting guiding design principles before mapping the to-be state is the course''s method for keeping the redesign coherent and intentional rather than ad hoc.'),
  ('Process Improvement with Automation: Certification', 10, 'Who does the course explicitly target as its audience?', '[{"label": "A", "text": "RPA and automation project managers, business/process analysts supporting automation work, operational leaders preparing processes for automation, and team members contributing requirements or controls"}, {"label": "B", "text": "Only professional software developers writing RPA scripts"}, {"label": "C", "text": "Only company founders and CEOs"}, {"label": "D", "text": "Only external compliance auditors"}]'::jsonb, 'A', 'The "Who this course is for" section lists exactly these four groups as the intended audience.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 1, 'What does DMAIC stand for, and how many structured steps does the course use to teach its five phases?', '[{"label": "A", "text": "Define, Measure, Analyse, Improve, and Control — taught across 15 structured steps within those 5 phases"}, {"label": "B", "text": "Design, Model, Assess, Iterate, Close — an entirely different acronym"}, {"label": "C", "text": "The course does not use a phase-based structure"}, {"label": "D", "text": "Define, Measure, Analyse, Improve, Control — taught in a single unstructured step"}]'::jsonb, 'A', 'The description states DMAIC''s 5 phases are taught "in 15 structured steps," explained across more than 78 sections.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 2, 'What statistical software does this course teach hands-on, alongside Six Sigma concepts?', '[{"label": "A", "text": "Minitab"}, {"label": "B", "text": "Microsoft Excel exclusively, with no dedicated statistical package"}, {"label": "C", "text": "Tableau"}, {"label": "D", "text": "SPSS"}]'::jsonb, 'A', 'The course title itself and its content repeatedly emphasize "expertise on Minitab," including Hypothesis Testing exercises on the platform.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 3, 'What is a Lean Six Sigma Green Belt project "storyboard," per the course?', '[{"label": "A", "text": "A structured way of documenting a Green Belt improvement project, which the course teaches how to create"}, {"label": "B", "text": "A marketing slide deck unrelated to process improvement"}, {"label": "C", "text": "A tool used only for onboarding new hires"}, {"label": "D", "text": "The course does not mention storyboards"}]'::jsonb, 'A', 'The course lists "Master the art of creating Lean Six Sigma Green Belt Project Storyboard" as one of its "What you''ll learn" items.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 4, 'What accreditations back this course''s certification, per its description?', '[{"label": "A", "text": "It is an Authorized Training Partner of PMI, CPD-accredited, and recognized by SHRM as a \"Provider of Choice\""}, {"label": "B", "text": "It carries no accreditation of any kind"}, {"label": "C", "text": "It is only accredited by a single obscure regional body with no international recognition"}, {"label": "D", "text": "It is accredited solely as a university degree program"}]'::jsonb, 'A', 'The description explicitly states AIGPE is a PMI Authorized Training Partner, CPD Accredited, and recognized as a "Provider of Choice" by SHRM.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 5, 'What prerequisite does the course assume before starting the Green Belt content?', '[{"label": "A", "text": "Completion of Six Sigma Yellow Belt Certification and a basic level of statistical knowledge"}, {"label": "B", "text": "A completed university degree in statistics"}, {"label": "C", "text": "No prior knowledge or certification of any kind"}, {"label": "D", "text": "Prior completion of the Black Belt certification"}]'::jsonb, 'A', 'The requirements state "You should have completed Yellow Belt Certification" and assume "a basic level of statistical knowledge."'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 6, 'What real-world cost-savings examples does the course cite to illustrate the value of Six Sigma?', '[{"label": "A", "text": "Motorola saved $16 billion (1986-2001) and General Electric saved $4.4 billion (1996-1999) using Six Sigma"}, {"label": "B", "text": "The course cites no real-world savings examples"}, {"label": "C", "text": "Only a single small local business example with no scale"}, {"label": "D", "text": "Examples exclusively from non-profit organizations"}]'::jsonb, 'A', 'The description explicitly cites these two named examples and dollar figures as evidence of Six Sigma''s financial impact.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 7, 'A Principal Specialist wants to formally scope and charter a major process-improvement initiative for the support org, with a clear problem statement, metrics, and root-cause plan before touching a fix. Which DMAIC phase does this correspond to?', '[{"label": "A", "text": "Define — the first DMAIC phase, focused on framing the project before measurement or analysis begins"}, {"label": "B", "text": "Control — the final phase, focused on sustaining a solution already implemented"}, {"label": "C", "text": "Improve — which the course places before any problem is defined"}, {"label": "D", "text": "DMAIC has no phase dedicated to project framing"}]'::jsonb, 'A', 'Define is the first of the five DMAIC phases, exactly matching the scoping/chartering activity described in the scenario.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 8, 'A Principal Specialist has implemented a fix and now wants to make sure the gains stick rather than reverting to the old pattern within a few months. Which DMAIC phase and course concept applies?', '[{"label": "A", "text": "Control — the final DMAIC phase, focused on monitoring the process to ensure gains are sustained"}, {"label": "B", "text": "Measure — which only establishes a baseline and is unrelated to sustaining a fix"}, {"label": "C", "text": "Analyse — which focuses on root-cause discovery, not sustaining outcomes"}, {"label": "D", "text": "The course provides no mechanism for sustaining improvements over time"}]'::jsonb, 'A', 'Control is DMAIC''s final phase, explicitly aimed at monitoring processes to ensure little or no deviation from the improved mean over time.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 9, 'Why might a Principal Specialist value the Minitab component of this course specifically, compared to a Six Sigma course that only covers concepts qualitatively?', '[{"label": "A", "text": "Because it enables rigorous, data-driven validation of process changes (e.g. hypothesis testing) rather than relying on qualitative judgment alone"}, {"label": "B", "text": "Because Minitab is described as purely a presentation tool with no statistical function"}, {"label": "C", "text": "Because the course says statistical validation is unnecessary for Six Sigma projects"}, {"label": "D", "text": "Because Minitab exercises are optional filler unrelated to the DMAIC phases"}]'::jsonb, 'A', 'The course''s Minitab-based hypothesis testing and graphical/statistical exercises are what let a Green Belt practitioner rigorously validate whether a process change actually worked, beyond qualitative judgment.'),
  ('Six Sigma: Certified Lean Six Sigma Green Belt (Accredited)', 10, 'Which industries does the course say it is specifically suited for?', '[{"label": "A", "text": "Transaction Processing, Back-office, BPO, KPO, Call Center Operations, Voice Operations, and other repeatable service-industry work"}, {"label": "B", "text": "Only heavy manufacturing, explicitly excluding services"}, {"label": "C", "text": "Only agriculture"}, {"label": "D", "text": "The course claims to be equally suited to literally every industry with no distinction"}]'::jsonb, 'A', 'The description explicitly scopes the course to "Transaction Processing, Back-office, Business Process Outsourcing (BPO), Knowledge Process Outsourcing (KPO)...Service Industry," and says it "may not be for those who are from non-service industries."'),
  ('TED — Linda Hill: How to manage for collective creativity', 1, 'What is the scope of the research behind this talk?', '[{"label": "A", "text": "A decade-long ethnographic study of 16 exceptional innovation leaders across 7 countries and 12 industries"}, {"label": "B", "text": "A one-year survey of a single company"}, {"label": "C", "text": "A purely theoretical framework with no empirical study"}, {"label": "D", "text": "A study of exactly one innovation leader over 30 years"}]'::jsonb, 'A', 'This is the exact scope of Hill''s underlying research.'),
  ('TED — Linda Hill: How to manage for collective creativity', 2, 'How does Hill define innovation in this talk?', '[{"label": "A", "text": "Anything that is both new and useful — products, services, processes, or organizational structures"}, {"label": "B", "text": "Only brand-new products that have never existed in any form"}, {"label": "C", "text": "Only process improvements, excluding products or services"}, {"label": "D", "text": "Any change at all, regardless of usefulness"}]'::jsonb, 'A', 'This is Hill''s own definition, given explicitly in the talk.'),
  ('TED — Linda Hill: How to manage for collective creativity', 3, 'What are the three capabilities Hill says innovative organizations share?', '[{"label": "A", "text": "Creative Abrasion, Creative Agility, and Creative Resolution"}, {"label": "B", "text": "Speed, Scale, and Secrecy"}, {"label": "C", "text": "Hierarchy, Consensus, and Compliance"}, {"label": "D", "text": "Budget, Headcount, and Deadline pressure"}]'::jsonb, 'A', 'These are Hill''s three named capabilities.'),
  ('TED — Linda Hill: How to manage for collective creativity', 4, 'What does "Creative Abrasion" mean in Hill''s framework?', '[{"label": "A", "text": "Creating a marketplace of ideas through debate — amplifying differences rather than minimizing them"}, {"label": "B", "text": "Avoiding all disagreement to keep the team comfortable"}, {"label": "C", "text": "Assigning one person to make every decision unilaterally"}, {"label": "D", "text": "Reducing the number of viewpoints involved in any decision"}]'::jsonb, 'A', 'This is Hill''s exact definition of Creative Abrasion — a marketplace of ideas via constructive debate.'),
  ('TED — Linda Hill: How to manage for collective creativity', 5, 'What does "Creative Resolution" mean, as distinct from simple compromise?', '[{"label": "A", "text": "Integrated decision-making that combines opposing ideas into a novel solution, rather than compromising or letting one person dominate"}, {"label": "B", "text": "Averaging every proposed idea into a middle-ground solution"}, {"label": "C", "text": "Letting the most senior person in the room make the final call"}, {"label": "D", "text": "Avoiding any decision until full consensus is reached"}]'::jsonb, 'A', 'Hill explicitly distinguishes this integrative approach from simple compromise or top-down decision-making.'),
  ('TED — Linda Hill: How to manage for collective creativity', 6, 'In the Google Infrastructure Group example under Bill Coughran, how did "Creative Agility" show up in practice?', '[{"label": "A", "text": "Two competing teams (Big Table and Build It From Scratch) worked in parallel, testing prototypes against reality before converging on the best solution"}, {"label": "B", "text": "A single team worked in isolation with no prototyping at all"}, {"label": "C", "text": "Leadership picked a solution before any prototypes were built"}, {"label": "D", "text": "The two teams merged immediately without ever testing separately"}]'::jsonb, 'A', 'This is the specific example Hill gives of discovery-driven learning/experimentation (Creative Agility) in action.'),
  ('TED — Linda Hill: How to manage for collective creativity', 7, 'How did Vineet Nayar''s approach at HCL Technologies reflect Hill''s reframing of leadership?', '[{"label": "A", "text": "He inverted the organizational hierarchy, positioning frontline employees as a source of innovation rather than only receiving top-down direction"}, {"label": "B", "text": "He centralized all decision-making in a small executive team"}, {"label": "C", "text": "He eliminated frontline employee input from all innovation efforts"}, {"label": "D", "text": "He introduced strict, fixed procedures with no room for employee-driven ideas"}]'::jsonb, 'A', 'This is exactly the leadership inversion Hill highlights in the HCL example.'),
  ('TED — Linda Hill: How to manage for collective creativity', 8, 'A team lead wants to apply "Creative Abrasion" without letting debates become personal or destructive. What does Hill''s framing suggest is the key distinction to maintain?', '[{"label": "A", "text": "Debate should be \"heated but constructive\" — amplifying differing ideas in service of better solutions, not personal conflict"}, {"label": "B", "text": "All disagreement should be suppressed to avoid any tension whatsoever"}, {"label": "C", "text": "Debates should only ever be resolved by majority vote with no further discussion"}, {"label": "D", "text": "Creative Abrasion requires removing anyone who disagrees from the team"}]'::jsonb, 'A', 'Hill''s own phrase — "heated but constructive arguments" — captures this exact distinction between productive and destructive conflict.'),
  ('TED — Linda Hill: How to manage for collective creativity', 9, 'Why does Hill argue that "conventional leadership approaches" fail when fostering innovation?', '[{"label": "A", "text": "Because innovation is a collective, emergent process, not something achieved through solo genius or unilateral top-down direction"}, {"label": "B", "text": "Because innovation always occurs completely spontaneously with zero leadership involved at all"}, {"label": "C", "text": "Because conventional leadership approaches are actually optimal for innovation, per Hill"}, {"label": "D", "text": "Because only technical leaders, never business leaders, can foster innovation"}]'::jsonb, 'A', 'Hill''s core thesis is that innovation emerges through collective effort, which conventional command-and-control leadership models are not built to cultivate.'),
  ('TED — Linda Hill: How to manage for collective creativity', 10, 'How does Hill describe the role of an effective innovation leader, using her own term?', '[{"label": "A", "text": "As a \"social architect\" who creates space for the group''s combined ideas, rather than as a singular visionary"}, {"label": "B", "text": "As a \"chief visionary\" who single-handedly decides the direction for the group"}, {"label": "C", "text": "As a strict enforcer whose main role is discipline and compliance"}, {"label": "D", "text": "As someone who should avoid ever hiring people who disagree with them"}]'::jsonb, 'A', 'Hill explicitly uses the term "social architect" to reframe the innovation leader''s role away from top-down visionary and toward space-creator for collective genius.'),
  ('Innovation Master Class', 1, 'What framework does the course teach for understanding the innovation process?', '[{"label": "A", "text": "Five Immutable Laws of innovation"}, {"label": "B", "text": "A single unnamed rule with no structured framework"}, {"label": "C", "text": "Ten Commandments of innovation"}, {"label": "D", "text": "The course provides no structured framework at all"}]'::jsonb, 'A', 'The course content lists "The Process of Innovation and its Five Immutable Laws" as a dedicated section.'),
  ('Innovation Master Class', 2, 'What does the course mean by an "Innovation Zone"?', '[{"label": "A", "text": "A structural/organizational space built to support and enable innovation, covered in a dedicated section on building one"}, {"label": "B", "text": "A specific physical office location with no organizational meaning"}, {"label": "C", "text": "A synonym for the R&D department''s budget line"}, {"label": "D", "text": "The course does not use this term"}]'::jsonb, 'A', '"Building an Innovation Zone" is a named course section, and the instructor has authored a book titled "The Innovation Zone."'),
  ('Innovation Master Class', 3, 'How many "lessons of innovation" does the course draw from the world''s best innovators?', '[{"label": "A", "text": "Seven"}, {"label": "B", "text": "Two"}, {"label": "C", "text": "Twenty"}, {"label": "D", "text": "The course does not identify a specific number of lessons"}]'::jsonb, 'A', 'The course explicitly lists "The Seven Lessons of Innovation" as both a learning objective and its largest section (14 lectures, 1hr 9min).'),
  ('Innovation Master Class', 4, 'What organizations does the course use as innovation case studies?', '[{"label": "A", "text": "Apple, Sony, GM, Boston Beer Company, Kodak, NASA, 3M, iRobot, and others"}, {"label": "B", "text": "Only a single fictional company invented for the course"}, {"label": "C", "text": "Exclusively non-profit organizations"}, {"label": "D", "text": "The course uses no real-world case studies"}]'::jsonb, 'A', 'The description lists these named organizations explicitly as "numerous real world case studies of companies who are great innovators."'),
  ('Innovation Master Class', 5, 'What does the course teach about incentivizing innovation?', '[{"label": "A", "text": "The pitfalls and correct ways to incentivize innovation"}, {"label": "B", "text": "That innovation should never be incentivized under any circumstances"}, {"label": "C", "text": "Only that financial bonuses are the sole correct incentive"}, {"label": "D", "text": "The course does not address incentives at all"}]'::jsonb, 'A', 'The course''s "What you''ll learn" section explicitly lists "The pitfalls and correct ways to incentivize innovation."'),
  ('Innovation Master Class', 6, 'What does the course teach about assessing an organization''s readiness for innovation?', '[{"label": "A", "text": "How to determine your organization''s propensity for innovation and assess its innovation capability"}, {"label": "B", "text": "The course assumes every organization is equally ready and skips assessment"}, {"label": "C", "text": "Only external consultants can perform this assessment, per the course"}, {"label": "D", "text": "This topic is not covered"}]'::jsonb, 'A', 'The course explicitly lists "How to determine your organization''s propensity for innovation" and "How To...Assess your organization''s innovation capability" among its learning objectives.'),
  ('Innovation Master Class', 7, 'A Specialist wants to measure whether a new internal innovation initiative is actually delivering value, not just generating activity. Which part of the course addresses this directly?', '[{"label": "A", "text": "\"Measuring the Impact and Value of Innovation,\" a dedicated course section"}, {"label": "B", "text": "\"The Global Context and The Imperative for Innovation,\" which only covers context, not measurement"}, {"label": "C", "text": "The course does not address measuring innovation''s impact"}, {"label": "D", "text": "Only the wrap-up/certification section, which has no measurement content"}]'::jsonb, 'A', 'This is a named section of the course specifically covering how to measure innovation''s impact and value, matching the scenario directly.'),
  ('Innovation Master Class', 8, 'A Specialist notices their organization talks about innovation but rewards only safe, incremental work and punishes failed experiments. Which course topic diagnoses this kind of mismatch?', '[{"label": "A", "text": "The pitfalls of incentivizing innovation, since misaligned rewards/behaviors are exactly what the course frames as a common failure mode"}, {"label": "B", "text": "Only the case studies section, which has no framework for diagnosing incentive problems"}, {"label": "C", "text": "The course claims incentive structures never affect innovation outcomes"}, {"label": "D", "text": "Only the \"Global Context\" section, unrelated to internal incentive design"}]'::jsonb, 'A', 'The course''s stated coverage of "pitfalls and correct ways to incentivize innovation" directly targets this kind of reward/behavior mismatch.'),
  ('Innovation Master Class', 9, 'Why does the course pair leadership and organizational structure ("How Leadership and Structure Support an Innovation Zone") with the Seven Lessons of Innovation, rather than treating culture and case-study lessons as separate topics?', '[{"label": "A", "text": "Because sustained innovation depends on both the right supporting structure/leadership and applying proven lessons from real innovators — neither alone is described as sufficient"}, {"label": "B", "text": "Because leadership and structure are described as irrelevant to whether lessons from other companies can be applied"}, {"label": "C", "text": "Because the course claims only leadership matters, with case-study lessons being purely optional trivia"}, {"label": "D", "text": "Because the Seven Lessons are described as applicable only to already-perfect organizational structures"}]'::jsonb, 'A', 'The course builds sequentially from the Innovation Zone and leadership/structure content into the Seven Lessons, implying both structural support and applied lessons are needed together.'),
  ('Innovation Master Class', 10, 'Per a student review, what is a noted weakness of this course relative to its length?', '[{"label": "A", "text": "One reviewer felt the content \"could have been summarized in less sections and videos\" due to some repetition"}, {"label": "B", "text": "All reviews unanimously report zero repetition of any kind"}, {"label": "C", "text": "The course has been removed from the platform entirely"}, {"label": "D", "text": "Reviewers uniformly say the course is too short to be useful"}]'::jsonb, 'A', 'A visible review states the content "is too generic and could have been summarized in less sections and videos," which is useful context for a Specialist weighing how to pace the material.'),
  ('Building a Culture of Innovation', 1, 'What statistic does the course cite about the failure rate of change initiatives?', '[{"label": "A", "text": "70% of change initiatives fail"}, {"label": "B", "text": "Only 5% of change initiatives fail"}, {"label": "C", "text": "The course claims all change initiatives succeed"}, {"label": "D", "text": "The course cites no failure-rate statistic"}]'::jsonb, 'A', 'The description opens by asking "Did you know that 70% of change initiatives fail?"'),
  ('Building a Culture of Innovation', 2, 'Which change management theory does the course explicitly teach?', '[{"label": "A", "text": "Kurt Lewin''s Planned Change"}, {"label": "B", "text": "Only a proprietary, unnamed model with no theoretical grounding"}, {"label": "C", "text": "Six Sigma DMAIC exclusively"}, {"label": "D", "text": "The course does not name any specific change theory"}]'::jsonb, 'A', 'The description explicitly names "transformative theories, from Kurt Lewin''s Planned Change to...human-centered design principles championed by...IDEO."'),
  ('Building a Culture of Innovation', 3, 'Which named company is used as a cautionary tale of failing to innovate?', '[{"label": "A", "text": "Blockbuster"}, {"label": "B", "text": "Apple"}, {"label": "C", "text": "Netflix"}, {"label": "D", "text": "IDEO"}]'::jsonb, 'A', 'The description explicitly names Blockbuster as a "cautionary tale," contrasted with Netflix and Facebook as companies that navigated innovation successfully.'),
  ('Building a Culture of Innovation', 4, 'What percentage of executives does the course say acknowledge the pivotal role of innovation, despite many organizations still struggling to innovate effectively?', '[{"label": "A", "text": "84%"}, {"label": "B", "text": "10%"}, {"label": "C", "text": "50%"}, {"label": "D", "text": "The course cites no such statistic"}]'::jsonb, 'A', 'The description states "despite 84% of executives acknowledging the pivotal role of innovation, many organizations still struggle to innovate effectively."'),
  ('Building a Culture of Innovation', 5, 'What learning framework does the course reference in connection with building teams that embrace innovation?', '[{"label": "A", "text": "Kolb''s Learning Styles"}, {"label": "B", "text": "Maslow''s Hierarchy of Needs"}, {"label": "C", "text": "Bloom''s Taxonomy"}, {"label": "D", "text": "The course does not reference any learning framework"}]'::jsonb, 'A', 'The description explicitly states the course draws on "techniques inspired by Kolb''s Learning Styles" for building teams that excel at innovation.'),
  ('Building a Culture of Innovation', 6, 'What does the course say about a Nobel Prize winner''s approach to failure?', '[{"label": "A", "text": "It references a Nobel Prize winner''s annual review of failure as a harbinger of innovation"}, {"label": "B", "text": "It claims Nobel Prize winners never experience failure"}, {"label": "C", "text": "The course does not mention any Nobel Prize winner"}, {"label": "D", "text": "It frames failure review as irrelevant to innovation"}]'::jsonb, 'A', 'The description explicitly mentions "the wisdom of a Nobel Prize winner''s annual review of failure as a harbinger of innovation."'),
  ('Building a Culture of Innovation', 7, 'A Senior Specialist wants to challenge an entrenched "we''ve always done it that way" attitude on their team before it makes the team''s processes obsolete. Which course theme most directly supports that effort?', '[{"label": "A", "text": "Cultivating curiosity and leading change per models like Lewin''s Planned Change, which the course frames as the antidote to unchallenged legacy thinking"}, {"label": "B", "text": "Ignoring the attitude, since the course says legacy thinking always resolves itself over time"}, {"label": "C", "text": "Immediately replacing the entire team, which the course does not recommend"}, {"label": "D", "text": "Ignoring the attitude, since the course frames it as harmless"}]'::jsonb, 'A', 'The course explicitly frames unchallenged "we''ve always done it that way" thinking as a business risk, and offers curiosity and change-leadership theory as the corrective.'),
  ('Building a Culture of Innovation', 8, 'A Senior Specialist is worried that proposing a bold process change will be read as criticizing how things currently work, and expects resistance. Per the course''s framing of Netflix vs. Blockbuster, what''s the risk of avoiding the conversation?', '[{"label": "A", "text": "Avoiding change out of fear of resistance is exactly the pattern the course associates with Blockbuster''s decline, versus companies that navigated change successfully"}, {"label": "B", "text": "The course says avoiding change always protects an organization from risk"}, {"label": "C", "text": "The Blockbuster/Netflix contrast is described as unrelated to internal process change"}, {"label": "D", "text": "The course recommends avoiding all proposals that might cause internal friction"}]'::jsonb, 'A', 'The course explicitly uses Blockbuster as a cautionary tale of failing to adapt, in contrast to companies like Netflix that embraced necessary change.'),
  ('Building a Culture of Innovation', 9, 'Why does the course pair human-centered design (IDEO-style) principles with change management theory, rather than teaching them as separate topics?', '[{"label": "A", "text": "Because effectively integrating human-centered design into leadership requires understanding how people experience and react to change, which change theories like Lewin''s explain"}, {"label": "B", "text": "Because human-centered design is described as having nothing to do with organizational change"}, {"label": "C", "text": "Because the course claims design thinking replaces the need for any change management approach"}, {"label": "D", "text": "Because change theory is presented as applicable only to marketing, not internal team leadership"}]'::jsonb, 'A', 'The course explicitly combines "leading change" theory with "human-centered design principles" as complementary tools for a leader driving innovation.'),
  ('Building a Culture of Innovation', 10, 'Who is this course primarily designed for, per its own framing?', '[{"label": "A", "text": "Mid to high-level managers who want to change team/organizational culture toward one where innovation becomes the norm, despite limited time"}, {"label": "B", "text": "Entry-level individual contributors with no team leadership responsibility"}, {"label": "C", "text": "External investors evaluating a company from the outside"}, {"label": "D", "text": "Only HR specialists with no product or engineering involvement"}]'::jsonb, 'A', 'The "Who this course is for" section explicitly targets "Mid to high-level manager who wants to change the culture of the organization and/or team," while noting their time constraints.'),
  ('Systems Innovation', 1, 'What does the course define systems innovation as?', '[{"label": "A", "text": "A new systems-based approach to enabling change within complex organizations, working with the evolutionary potential of complex adaptive systems"}, {"label": "B", "text": "A synonym for buying new IT hardware"}, {"label": "C", "text": "A purely financial cost-cutting technique"}, {"label": "D", "text": "A one-time training exercise with no ongoing organizational application"}]'::jsonb, 'A', 'The description explicitly defines it: "Systems innovation is a new systems-based approach to enabling change within complex organizations... working with the innate evolutionary potential of complex adaptive systems."'),
  ('Systems Innovation', 2, 'What are "wicked problems," per the course?', '[{"label": "A", "text": "Complex, interconnected, and highly dynamic challenges that traditional centralized, long-term-planning approaches struggle to solve"}, {"label": "B", "text": "Simple, easily solvable issues with a single clear-cut fix"}, {"label": "C", "text": "A term unrelated to organizational or societal challenges"}, {"label": "D", "text": "Problems that only occur in manufacturing settings"}]'::jsonb, 'A', '"Wicked Problems" is a named lecture in the course, and the description frames today''s challenges as "incredibly dynamic and complex" and poorly served by traditional bureaucratic planning.'),
  ('Systems Innovation', 3, 'Which systems thinkers does the course draw upon?', '[{"label": "A", "text": "Donella Meadows and Russell Ackoff"}, {"label": "B", "text": "Only fictional, invented theorists with no real academic grounding"}, {"label": "C", "text": "Only marketing strategists with no systems-thinking background"}, {"label": "D", "text": "The course cites no named thinkers"}]'::jsonb, 'A', 'The description explicitly states the course "draws upon the work of prominent systems thinkers such as Donella Meadows and Russell Ackoff."'),
  ('Systems Innovation', 4, 'What does the course say about traditional, centralized approaches to today''s complex challenges?', '[{"label": "A", "text": "They are failing to gain traction, since these problems are dynamic and complex while traditional responses rely on fixed, long-term projections"}, {"label": "B", "text": "They are described as perfectly suited to every modern challenge"}, {"label": "C", "text": "The course claims centralized planning has never been tried before"}, {"label": "D", "text": "The course says traditional approaches are irrelevant to the discussion"}]'::jsonb, 'A', 'The description states "a failure to gain traction on even one of the global challenges today is a testimony to a failing set of approaches" built on fixed, centralized, long-term planning.'),
  ('Systems Innovation', 5, 'What four course sections make up the curriculum?', '[{"label": "A", "text": "Overview, Systems Thinking, Systems Analysis, and Digital Transformation"}, {"label": "B", "text": "Only a single unbroken 3-hour video"}, {"label": "C", "text": "Marketing, Sales, Finance, and Legal"}, {"label": "D", "text": "Onboarding, Compliance, Payroll, and Benefits"}]'::jsonb, 'A', 'The course content lists exactly these four sections: Overview, Systems Thinking, Systems Analysis, Digital Transformation.'),
  ('Systems Innovation', 6, 'What approach does the course say complex, dynamic systems demand, instead of traditional centralized planning?', '[{"label": "A", "text": "A more holistic, networked, emergent, and evolutionary approach"}, {"label": "B", "text": "An even more rigid, centralized, top-down control structure"}, {"label": "C", "text": "No structured approach at all; the course argues these problems are unsolvable"}, {"label": "D", "text": "A purely financial, budget-only approach"}]'::jsonb, 'A', 'The description states these systems "demand a more holistic, networked, emergent and evolutionary approach," building on complexity theory.'),
  ('Systems Innovation', 7, 'A Principal Specialist is asked to fix a recurring cross-departmental support-escalation failure that keeps reappearing despite several isolated departmental fixes. Per this course''s framing, what is likely wrong with the isolated-fix approach?', '[{"label": "A", "text": "It treats a systemic, interconnected problem as if it were a simple, isolated one, rather than addressing its underlying dynamics and root causes holistically"}, {"label": "B", "text": "Isolated departmental fixes are described in the course as always the correct approach for any recurring issue"}, {"label": "C", "text": "The course claims recurring cross-departmental issues cannot exist in practice"}, {"label": "D", "text": "The course says only marketing teams experience this kind of recurring problem"}]'::jsonb, 'A', 'Systems innovation''s whole premise is that complex, interconnected problems need a holistic approach addressing underlying dynamics, not a series of isolated departmental patches.'),
  ('Systems Innovation', 8, 'A Principal Specialist wants to justify why a long-term, five-year fixed roadmap for support tooling might be the wrong planning approach in a fast-changing environment. Which course argument supports that instinct?', '[{"label": "A", "text": "The course''s critique of traditional centralized planning \"based upon fixed future projections,\" which struggles against dynamic, evolving systems"}, {"label": "B", "text": "The course argues fixed five-year roadmaps are always superior to adaptive planning"}, {"label": "C", "text": "The course does not address planning horizons at all"}, {"label": "D", "text": "The course claims dynamic systems do not exist in real organizations"}]'::jsonb, 'A', 'The description explicitly critiques traditional approaches for relying on "long-term planning based upon fixed future projections" against systems that are "continuously recreated through...ongoing choices, actions, and interactions."'),
  ('Systems Innovation', 9, 'Why does the course pair "Systems Thinking" and "Systems Analysis" as separate but connected sections, rather than a single combined topic?', '[{"label": "A", "text": "Because thinking in systems (concepts/mental models) and analyzing systems (methods/techniques) are related but distinct skills needed to actually apply systems innovation"}, {"label": "B", "text": "Because Systems Thinking and Systems Analysis are described as unrelated, competing methodologies"}, {"label": "C", "text": "Because only one of the two sections is relevant to any real organizational problem"}, {"label": "D", "text": "Because Systems Analysis replaces the need for Systems Thinking entirely"}]'::jsonb, 'A', 'The course structures these as two separate, substantial sections (5 lectures/50min and 5 lectures/52min respectively), implying they are related but distinct competencies.'),
  ('Systems Innovation', 10, 'Who does the course say this material is suited for?', '[{"label": "A", "text": "Anyone interested in trying to enable change within large organizations and systems"}, {"label": "B", "text": "Only certified data scientists"}, {"label": "C", "text": "Only marketing professionals"}, {"label": "D", "text": "Only entry-level employees with less than one year of experience"}]'::jsonb, 'A', 'The "Who this course is for" section states it is "suited for anyone who is interested in trying to enable change within large organizations and system."'),
  ('Introduction to Design Thinking', 1, 'What 5-step design thinking process does this course teach, and where does it originate?', '[{"label": "A", "text": "Empathize, Define, Ideate, Prototype, and Test — developed at Stanford''s Hasso Plattner Institute of Design"}, {"label": "B", "text": "A 5-step process invented by the instructor with no academic origin"}, {"label": "C", "text": "A process with only 2 steps: Build and Ship"}, {"label": "D", "text": "The course teaches no structured step sequence"}]'::jsonb, 'A', 'The course explicitly teaches "The 5-Step design thinking process developed by Stanford University" (Hasso Plattner Institute of Design), naming Empathize, Define, Ideate, Prototype, and Test as the steps.'),
  ('Introduction to Design Thinking', 2, 'What three major design constraints does the course teach?', '[{"label": "A", "text": "Desirability, Feasibility, and Viability"}, {"label": "B", "text": "Speed, Cost, and Color"}, {"label": "C", "text": "Legal, Marketing, and Sales"}, {"label": "D", "text": "The course does not name specific design constraints"}]'::jsonb, 'A', 'The description explicitly names "the three major design constraints--Desirability, Feasibility and Viability--and how they interact."'),
  ('Introduction to Design Thinking', 3, 'What is a "persona" in the context of this course?', '[{"label": "A", "text": "A tool developed during the Define step to represent a type of user, informed by empathy work"}, {"label": "B", "text": "A synonym for an org chart position"}, {"label": "C", "text": "A legal document unrelated to user research"}, {"label": "D", "text": "The course does not cover personas"}]'::jsonb, 'A', '"Personas and Persona Development" and a "Persona Practice Exercise" are named lectures, positioned after Empathize and Define in the course sequence.'),
  ('Introduction to Design Thinking', 4, 'What is Kano''s Model of Customer Satisfaction, per the course?', '[{"label": "A", "text": "A model covered in a dedicated lecture, used to understand and categorize customer satisfaction factors"}, {"label": "B", "text": "A financial forecasting spreadsheet template"}, {"label": "C", "text": "A synonym for the 5-step design process itself"}, {"label": "D", "text": "The course does not mention this model"}]'::jsonb, 'A', '"Kano''s Model of Customer Satisfaction" is a named lecture in the course, distinct from but related to the persona and empathy work.'),
  ('Introduction to Design Thinking', 5, 'What does the course teach about unconscious biases?', '[{"label": "A", "text": "It covers them explicitly, including a \"Glossary of Unconscious Biases\" lecture, as a hazard to be aware of during design thinking"}, {"label": "B", "text": "It claims unconscious bias is not relevant to design work"}, {"label": "C", "text": "It only mentions bias in a single throwaway sentence with no dedicated content"}, {"label": "D", "text": "It teaches that biases should be intentionally leveraged rather than mitigated"}]'::jsonb, 'A', 'The course lists "The hazard of unconscious biases" as a learning objective and includes both an "Unconscious Biases" lecture and a "Glossary of Unconscious Biases" lecture.'),
  ('Introduction to Design Thinking', 6, 'What does the course teach about the value of prototyping?', '[{"label": "A", "text": "That prototyping throughout the design process lowers cost and risk, and it distinguishes low-fidelity from high-fidelity prototypes"}, {"label": "B", "text": "That prototyping should always be skipped to save time"}, {"label": "C", "text": "That only high-fidelity prototypes have any value"}, {"label": "D", "text": "The course does not address prototyping"}]'::jsonb, 'A', 'The course explicitly teaches "the value of prototyping and iteration" and "Low-fi versus Hi-fi prototypes," along with how prototyping lowers cost and risk.'),
  ('Introduction to Design Thinking', 7, 'A Specialist is asked to fix a recurring support complaint but keeps hearing a proposed fix described as "technically impossible" by engineering, "too costly" by finance, and "not what customers actually want" by CS. Which course concept directly names this three-way tension?', '[{"label": "A", "text": "The three design constraints — Feasibility, Viability, and Desirability — which interact and must be balanced"}, {"label": "B", "text": "The 5-Whys technique, which is unrelated to constraint balancing"}, {"label": "C", "text": "Kano''s Model, which only concerns pricing, not feasibility or desirability"}, {"label": "D", "text": "The course does not address competing constraints of this kind"}]'::jsonb, 'A', 'This scenario is exactly what the course''s three design constraints (technological/business/human-centered — feasibility, viability, desirability) are meant to name and reconcile.'),
  ('Introduction to Design Thinking', 8, 'A Specialist drafts a persona for "the typical customer" based only on their own assumptions, without talking to any real customers. What would the course say is missing?', '[{"label": "A", "text": "The Empathize step, since personas should be grounded in real empathy work/data about actual users, not just assumptions"}, {"label": "B", "text": "Nothing is missing; personas are meant to be built purely from assumptions"}, {"label": "C", "text": "The Prototype step, which has no relationship to persona accuracy"}, {"label": "D", "text": "The course says personas should never be based on any real user data"}]'::jsonb, 'A', 'The course sequences Empathize before Define/Personas specifically because personas are meant to be informed by genuine empathy-based understanding of users, not assumption alone.'),
  ('Introduction to Design Thinking', 9, 'Why does the course pair active listening with the later stages of design thinking, rather than treating it as a stand-alone soft skill?', '[{"label": "A", "text": "Because effective empathy, testing, and iteration all depend on genuinely hearing user feedback, which active listening supports throughout the process, not just at the start"}, {"label": "B", "text": "Because active listening is described as relevant only to the Prototype step"}, {"label": "C", "text": "Because the course claims active listening has no bearing on design thinking outcomes"}, {"label": "D", "text": "Because active listening is presented as a replacement for the entire 5-step process"}]'::jsonb, 'A', '"Active Listening" appears late in the course content, right before the closing lectures, reinforcing that it supports Test/iteration as much as the initial Empathize step.'),
  ('Introduction to Design Thinking', 10, 'Who does the course explicitly list as its intended audience?', '[{"label": "A", "text": "Product Managers, Process/Manufacturing/Quality Engineers, UX Designers, Business Analysts, Continuous Improvement Specialists, and professionals moving into leadership"}, {"label": "B", "text": "Only professional graphic designers"}, {"label": "C", "text": "Only C-suite executives"}, {"label": "D", "text": "Only customers themselves, not internal staff"}]'::jsonb, 'A', 'The "Who this course is for" section lists exactly this broad set of roles.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 1, 'From a customer-impact perspective, what problem does the API + webhooks/triggered-actions layered architecture ultimately solve for a customer?', '[{"label": "A", "text": "It lets a customer keep their other business systems automatically in sync with Skedulo, without manual re-entry or constant polling"}, {"label": "B", "text": "It exists purely for Skedulo engineering, with no customer-facing benefit"}, {"label": "C", "text": "It only benefits Salesforce-based customers, never Pulse Platform customers"}, {"label": "D", "text": "It replaces the need for the customer to use the Skedulo web app at all"}]'::jsonb, 'A', 'The layered architecture (API connectivity + reactive automation + embedded logic) exists so customer systems can integrate and react automatically — directly reducing manual customer effort.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 2, 'A customer complains their team has to manually check Skedulo every hour for job status changes to update their own CRM. Which capability, framed around customer impact, directly solves this pain point?', '[{"label": "A", "text": "Webhooks/Triggered Actions — automatically pushing/reacting to changes, eliminating manual polling"}, {"label": "B", "text": "The Skedulo CLI — for deploying custom artifacts"}, {"label": "C", "text": "The Object Reference documentation alone"}, {"label": "D", "text": "Skedulo Functions — for embedding logic in mobile extensions only"}]'::jsonb, 'A', 'This is precisely the event-driven automation use case: eliminating the customer''s need to manually poll for changes.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 3, 'Why does Salesforce-specific integration (Apex-based API calls) get special attention in this overview, from a customer-experience standpoint?', '[{"label": "A", "text": "Because Skedulo for Salesforce customers are a major segment whose systems need bidirectional, native-feeling communication with Skedulo"}, {"label": "B", "text": "Because Salesforce customers don''t actually need integration support"}, {"label": "C", "text": "Because it''s being phased out and customers should avoid it"}, {"label": "D", "text": "Because it''s identical in every way to the generic REST API, with no special customer consideration"}]'::jsonb, 'A', 'The overview singles this out because Salesforce customers are a major, dedicated integration target needing tailored (Apex-based) support.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 4, 'A customer wants a custom mobile experience that embeds their own business logic without waiting on Skedulo engineering for every change. Which capability serves that need, and why does it matter to the customer?', '[{"label": "A", "text": "Skedulo Functions — it lets the customer''s own team embed and control custom logic directly, increasing their autonomy and reducing turnaround time"}, {"label": "B", "text": "Webhooks — since they exist purely for outbound notifications"}, {"label": "C", "text": "The REST API alone, since functions require a Skedulo engineering ticket every time"}, {"label": "D", "text": "This isn''t possible via any integration capability"}]'::jsonb, 'A', 'Functions let a customer/partner embed custom logic directly, which — from a customer-first standpoint — reduces dependency on Skedulo engineering for every tweak.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 5, 'A customer asks ''why do I need webhooks if I already have API access?'' What''s the customer-centric answer based on this overview''s layered model?', '[{"label": "A", "text": "The API lets them pull data on demand; webhooks let their systems react immediately to changes without the customer''s team having to ask for it — the two serve different needs"}, {"label": "B", "text": "Webhooks are simply a slower version of the API with no real benefit"}, {"label": "C", "text": "Webhooks replace the API entirely, so having both is redundant"}, {"label": "D", "text": "API access alone already replicates everything webhooks provide"}]'::jsonb, 'A', 'This reflects the layered architecture: APIs for on-demand connectivity, webhooks/triggered actions for automatic, immediate reaction — each solving a different customer workflow need.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 6, 'A customer is frustrated that a critical business process depends on someone remembering to manually check Skedulo daily. Which architectural layer, explained in customer terms, most directly reduces this operational burden?', '[{"label": "A", "text": "Event-driven automation via Webhooks/Triggered Actions"}, {"label": "B", "text": "The Object Reference documentation"}, {"label": "C", "text": "The Skedulo CLI"}, {"label": "D", "text": "Manual data exports"}]'::jsonb, 'A', 'This layer exists specifically to remove the customer''s need for manual, recurring checks by reacting to changes automatically.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 7, 'From a customer''s point of view, why might it matter that Skedulo documents these four integration topics as a connected ''architecture'' rather than four unrelated features?', '[{"label": "A", "text": "It helps a customer''s technical team choose the right combination of layers (data access + automation + custom logic) for their specific workflow, instead of guessing at one feature in isolation"}, {"label": "B", "text": "It doesn''t matter — customers never read developer documentation"}, {"label": "C", "text": "It matters only for Skedulo''s internal engineering roadmap, not customer decision-making"}, {"label": "D", "text": "The four topics are actually unrelated and the ''architecture'' framing is misleading"}]'::jsonb, 'A', 'Framing these as a layered architecture helps a customer''s technical stakeholders design an integration that combines the right layers for their actual need.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 8, 'A customer''s Salesforce admin wants Salesforce Flow to call Skedulo directly using declarative tools rather than custom Apex. Is that fully covered by the ''Making calls to the Skedulo API from Salesforce using Apex'' section, and what should support clarify?', '[{"label": "A", "text": "Not entirely — that section is specifically Apex-based; a no/low-code Flow-based approach may need a different pattern, so support should clarify the customer''s actual technical approach before pointing them to Apex-specific docs"}, {"label": "B", "text": "Yes, Apex and Flow are described as identical in this documentation"}, {"label": "C", "text": "No, Salesforce customers cannot call the Skedulo API under any circumstances"}, {"label": "D", "text": "This is irrelevant — Flow cannot call external APIs at all"}]'::jsonb, 'A', 'The documented section is explicitly framed around Apex-based calls; a support specialist should confirm whether the customer''s team is coding in Apex or using declarative Flow tooling before directing them, since the guidance differs.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 9, 'A customer''s leadership asks the support team to justify why their integration project needs both API work AND a Skedulo Functions component. What''s a customer-first way to explain this using the layered model?', '[{"label": "A", "text": "The API layer handles moving/accessing data; Functions let the customer embed logic Skedulo doesn''t natively provide — together they cover both ''connectivity'' and ''customization'' needs"}, {"label": "B", "text": "Functions and APIs do the exact same thing, so only one is truly needed"}, {"label": "C", "text": "This combination is never necessary in practice"}, {"label": "D", "text": "APIs are only for reporting, and Functions are only for authentication"}]'::jsonb, 'A', 'This reflects the layered architecture accurately: APIs for connectivity, Functions for embedding custom logic — distinct, complementary needs, which is a clear way to justify the investment to customer leadership.'),
  ('Skedulo Developer Guide — Integration and Automation (customer-impact lens)', 10, 'A customer says they ''just want Skedulo to talk to their system automatically'' without specifying more. What should a customer-first support response do first, given these four overlapping capabilities?', '[{"label": "A", "text": "Ask clarifying questions about their actual workflow (pull vs. push, real-time vs. periodic, custom logic needs) before recommending a specific layer, rather than assuming which of the four fits"}, {"label": "B", "text": "Immediately recommend Skedulo Functions regardless of their actual need"}, {"label": "C", "text": "Tell them integration isn''t possible without more Salesforce licenses"}, {"label": "D", "text": "Point them only at the API Reference Guide with no further discussion"}]'::jsonb, 'A', 'Given that APIs, webhooks/triggered actions, Salesforce-specific calls, and Functions each solve a different kind of need, a customer-first response clarifies the actual workflow before recommending one — avoiding a mismatched solution.'),
  ('Customer Success | How to Exceed Your Customers Expectations', 1, 'What does the course say a company needs beyond low prices to have a real competitive advantage?', '[{"label": "A", "text": "Value — though the course notes value \"may not be what you''ve been led to believe it really is\""}, {"label": "B", "text": "Only aggressive advertising spend"}, {"label": "C", "text": "Only a larger sales team"}, {"label": "D", "text": "The course claims low prices alone are always sufficient"}]'::jsonb, 'A', 'The description opens by stating a company "needs a competitive advantage much bigger than just low prices. That advantage is value. But value may not be what you''ve been led to believe it really is."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 2, 'What framework does the course use to explain how customers decide what they truly need from a product?', '[{"label": "A", "text": "\"Jobs to Be Done\" thinking"}, {"label": "B", "text": "A simple price-comparison spreadsheet"}, {"label": "C", "text": "The 5 Whys technique"}, {"label": "D", "text": "The course does not address how customers decide what they need"}]'::jsonb, 'A', '"Jobs to Be Done" is an explicit named lecture and learning point, described as thinking that "will revolutionize your company."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 3, 'Which named case study illustrates using customer insight to design an entirely new product?', '[{"label": "A", "text": "Hyundai Motors"}, {"label": "B", "text": "A fictional, unnamed company invented for the course"}, {"label": "C", "text": "McDonald''s, used only for pricing strategy"}, {"label": "D", "text": "Costco, used only for supply chain logistics"}]'::jsonb, 'A', 'The course includes a dedicated "Hyundai Case Study" lecture, explicitly framed as "how Hyundai Motors used customer insight to create an entirely new vehicle."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 4, 'What concept does the course teach for evaluating the true, long-term worth of a customer relationship?', '[{"label": "A", "text": "Customer Lifetime Value"}, {"label": "B", "text": "Quarterly revenue alone, with no longer-term view"}, {"label": "C", "text": "Net Promoter Score exclusively"}, {"label": "D", "text": "The course does not address customer valuation"}]'::jsonb, 'A', '"Customer Lifetime Value" is an explicit named lecture, described as something that "will change the way you evaluate the real value of your customers."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 5, 'What does the Costco case study in this course illustrate?', '[{"label": "A", "text": "How Costco delivers extreme value to millions of customers"}, {"label": "B", "text": "How Costco failed to retain customers"}, {"label": "C", "text": "A case study unrelated to customer value"}, {"label": "D", "text": "The course does not include a Costco case study"}]'::jsonb, 'A', 'The course includes a "Costco Case Study" lecture explicitly framed around "how Costco delivers extreme value to millions of customers."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 6, 'What does the course call the concept describing every customer''s journey "from expectation to loyalty"?', '[{"label": "A", "text": "The Value Universe"}, {"label": "B", "text": "The Sales Funnel"}, {"label": "C", "text": "The Net Promoter Score"}, {"label": "D", "text": "The course does not name this concept"}]'::jsonb, 'A', '"The Value Universe" is an explicit named lecture, described as affecting "every customer on their journey from expectation to loyalty."'),
  ('Customer Success | How to Exceed Your Customers Expectations', 7, 'A Principal Specialist is asked why the team''s roadmap should prioritize a small, easy-to-miss pain point that a segment of long-tenured customers keeps mentioning. Which course concept most directly supports weighing this against short-term, flashier wins?', '[{"label": "A", "text": "Customer Lifetime Value, which reframes the evaluation around the long-term worth of retaining and satisfying that customer segment, not just the immediate ask"}, {"label": "B", "text": "Only the Hyundai case study, which is unrelated to prioritization tradeoffs"}, {"label": "C", "text": "The course provides no framework for this kind of prioritization tradeoff"}, {"label": "D", "text": "The Value Universe, which the course says applies only to brand-new customers"}]'::jsonb, 'A', 'Customer Lifetime Value is exactly the course''s tool for evaluating a customer relationship''s real, long-term worth, which supports weighing a persistent long-tenured pain point against short-term flashier work.'),
  ('Customer Success | How to Exceed Your Customers Expectations', 8, 'A Principal Specialist is designing a new self-service support feature and wants to avoid building something customers don''t actually need, even if it sounds impressive on paper. Which course framework should guide the requirements discussion?', '[{"label": "A", "text": "\"Jobs to Be Done\" thinking, which focuses on the underlying need a customer is trying to satisfy, not just surface-level feature requests"}, {"label": "B", "text": "The Value Universe, which the course frames as unrelated to feature scoping"}, {"label": "C", "text": "The Costco case study, which only concerns retail membership pricing"}, {"label": "D", "text": "The course does not provide any framework relevant to feature scoping"}]'::jsonb, 'A', '"Jobs to Be Done" thinking is specifically about identifying the real underlying need behind a customer''s request, which is exactly the risk this scenario is trying to avoid.'),
  ('Customer Success | How to Exceed Your Customers Expectations', 9, 'Why does the course pair concrete named case studies (Hyundai, McDonald''s, Costco) with more abstract frameworks like the Value Universe and Jobs to Be Done, rather than teaching the frameworks alone?', '[{"label": "A", "text": "Because seeing how real companies applied these concepts makes the otherwise abstract frameworks concrete and actionable for a learner''s own context"}, {"label": "B", "text": "Because the case studies are described as unrelated to the frameworks being taught"}, {"label": "C", "text": "Because the course claims frameworks alone are always sufficient without any real-world grounding"}, {"label": "D", "text": "Because the case studies are meant to replace the frameworks entirely, not illustrate them"}]'::jsonb, 'A', 'The course structure interleaves abstract frameworks (Value Universe, Jobs to Be Done, Customer Lifetime Value) with matching named case studies, which is a deliberate design choice to make the concepts concrete.'),
  ('Customer Success | How to Exceed Your Customers Expectations', 10, 'Who does the course say will benefit most from this material?', '[{"label": "A", "text": "Those who work with customers and are interested in marketing, market research, sales, customer service, and strategy"}, {"label": "B", "text": "Only certified financial analysts"}, {"label": "C", "text": "Only software engineers with no customer-facing responsibilities"}, {"label": "D", "text": "Only external auditors reviewing customer contracts"}]'::jsonb, 'A', 'The "Who this course is for" section states it is for those who "work with customers and are interested in the topics of marketing, market research, sales, customer service, and strategy."')
) as v(title, position, question, options, correct_answer, rationale)
join courses c on c.title = v.title and c.track_id = (select id from tracks where name = 'Core Competency')
on conflict (course_id, position) do nothing;
